window.POEM_DB=window.POEM_DB||{};POEM_DB["song_012"]={"n":"陈造","dyn":"宋","poems":[{"t":"游北山","f":"五言古诗","c":["有客可与游，阙酒得无病。","岂意四从事，过我不待请。","洗杓挹风度，免惭林花盛。","公学此味如，浑厚兼醇正。","公量虚谷如，有来良善应。","肯分兵厨沥，少佐笔力劲。","罢营杖头钱，徐取松间径。","登临旧能赋，七发踵枚乘。","此兴老未衰，西日尚馀映。","风怒雷再鼓，云破天一镜。","山花下野鸟，诗题一堪命。","府公文章伯，声称耸群听。","明朝倒锦囊，非是庶所订。","岂伊綵凤鸣，而聆露鹤警。","定知谢东山，凡百易子敬。"]},{"t":"八月十二日夜偕客赏木犀八首 其八","f":"七言绝句","c":["酒边先起未须扶，犹听槌床击唾壶。","风月撩人成不寝，隔墙却拟应歌呼。"]},{"t":"八月十二日夜偕客赏木犀八首 其七","f":"七言绝句","c":["人间雨恨更云愁，月殿仙娥替汝羞。","诗酹此觞坚后约，与人晴霁作中秋。"]},{"t":"八月十二日夜偕客赏木犀八首 其六","f":"七言绝句","c":["客间那不笑翁痴，酒处犹须古锦为。","不道诗成还玉雪，聊凭一解桂娥颐。"]},{"t":"八月十二日夜偕客赏木犀八首 其五","f":"七言绝句","c":["衰怀对客便超然，病骨枝梧胜去年。","未作槌腰摩腹想，尚堪渌蚁翠蛾前。"]},{"t":"八月十二日夜偕客赏木犀八首 其四","f":"七言绝句","c":["露颗零空冱欲冰，风姨收尽晚林声。","金波冷浸山河影，直为高阳酒伴明。"]},{"t":"八月十二日夜偕客赏木犀八首 其三","f":"七言绝句","c":["朋来济济尽嘉宾，饮兴翩翩笑语真。","绝胜谪仙邀月醉，当时和影祇三人。"]},{"t":"八月十二日夜偕客赏木犀八首 其二","f":"七言绝句","c":["谢兰潘璧少年场，玉麈金罍度夜央。","老子遽能忘此兴，且容投杖唤胡床。"]},{"t":"八月十二日夜偕客赏木犀八首 其一","f":"七言绝句","c":["冰蟾蜚下一天霜，领略岩花旖旎香。","我亦小园清绝处，与君同命醉为乡。"]},{"t":"十五夜再次赵帅韵","f":"七言绝句","c":["嘉宾饮兴未阑残，却倩纤纤奉雪团。","一笑举杯邀月姊，为渠聊贷广寒寒。"]},{"t":"十绝句呈章茂深安抚 其七","f":"七言绝句","c":["右史文章海倒流，淮南异政古人俦。","亲闻抚几推双美，独向夫君放一头。"]},{"t":"十绝句呈章茂深安抚 其八","f":"七言绝句","c":["楚城巉绝控穷边，楚俗伤弓未帖然。","一自并州烦李绩，不闻贵买渡江船。"]},{"t":"十绝句呈章茂深安抚 其三","f":"七言绝句","c":["三傍清淮酹酒杯，四年霜鬓犯风埃。","即今定被淮人笑，又见衰翁禄遫来。"]},{"t":"十绝句呈章茂深安抚 其一","f":"七言绝句","c":["雨馀凉气晓风沨，却爱朝阳一抹红。","照影芙蕖天与远，可能犹恨打头风。"]},{"t":"十绝句呈章茂深安抚 其五","f":"七言绝句","c":["诗伯于今第一流，清篇传诵到鳌头。","共推句法源流远，伯仲夔州只楚州。"]},{"t":"十绝句呈章茂深安抚 其四","f":"七言绝句","c":["追寻名胜剩留年，白首犹参五字禅。","寄语蜚廉亟回驭，拟凌风去访诗仙。"]},{"t":"十绝句呈章茂深安抚 其九","f":"七言绝句","c":["里社过逢起醉眠，行人鱼稻不论钱。","欲知劝课功多少，地覆黄云远接天。"]},{"t":"十绝句呈章茂深安抚 其二","f":"七言绝句","c":["忍馋留得可羹鱼，微沫相濡未就枯。","自解柳枝投渌水，劳生与汝各江湖。"]},{"t":"十绝句呈章茂深安抚 其六","f":"七言绝句","c":["密受眉山一印传，斯文千载石林仙。","使君酷似牢之舅，更喜鸾胶续此弦。"]},{"t":"十绝句呈章茂深安抚 其十","f":"七言绝句","c":["经纶术业向来优，千骑东方恐未俦。","他日应携报恩子，还朝看拜富民侯。"]},{"t":"十绝句寄赵帅 其七","f":"七言绝句","c":["从公日日醉中归，插鬓长分最好枝。","旧约何如趁新约，浪言灯夕胜花时。"]},{"t":"十绝句寄赵帅 其一","f":"七言绝句","c":["柳堤阴里放船开，识面人家首屡回。","莫讶春阳浮大宅，新陪诗伯唱酬来。"]},{"t":"十绝句寄赵帅 其十","f":"七言绝句","c":["每上平山把酒卮，海鸿泉骥满乌丝。","风流人物诗书帅，万字千钟更属谁。"]},{"t":"十绝句寄赵帅 其六","f":"七言绝句","c":["醉中记得新翻谱，土苴梁州笑石州。","火急归来传好事，为渠一洗世间愁。"]},{"t":"十绝句寄赵帅 其四","f":"七言绝句","c":["金田碧野把杯前，飞骑鸣弰簉玳筵。","五百年来逢此乐，府公今续谪仙弦。"]},{"t":"十绝句寄赵帅 其三","f":"七言绝句","c":["款陪仙伯燕池亭，不但新诗老眼明。","鼓吹激天飞鸟堕，旌幢点水睡龙惊。"]},{"t":"十绝句寄赵帅 其九","f":"七言绝句","c":["讼户无声日燕閒，驱驰风月笑谭间。","自今玉海添新集，与继当年大小山。"]},{"t":"十绝句寄赵帅 其八","f":"七言绝句","c":["子骏福星方久照，渔阳竹马省相迎。","他时薤水休重问，市虎晨羊各用情。"]},{"t":"十绝句寄赵帅 其五","f":"七言绝句","c":["豪竹哀丝荐玉觞，羽衣仙袂俨分行。","酡颜一为东君笑，媚白妖红不敢芳。"]},{"t":"又次看字韵二首 其二","f":"七言绝句","c":["明年屈指春来早，定是元宵不苦寒。","十里珠帘火城夜，客来应许醉中看。"]},{"t":"又次看字韵二首 其一","f":"七言绝句","c":["谁扶璧月上天端，雪魄扬辉桂影寒。","照见群仙拥仙伯，嫦娥定复转头看。"]},{"t":"又次铦朴翁韵四首 其四","f":"七言绝句","c":["几向西湖舣画桡，冰奁俨受众峰朝。","即今去雁将清梦，飞下长桥更短桥。"]},{"t":"又次铦朴翁韵四首 其三","f":"七言绝句","c":["婪酣贵宦鲛绡帐，赑屃功名泊浪沙。","谁似朴翁随分过，曹溪水煮赵州茶。"]},{"t":"又次铦朴翁韵四首 其二","f":"七言绝句","c":["闻为诗魔掩贝多，辞源衮衮倒洪河。","遥知传诵日千纸，淇上高唐无善歌。"]},{"t":"又次铦朴翁韵四首 其一","f":"七言绝句","c":["僧床正听晓楼钟，客棹方占上水风。","喧静未须岐出处，与渠心事各冥鸿。"]},{"t":"又次韵二首 其一","f":"七言绝句","c":["愁为离群老不禁，诗来深得故人心。","自摩病眼添沈炷，满纸晶荧玩碎金。"]},{"t":"口号十首呈程殿撰 其二","f":"七言绝句","c":["欢意长随夜漏长，隆宽尽贷酒边狂。","东归祇有南窗梦，夜夜掀髯锦瑟傍。"]},{"t":"口号十首呈程殿撰 其七","f":"七言绝句","c":["公家昆季尽时贤，叔也骅骝拟度前。","书谂亲庭先静退，至今文采照林泉。"]},{"t":"口号十首呈程殿撰 其九","f":"七言绝句","c":["故人折柳送东辕，不羡当年李郭船。","囊锦鸱夷有供给，自疑身是御风仙。"]},{"t":"口号十首呈程殿撰 其五","f":"七言绝句","c":["福地常披十幅图，仙翁隐处玉为壶。","九华山侧双峰下，还许侬分半席无。"]},{"t":"口号十首呈程殿撰 其三","f":"七言绝句","c":["八月襄城暑始回，水仙争趁玉梅开。","当时二物知天意，共报公家福鼎来。"]},{"t":"口号十首呈程殿撰 其十","f":"七言绝句","c":["帝所乡关等是家，奚囊纳纳尽天葩。","西湖久待公题品，莫遣波神妒九华。"]},{"t":"口号十首呈程殿撰 其四","f":"七言绝句","c":["芳信飞来自月宫，月中桂茂劣能容。","素娥封殖非无意，准拟公家不尽供。"]},{"t":"口号十首呈程殿撰 其一","f":"七言绝句","c":["白璧明玑每堕前，续貂辄复耸双肩。","一从归作漳滨卧，不寄诗筒恰五年。"]},{"t":"口号十首呈程殿撰 其六","f":"七言绝句","c":["郎君衮绣照鸳行，诗老时须住帝乡。","即见翘材辟新馆，预应绿野敞深堂。"]},{"t":"马援","f":"七言绝句","c":["朱勃风标似可亲，文渊竟作白头新。","平时轻侮知何事，辨雪冤诬独此人。"]},{"t":"不寐二首 其二","f":"七言绝句","c":["追思可乐是丁年，日力孳孳有食眠。","头触屏风祇灯后，慈亲笑劝掩陈编。"]},{"t":"不寐二首 其一","f":"七言绝句","c":["改遍年来所著书，依然幽梦隔华胥。","寒更何与衰翁事，数到琤摐杀点馀。"]},{"t":"书事二首 其二","f":"七言绝句","c":["苦吟添满镜中丝，课效全输博塞嬉。","改就新诗哦百过，浪言儿辈不须知。"]},{"t":"书事二首 其一","f":"七言绝句","c":["壮年肤骨已清臞，老去支离转不如。","二十七年扶病过，半缘耽酒半耽书。"]},{"t":"书南柯太守曲后二首 其二","f":"七言绝句","c":["竹叶舟前客念家，慈云瓮里事如麻。","而今不笑檀槐战，笑汝研桑了岁华。"]},{"t":"书南柯太守曲后二首 其一","f":"七言绝句","c":["门前车马竞飞驰，等是槐安未寐时。","何似阿怜歌此曲，一卮随分得伸眉。"]},{"t":"书城北尼庵二首 其二","f":"七言绝句","c":["诸郎弓力胜黄间，中戟穿杨气貌闲。","乐府新传杀胡谶，看君飞矢下阴山。"]},{"t":"书城北尼庵二首 其一","f":"七言绝句","c":["小摇蛇影鸟惊堕，已落背毛牛自如。","瞢欲分朋惭老病，与渠甘作典筹舒。"]},{"t":"予七十赵监税见贺以诗次韵","f":"五言绝句","c":["平生烛之武，况已雪髯翁。","誉我犹时用，君言恐未公。"]},{"t":"元夕遣怀二首 其二","f":"七言绝句","c":["平世计功须壮岁，异时敌己尽亨涂。","鬓须久已沾青女，穷达何劳问紫姑。"]},{"t":"元夕遣怀二首 其一","f":"七言绝句","c":["陆海莲开夜色鲜，短檠灯下掩陈编。","风姨竟日鸣条罢，月姊因谁得意圆。"]},{"t":"公孙述","f":"七言绝句","c":["东来温诏枉丁宁，隆少忠谋肯汝聆。","不待宾胪延马援，始知西帝偶人形。"]},{"t":"六绝句呈赵帅兼简郑机宜 其六","f":"七言绝句","c":["长日登临忆侍郎，芳时谭笑客凝香。","须公多办琼花露，容我时开古锦囊。"]},{"t":"六绝句呈赵帅兼简郑机宜 其五","f":"七言绝句","c":["蒲鞭閤束久停檛，暮府人闲早放衙。","频唤羊何把诗笔，即看姚魏用年华。"]},{"t":"六绝句呈赵帅兼简郑机宜 其一","f":"七言绝句","c":["南徐把酒送行行，话我漂零倍怆情。","屈指六年才一梦，更消几梦了浮生。"]},{"t":"六绝句呈赵帅兼简郑机宜 其三","f":"七言绝句","c":["雁塔题名尽俊贤，即今十八卧重泉。","合离荣瘁何须较，强健相过是半仙。"]},{"t":"六绝句呈赵帅兼简郑机宜 其二","f":"七言绝句","c":["玉笋班中第一流，冰花影里釂琼舟。","来迟输与花前客，袖手看公笔不休。"]},{"t":"六绝句呈赵帅兼简郑机宜 其四","f":"七言绝句","c":["宦路平时欲陆沉，先生诲语每南金。","长庚配月空回首，古井无波已此心。"]},{"t":"孔明二首 其二","f":"七言绝句","c":["搴蜀宁蛮走阿瞒，功名继此坐天悭。","平生囊括华夷策，畏虎才教见一斑。"]},{"t":"孔明二首 其一","f":"七言绝句","c":["古今深忌忿为兵，及霤师臣要力争。","白帝败归思孝直，端知难抗魏元成。"]},{"t":"文帝","f":"七言绝句","c":["君王俭德本天然，萧相鸠营已造天。","不见千门并万户，露台虽罢未为贤。"]},{"t":"无题","f":"七言绝句","c":["多誉庸非蠲忿草，一谦良是辟兵符。","先生謦欬忘鸡口，俗子过逢动虎须。"]},{"t":"无题三首 其二","f":"七言绝句","c":["才不时宜懒治生，学专信已一官轻。","只今尚友须千载，独惜时无尚子平。"]},{"t":"无题三首 其三","f":"七言绝句","c":["居为耕叟出为官，出处人将二致看。","朝市山林俱乐地，却须神武挂衣冠。"]},{"t":"无题三首 其一","f":"七言绝句","c":["酒鸱车后无何饮，易卷床头脱复看。","岂谓浮生须此具，世纷方解不相干。"]},{"t":"王逢原二首 其二","f":"七言绝句","c":["文章俯睨汉唐馀，属思深湛到古初。","正使玉楼须有记，忍令银笔嗣无书。"]},{"t":"王逢原二首 其一","f":"七言绝句","c":["弱岁文推一代豪，诸公敛衽看颠毛。","天于屈宋应为地，不放先生仆命骚。"]},{"t":"东庄小留四首 其四","f":"七言绝句","c":["接屋连墙翠密中，炊香羹玉饱过从。","人将逋客为同社，地与斜川作附庸。"]},{"t":"东庄小留四首 其三","f":"七言绝句","c":["亲朋樽俎日周旋，无限欢情到酒边。","底许挤排作尊客，祇令抚己叹衰年。"]},{"t":"东庄小留四首 其二","f":"七言绝句","c":["夹沟欲插柳千株，绕舍先营五亩蔬。","供爨禦冬须次第，西归新得务农书。"]},{"t":"东庄小留四首 其一","f":"七言绝句","c":["南陂荒茀已成围，北墅田租颇应期。","两地径规般薄地，小为庵屋大为池。"]},{"t":"东坡二首 其二","f":"七言绝句","c":["高文鲠论博艰危，凛凛声名百世垂。","得意王公莽枯冢，谁令圣主想同时。"]},{"t":"东坡二首 其一","f":"七言绝句","c":["五载诗鸣卧雪堂，暮年长啸走南荒。","当时戏綵慈亲侧，岂复陈编羡范滂。"]},{"t":"四月望再游西湖十首 其十","f":"七言绝句","c":["横逵纵径平如水，无复冲泥防险人。","傥使人心尽包叟，世间何向不通津。"]},{"t":"四月望再游西湖十首 其九","f":"七言绝句","c":["歌呼浩渺翠霏间，祇苦诗才老坐悭。","安得观音母陁手，为人千纸写湖山。"]},{"t":"四月望再游西湖十首 其八","f":"七言绝句","c":["春光陆续委东流，看到湖边安石榴。","更与苏堤鸥鹭约，办舟来赏牡丹秋。"]},{"t":"四月望再游西湖十首 其七","f":"七言绝句","c":["堆青泛碧放船篷，万里风前鹤发翁。","绝境满前官不禁，此身未省叹涂穷。"]},{"t":"四月望再游西湖十首 其六","f":"七言绝句","c":["定结诸山粥饭缘，每归留得杖头钱。","穿云更欲携君去，布水多烦为我先。"]},{"t":"四月望再游西湖十首 其五","f":"七言绝句","c":["十字街头托钵盂，雁鹅食口待朝晡。","我来欲序睽违意，要问扬州米价无。"]},{"t":"四月望再游西湖十首 其四","f":"七言绝句","c":["杖挑初日闯云关，忽报充师早下山。","煮茗谭诗有贤子，免教题凤怅空还。"]},{"t":"四月望再游西湖十首 其三","f":"七言绝句","c":["畴昔相期襆被来，饭馀归意类挤排。","蘋风萝月孤清夜，仅见山间结夏斋。"]},{"t":"四月望再游西湖十首 其二","f":"七言绝句","c":["杰屋修垣著画图，连连胜士逸人居。","乘闲我亦无羁束，竹杖芒鞋信所如。"]},{"t":"四月望再游西湖十首 其一","f":"七言绝句","c":["前时小舫冒氛昏，重到轻桡破曲尘。","湖面风烟饱姿态，一番到眼一番新。"]},{"t":"汉江岸二首 其二","f":"七言绝句","c":["沙随秋涨漫川原，沙外人家尽毁垣。","寄语饥羸莫深恨，西人无数饱鱼鼋。"]},{"t":"汉江岸二首 其一","f":"七言绝句","c":["一自阳侯战雨师，枣畦桑陇但空陂。","此君屹立如尊勇，依旧青青似昔时。"]},{"t":"示阿泰三首 其三","f":"七言绝句","c":["老稚悬知乐有馀，迎门先问小于菟。","风烟满眼山环海，对酒还曾斲句无。"]},{"t":"示阿泰三首 其二","f":"七言绝句","c":["官上依然四壁空，讼庭人寂每从容。","看家不为穿窬计，老去登临分外慵。"]},{"t":"示阿泰三首 其一","f":"七言绝句","c":["曾倚新晴望海天，天容海色湛相鲜。","奁中遥点群鸦影，万舶千艘忽过前。"]},{"t":"光武二首 其二","f":"七言绝句","c":["闭关谢质保丰功，建武规模见祖风。","宰辅骈诛非细故，平章敢谓茂陵同。"]},{"t":"光武二首 其一","f":"七言绝句","c":["济业何关赤伏符，王梁不拜未云疏。","君王幸却东封请，底事终身溺谶书。"]},{"t":"再次交代韵四首 其四","f":"七言绝句","c":["传闻洞府锁高青，探著诗成数启扃。","相见群仙书玉叶，更应交口叹精灵。"]},{"t":"再次交代韵四首 其一","f":"七言绝句","c":["嗣皇仁覆物昭苏，皋自陈谟鲧自吁。","闻道诸公扶国论，须君左袒订邦诬。"]},{"t":"再次交代韵四首 其三","f":"七言绝句","c":["漫叟当年臼作樽，侑樽青嶂漫嶙峋。","与君屡共山前醉，似觉清欢胜昔人。"]},{"t":"再次交代韵四首 其三","f":"七言绝句","c":["环秀亭中命渌樽，云烟明灭映嶙峋。","佐州不喜分风月，喜与南山作主人。"]},{"t":"再次交代韵四首 其四","f":"七言绝句","c":["诗人妙思天同巧，鬼守玄关不及扃。","闲挹山光诵奇语，断无尘滓溷襟灵。"]},{"t":"再次交代韵四首 其二","f":"七言绝句","c":["今朝著我簿书堆，领客樽罍未办开。","始信南山是知己，露奇呈秀斩关来。"]},{"t":"再次羊羔酒韵三首 其三","f":"七言绝句","c":["他时阿奋辞髯簿，来作东风席上珍。","安得方平鞭乱石，百觚陆续丐吾人。"]},{"t":"再次羊羔酒韵三首 其二","f":"七言绝句","c":["莱子杯盘别样香，春浮亲面日相羊。","老夫底幸沾馀沥，却笑无鱼客孟尝。"]},{"t":"再次羊羔酒韵三首 其一","f":"七言绝句","c":["元放诸孙怜遽许，截肪醉骨荐馨香。","茂先九酝犹须问，自是诗翁石作肠。"]},{"t":"再次还鹤韵三首 其三","f":"七言绝句","c":["人家往往琴堪劈，谁定如翁肯放回。","他日飙轮驷修翮，衔恩当复誓云来。"]},{"t":"再次还鹤韵三首 其二","f":"七言绝句","c":["啅鹊却陪新饮啄，啼猿俨识旧容仪。","可须辩士诳荆楚，似喜逐臣还秭归。"]},{"t":"再次还鹤韵三首 其一","f":"七言绝句","c":["朅来室迩念人遐，回首青田几许赊。","飞去定惊鱼荡水，跫然今似客还家。"]},{"t":"再次前韵三首 其三","f":"七言绝句","c":["茗瓯对客乳花浓，静听挥犀发异同。","度腊迎春如此过，不知人世有王公。"]},{"t":"再次前韵三首 其二","f":"七言绝句","c":["连夜愁阴苦戒严，雪将寒雨斗廉纤。","老人冻饿人情断，米价何如酒价添。"]},{"t":"再次前韵三首 其一","f":"七言绝句","c":["春事兼回寂寞滨，茅檐背日已书勋。","径须引睡携黄奶，未办寻芳命紫君。"]},{"t":"再次寄肯堂韵五首 其三","f":"七言绝句","c":["枝筇过我海云边，空谷人声喜欲颠。","更喜重逢各强健，未须悽惋话彫年。"]},{"t":"再次寄肯堂韵五首 其一","f":"七言绝句","c":["梦思游览慰衰迟，起耐阴寒不自持。","捉笔把杯吾技痒，可堪袖手过花时。"]},{"t":"再次寄肯堂韵五首 其四","f":"七言绝句","c":["倦游祇有囊诗锦，试为高人一笑开。","当日留题海山寺，旋闻石刻暗莓苔。"]},{"t":"再次寄肯堂韵五首 其四","f":"七言绝句","c":["眼向朱门每懒抬，今朝笑口为君开。","别来却喜人争席，浪遣长须扫径苔。"]},{"t":"再次寄肯堂韵五首 其一","f":"七言绝句","c":["住山今日得宗师，妙与缁徒示总持。","衣钵更缘延客尽，衲衣包却郑当时。"]},{"t":"再次寄肯堂韵五首 其五","f":"七言绝句","c":["精蓝端未下云居，况复僧中有后湖。","理障禅那俱坐断，颇尝游戏到诗无。"]},{"t":"再次寄肯堂韵五首 其三","f":"七言绝句","c":["共谭诗律更谭禅，人指昌黎接大颠。","屏叠葛藤烧笔砚，息阴休影了残年。"]},{"t":"再次寄肯堂韵五首 其五","f":"七言绝句","c":["好在新居胜旧居，右连灵隐面西湖。","东南胜境谁同领，我亦闲官一事无。"]},{"t":"再次寄肯堂韵五首 其二","f":"七言绝句","c":["道人心地古为徒，野鹤昂藏白月孤。","我亦生来世缘薄，回思昏宦叹非夫。"]},{"t":"再次寄肯堂韵五首 其二","f":"七言绝句","c":["丈室云趋彼岂徒，拳拳此意忍容孤。","即今又举二三语，说似当年邑大夫。"]},{"t":"再次韵 其二","f":"七言绝句","c":["微风不放浪纹长，噞暖跳鱼三尺黄。","祇欠高荷护千袜，醉妆浓艳媚斜阳。"]},{"t":"再次韵","f":"七言绝句","c":["二子峨冠共我长，即看紫绶映银黄。","不须握手论家谱，更举宣尼与伯阳。"]},{"t":"再次韵三首 其三","f":"七言绝句","c":["连朝飞雨暗群山，局步修廊广霤间。","会作闲人留十日，当令屐齿遍苔班。"]},{"t":"再次韵三首 其二","f":"七言绝句","c":["俗尘我亦怜多病，道价师今重五天。","投老鼎山追旧约，未妨林壑著臞仙。"]},{"t":"再次韵三首 其一","f":"七言绝句","c":["得君清句我愁无，不惜长哦缺唾壶。","句法森严谁到此，了知岛可但中涂。"]},{"t":"再次到房交代招饮韵四首 其三","f":"七言绝句","c":["荦确悍顽经数驿，醒然初挹碧嶙峋。","眼明骤与真山晤，不比逃虚见似人。"]},{"t":"再次韵四首 其三","f":"七言绝句","c":["到眼浪岐官冷热，遇人传得酒逡巡。","曼容东老俱通梦，不劝趋荣劝养神。"]},{"t":"再次到房交代招饮韵四首 其二","f":"七言绝句","c":["语不能工恨作堆，撚髭空对翠屏开。","清吟赖有雕龙手，绣段联翩诏后来。"]},{"t":"再次韵四首 其一","f":"七言绝句","c":["公朝已后茹茅连，幕府偷闲亦所天。","宠辱肯为差别观，道人随寓祇怡然。"]},{"t":"再次交代韵四首 其三","f":"七言绝句","c":["视草行看赐上樽，浊醪付我酹嶙峋。","扶携谁共山前醉，从此无君度外人。"]},{"t":"再次韵四首 其二","f":"七言绝句","c":["作吏丁年熟李书，调官晚境曳邹裾。","平时外慕生灾怪，嘉遁爻中有祓除。"]},{"t":"再次到房交代招饮韵四首 其四","f":"七言绝句","c":["山色阴晴远更青，谁教睥睨枕岩扃。","诗翁意欲移千步，安得朱符祝巨灵。"]},{"t":"再次韵四首 其四","f":"七言绝句","c":["颇有传诗问子山，或将赞易誉虞翻。","先生不乏醺酣笑，问字能无款席门。"]},{"t":"再次到房交代招饮韵四首 其一","f":"七言绝句","c":["山好能令肺病苏，诗来把玩更惊吁。","蜀人例作残山看，端喜因诗免受诬。"]},{"t":"再次交代韵四首 其四","f":"七言绝句","c":["诗愁磨尽鬓边青，玄钥无施闭理扃。","牛渚锦官祠庙古，瓣香傥格在天灵。"]},{"t":"再次交代韵四首 其一","f":"七言绝句","c":["君家诗价自姑苏，系胄蝉联世唶吁。","欲把阿元轻辈行，古今俗子喜相诬。"]},{"t":"再次韵杨宰七首 其六","f":"七言绝句","c":["骤闻行旅叹赍粮，无复居人肯馈浆。","十袭君诗要娱老，却愁痛定说常旸。"]},{"t":"再次韵杨宰七首 其五","f":"七言绝句","c":["微吟长啸强跻攀，愁斛多于庾子山。","我亦丰凶关梦寐，秋成消息待君还。"]},{"t":"再次韵杨宰七首 其四","f":"七言绝句","c":["枣饤菘菹不阙供，露莲何啻剥千蓬。","迎秋更有苍虬卵，邀勒斜阳未肯红。"]},{"t":"再次韵杨宰七首 其三","f":"七言绝句","c":["能书徒自想高闲，煨芋何从得懒残。","萧寺随缘茶饼供，胜谭谁为解忧端。"]},{"t":"再次韵杨宰七首 其二","f":"七言绝句","c":["颇思菱角问鸡头，且放莲房擅早秋。","蠲渴涤烦须底物，未应接绠汲溪流。"]},{"t":"再次韵杨宰七首 其一","f":"七言绝句","c":["雪英闲澹炯双明，水斛泓渟碧一罂。","小憩山村无与语，熏炉茶鼎斗僧清。"]},{"t":"再次韵赵帅见寄三首 其三","f":"七言绝句","c":["倏晴骤雨寒犹在，约勒群芳未尽开。","销得燕堂千杖鼓，旋看锦缬裹条枚。"]},{"t":"再次韵赵帅见寄三首 其二","f":"七言绝句","c":["前欢已悔东隅失，后约如前敢再违。","连夜扬州昔年梦，小梅清瘦杏花肥。"]},{"t":"再次韵赵帅见寄三首 其一","f":"七言绝句","c":["枝撑强趁火城春，踪迹犹烦问水滨。","更醉南州好红紫，凝香诗伯是花神。"]},{"t":"再次韵赵景安四首 其四","f":"七言绝句","c":["酒浓胜得晚天寒，云气侵帷水墨翻。","兰蕙香前还判醉，不须投辖锁重门。"]},{"t":"再次韵赵景安四首 其三","f":"七言绝句","c":["平时一饱每从人，自庇官曹等徼巡。","且可放狂中酒圣，冷看得意诧钱神。"]},{"t":"再次韵赵景安四首 其二","f":"七言绝句","c":["艳粉奇葩照座隅，更阑醉墨点襟裾。","诗成平处犹元白，无限羁愁赖破除。"]},{"t":"再次韵赵景安四首 其一","f":"七言绝句","c":["迂儒法士就鸡连，犹复拘拘诧瓮天。","度外有人能好客，一樽容我赋超然。"]},{"t":"再次赠张学录韵十诗 其五","f":"五言绝句","c":["阅世有顺逆，飞埃曀空虚。","旷怀略外物，曲士乃拘墟。"]},{"t":"再题二首 其二","f":"七言绝句","c":["涛头蜚过不斯须，祇合朝昏展此图。","缅想海门才末势，终然畎浍视江湖。"]},{"t":"再题二首 其一","f":"七言绝句","c":["天吴凭怒鼓涛澜，不作闲居卷轴看。","夜半负山谁料得，重来坐失两高寒。"]},{"t":"刘向二首 其二","f":"七言绝句","c":["若将初节订贤愚，圣哲功名古亦无。","一代儒宗忧国意，当年几落伪金诛。"]},{"t":"刘向二首 其一","f":"七言绝句","c":["江边逐客楚宗卿，谏数君疏命自轻。","可信后儒惭往哲，辄将强聒议更生。"]},{"t":"刘有诗再次韵四首 其四","f":"七言绝句","c":["耐暑支离倚瘦筇，百金未博一襟风。","了知诗有蠲痾力，绝胜江涛捲碧空。"]},{"t":"刘有诗再次韵四首 其三","f":"七言绝句","c":["此君高韵已萧然，更向新诗得媚川。","谁遣小家藏二妙，为君时炷水沉烟。"]},{"t":"刘有诗再次韵四首 其二","f":"七言绝句","c":["已后湖州秃鬓翁，喜君挥扫有遗风。","幻成殢雨熹晴态，尽使尘凡一洗空。"]},{"t":"刘有诗再次韵四首 其一","f":"七言绝句","c":["小点猩毫出碧鲜，技随文思各增川。","祇应月地饶般礴，心醉寒梢曳晓烟。"]},{"t":"同沈守劝农十首 其十","f":"七言绝句","c":["露粉烟香细孰何，荆扉竹径喜经过。","阳和若作留连计，谁遣飞红扫更多。"]},{"t":"同沈守劝农十首 其九","f":"七言绝句","c":["抖擞平时簿领尘，偷闲来作看花人。","从今日作花间去，已费今年一半春。"]},{"t":"同沈守劝农十首 其八","f":"七言绝句","c":["病来止酒似渊明，潘岳归田赋已成。","布谷催耕如见谂，提壶劝醉更多情。"]},{"t":"同沈守劝农十首 其七","f":"七言绝句","c":["林花断续碧溪长，好在冰奁照靓妆。","泛腻流膏知远近，未妨粉水更添香。"]},{"t":"同沈守劝农十首 其五","f":"七言绝句","c":["沉炷茶铛且翠微，归轩何惜小逶迤。","晴天璧月今宵好，待得金波泛夜时。"]},{"t":"同沈守劝农十首 其三","f":"七言绝句","c":["行遍西阡更北村，檀栾处处绿梢云。","官身未敢山间宿，可得排门谒此君。"]},{"t":"同沈守劝农十首 其二","f":"七言绝句","c":["门横石濑漱潺湲，两两人家柳映门。","花影滟红山影碧，客行疑到武陵原。"]},{"t":"同沈守劝农十首 其一","f":"七言绝句","c":["谁似青君用岁华，遍分春色到幽遐。","房陵远近山千叠，到处东风到处花。"]},{"t":"同徐吕二子游西湖复次前韵五首 其五","f":"七言绝句","c":["天分天上灵河水，围作钱塘千顷湖。","未有风亭花月观，已誇胜境世间无。"]},{"t":"同徐吕二子游西湖复次前韵五首 其四","f":"七言绝句","c":["酴醾芍药借春回，似解商量陆续开。","安得玄霜著花骨，不教容易染苍苔。"]},{"t":"同徐吕二子游西湖复次前韵五首 其三","f":"七言绝句","c":["仙祠佛舍碧山边，扶路逢人有醉颠。","火急向渠分此乐，徐郎多病我衰年。"]},{"t":"同徐吕二子游西湖复次前韵五首 其二","f":"七言绝句","c":["林仙金骨閟丘墟，松自萧森鹤自孤。","灵魄在天联傅说，遗书落世仰潜夫。"]},{"t":"同徐吕二子游西湖复次前韵五首 其一","f":"七言绝句","c":["老去胡宜誓酒卮，兴来破戒为君持。","自今排日花间醉，报答春光已后时。"]},{"t":"庆元冬再到盱眙四首 其四","f":"七言绝句","c":["日行荦确面孱颜，旧惯山居意易阑。","见说烟云暝崷崒，北人争指画图看。"]},{"t":"庆元冬再到盱眙四首 其三","f":"七言绝句","c":["醴筵曾作二年留，静镇人今郭细侯。","望断江南空梦到，西风斜照白杨秋。"]},{"t":"庆元冬再到盱眙四首 其二","f":"七言绝句","c":["平日朝京此问途，如今一水剪坤舆。","客来羡杀闲鸥鹭，北翥南飞得自如。"]},{"t":"庆元冬再到盱眙四首 其一","f":"七言绝句","c":["虎头山下参天柳，亲见栽时共我长。","柳自摧残人自老，半生不抵熟黄粱。"]},{"t":"戏促黄簿鸡粥约三首 其三","f":"七言绝句","c":["只鸡可餍小人腹，未羡侯家千足羊。","借问解鼋食指动，何如蒸鸭瓠壶香。"]},{"t":"戏促黄簿鸡粥约三首 其二","f":"七言绝句","c":["鹅炙博嗔宁复计，马肝知味不须评。","老宜此辈充庖宰，更问钻篱与不鸣。"]},{"t":"戏促黄簿鸡粥约三首 其一","f":"七言绝句","c":["微吟仰屋耐调饥，腹负将军竟是谁。","侧耳邻翁隔墙唤，黄鸡粥熟是何时。"]},{"t":"早春十绝呈石湖 其七","f":"七言绝句","c":["虎丘僧宇瞰坡陀，几许香軿载酒过。","游子花骢烟外驻，丽人尘袜水边多。"]},{"t":"早春十绝呈石湖 其一","f":"七言绝句","c":["不是风寒即雨寒，朝来春意破天悭。","怪君未解春皇意，恐把韶华付等闲。"]},{"t":"早春十绝呈石湖 其四","f":"七言绝句","c":["中林频度养花风，合放林梢一点红。","蝴蝶与春偏有约，依依先占去年丛。"]},{"t":"早春十绝呈石湖 其十","f":"七言绝句","c":["馆娃宫外趁游人，不见湖山自在春。","闻道石湖清绝处，芳时不著绮罗尘。"]},{"t":"早春十绝呈石湖 其三","f":"七言绝句","c":["树外晴云不拟飞，东风无力惬单衣。","垂杨院宇斜阳里，还是钩帘待燕归。"]},{"t":"早春十绝呈石湖 其二","f":"七言绝句","c":["倏看媚白破梅枝，更喜娇黄著柳丝。","春事斩新当客眼，可须山鸟报人知。"]},{"t":"早春十绝呈石湖 其九","f":"七言绝句","c":["鸱夷古锦犊车辕，盘薄沙鸥舞蝶前。","少日长安聚蚊梦，莫年诗酒解随缘。"]},{"t":"早春十绝呈石湖 其五","f":"七言绝句","c":["杏羞桃涩要诗催，客子情钟倍费才。","惜欠王家千杖鼓，辊雷声里看花开。"]},{"t":"早春十绝呈石湖 其六","f":"七言绝句","c":["未须看竹扣人门，且复寻梅过水村。","香片点衣归马健，临风只博断吟魂。"]},{"t":"早春十绝呈石湖 其八","f":"七言绝句","c":["缓引牙樯载绮罗，宽围丝锦著笙歌。","小抬醉眼游丝外，夕照御城奈乐何。"]},{"t":"早夏 其一","f":"七言绝句","c":["安石榴花猩血鲜，凉荷高叶碧田田。","鲥鱼入市河豚罢，已破江南打麦天。"]},{"t":"朱倅索诗作三绝谢之 其一","f":"七言绝句","c":["因循不试推敲手，日月消磨簿领间。","旧故书来尽新作，穷儿券负几时还。"]},{"t":"朱倅索诗作三绝谢之 其三","f":"七言绝句","c":["从公挥扫且观傍，免费雕镌苦肾肠。","血指忍惭嗟已老，怒矊相向更深防。"]},{"t":"次王巡检韵三首 其三","f":"七言绝句","c":["每愧铜盘走柘丸，忽惊檀轴卷丝阑。","真成敝帚千金享，笑唤诸雏挂壁看。"]},{"t":"次王巡检韵三首 其二","f":"七言绝句","c":["平生嘿识玩诗昌，对客挥毫底未忘。","祇恐韩陵读碑客，诮君草草诮吾狂。"]},{"t":"次王巡检韵三首 其一","f":"七言绝句","c":["掐肾搜肠不自奇，细模深刻似非宜。","流传纵便鸡林售，指擿防遭鹅腿嗤。"]},{"t":"次史髯韵二首 其二","f":"七言绝句","c":["已误西湖鸥鹭约，客舟西上更徘徊。","故人益叹天涯远，怀抱何从得好开。"]},{"t":"次史髯韵二首 其一","f":"七言绝句","c":["痛忆分题把酒时，暑寒谁遣隙驹驰。","芙蓉风露梅花月，又费骚人几首诗。"]},{"t":"次石湖送炭韵赠龚养正三首 其三","f":"七言绝句","c":["寒谷冰崖底著身，望晨疑寝越王薪。","今年未办巡檐笑，急雪阴风肯贷春。"]},{"t":"次石湖送炭韵赠龚养正三首 其二","f":"七言绝句","c":["广文书案雪沾身，灶妇冰菹焮湿薪。","綵胜银花犹拜赐，冻醅寒饼不成春。"]},{"t":"次石湖送炭韵赠龚养正三首 其一","f":"七言绝句","c":["饥乌窘兔不谋身，君亦衣穿桂作薪。","小露化工陶铸手，地炉分得雪中春。"]},{"t":"次两知县韵四首 其四","f":"七言绝句","c":["政成无复败群羊，万轴书前一缕香。","明日过君况休务，茶边清话不妨长。"]},{"t":"次两知县韵四首 其三","f":"七言绝句","c":["似我聱牙亦漫官，倚君风义慰羁单。","开缄更识新诗法，脱手铜丸转玉盘。"]},{"t":"次两知县韵四首 其二","f":"七言绝句","c":["暴醉琳腴饱栈羊，巡檐闲认小梅香。","胡床曝背关情甚，古锦囊诗引兴长。"]},{"t":"次两知县韵四首 其一","f":"七言绝句","c":["老去栖迟八品官，剑颐深悔诮田单。","东邻未省吟髭断，笑掷牙牌命肉盘。"]},{"t":"次张节推山字韵诗留其行 其五","f":"七言绝句","c":["老丑只宜岩谷里，何人挈致俊贤间。","虽云章服裹叔夜，尚有笭箵随次山。"]},{"t":"次张节推山字韵诗留其行 其三","f":"七言绝句","c":["红尘叹我奔驰久，空谷逢君梦寐间。","政使公荣可无饮，风江惊浪涌银山。"]},{"t":"次张节推山字韵诗留其行 其二","f":"七言绝句","c":["人瞻甫里歊埃外，诗著苏州伯仲间。","爽气凭销残暑尽，钩窗不用对西山。"]},{"t":"次张节推山字韵诗留其行 其六","f":"七言绝句","c":["故人偶得一饭款，僻县才馀十亩间。","赤米白盐君勿诮，病夫官况等居山。"]},{"t":"次张节推山字韵诗留其行 其四","f":"七言绝句","c":["粹学堂堂真有本，玄谈亹亹尽无间。","小回馀事入诗律，句法还能逼后山。"]},{"t":"次张节推山字韵诗留其行 其一","f":"七言绝句","c":["足音肯到寂寥处，风味要看樽俎间。","行役小休良不恶，雷声昨夜殷南山。"]},{"t":"次张丞送菊韵二首 其二","f":"七言绝句","c":["寒花彭泽门阑旧，好句柯山伯仲间。","贫负清樽只三益，诗人错笑庾郎悭。"]},{"t":"次张丞送菊韵二首 其一","f":"七言绝句","c":["粉身免泛杯中物，并驾容陪陇首花。","况耐岁寒双干在，周旋三益羡君家。"]},{"t":"次张学录韵十首 其七","f":"五言绝句","c":["广文无酒钱，到官倏改火。","清谭坐萧斋，惟子屡过我。"]},{"t":"次张学录韵十首 其六","f":"五言绝句","c":["张子五车读，笔作蛟龙腾。","百战气弥厉，依然短檠灯。"]},{"t":"次张学录韵十首 其一","f":"五言绝句","c":["俗习有南北，交情无故新。","得子班荆地，朴鲁俱淮人。"]},{"t":"次林子长教授韵 其二","f":"七言绝句","c":["豫章材成七年后，潢潦眼看三尺彊。","山翁坐阅刺天翼，抱书亦耻崔嵬藏。"]},{"t":"次玩鞭亭小诗韵 其二","f":"七言绝句","c":["窃禄未辞官九品，归田止欠屋三间。","著书他日藏岩穴，或继淮南大小山。"]},{"t":"次玩鞭亭小诗韵 其一","f":"七言绝句","c":["心事即今惊白发，世情从昔彀黄间。","窦家锦上四百字，祇道藁砧山复山。"]},{"t":"次姜尧章饯徐南卿韵二首 其二","f":"七言绝句","c":["风调心期契钥同，谁教社燕辟秋鸿。","莫年孤陋仍漂泊，可得斯人慰眼中。"]},{"t":"次姜尧章饯徐南卿韵二首 其一","f":"七言绝句","c":["姜郎未仕不求田，倚赖生涯九万笺。","稛载珠玑肯分我，北关当有合肥船。"]},{"t":"次赵帅喜雪韵","f":"七言绝句","c":["府公忧国雪神知，三白呈祥不待祈。","旧岁新年多乐事，一时分付笔如飞。"]},{"t":"次赵帅韵三首 其三","f":"七言绝句","c":["诗仙催客共流霞，不待高城噪晚鸦。","好竞春光醉良夜，即今庭院已飞花。"]},{"t":"次赵帅韵三首 其二","f":"七言绝句","c":["游人笑语问朝霞，处处相随攫肉鸦。","上冢归来更乘兴，醉依柳影藉梨花。"]},{"t":"次赵帅韵三首 其一","f":"七言绝句","c":["眼眩如看九色霞，女肤侧理字栖鸦。","挽回春事凭诗力，留住风林欲褪花。"]},{"t":"次梁教授见贻韵五首 其五","f":"七言绝句","c":["敝帚千篇漫手缄，分无三字入官衔。","消磨不尽干云气，时作长虹贯夜岩。"]},{"t":"次梁教授见贻韵五首 其四","f":"七言绝句","c":["藏室仙经玉作函，一编当复翠鸾衔。","即今尚喜观书眼，月射清池电耀岩。"]},{"t":"次梁教授见贻韵五首 其三","f":"七言绝句","c":["谁向仙曹接胜谭，金泥天篆署冰衔。","如闻不惜蜚霞佩，乞与耕莘与筑岩。"]},{"t":"次梁教授见贻韵五首 其二","f":"七言绝句","c":["沐猴岂合缠章服，野马如今脱辔衔。","屈指悔来坡下路，瘦筇随客上巉岩。"]},{"t":"次梁教授见贻韵五首 其一","f":"七言绝句","c":["红尘半世仅绯衫，白首官曹两换衔。","羞见淮乡隐君子，紫芝黄独老嵌岩。"]},{"t":"次程平叔韵二首 其二","f":"七言绝句","c":["诗情对景可胜长，酒与鹅儿斗嫩黄。","忠贯主人真好事，肯来訾省沈东阳。"]},{"t":"次程平叔韵二首 其一","f":"七言绝句","c":["故人常叹别时长，一笑眉开色便黄。","领略西园好风景，凭君更唤郭汾阳。"]},{"t":"次韵王统制喜雨","f":"七言绝句","c":["公馀竞病挥诗笔，谁似风流老伏波。","对雨肯来同把酒，当令阿素为君歌。"]},{"t":"次韵吴守四首 其四","f":"七言绝句","c":["当日谪仙随凤诏，毫端写出禁园春。","沉香亭北人沉醉，误认龙香在领巾。"]},{"t":"次韵吴守四首 其三","f":"七言绝句","c":["莫管龙公懒放晴，主宾笑语自生春。","不妨妃子天香面，满压林宗折角巾。"]},{"t":"次韵吴守四首 其一","f":"七言绝句","c":["十日阴寒此日晴，归来趁赏大花春。","主家千斛香泉碧，却自摩挲漉酒巾。"]},{"t":"次韵张丞","f":"七言绝句","c":["官上绝无歌酒乐，堆豗了事孰非痴。","开樽良省缠头费，却有新章赠雪儿。"]},{"t":"次韵张守三首 其三","f":"七言绝句","c":["虐天子子是无天，谪一何妨惠亿千。","闻道蝎中犹滑涣，可偕五细尚穷边。"]},{"t":"次韵张守三首 其二","f":"七言绝句","c":["平时漫诧跳梁去，末势宁逃死弃如。","但遣鲸鲵绝吞噬，茫洋春泽尽嘉鱼。"]},{"t":"次韵张守三首 其一","f":"七言绝句","c":["频岁中田苦螟螣，为渠秉畀作丰年。","只今鼠子诛求地，巷议街谈一粲然。"]},{"t":"次韵张守四首 其四","f":"七言绝句","c":["葱青嘉树被平岗，素艳丹葩半在亡。","安得芳春并好客，一时难老倚玄霜。"]},{"t":"次韵张守四首 其三","f":"七言绝句","c":["舟凌清泚转弯环，立鹭驯鸥拱挹间。","还忆苕溪听鸣橹，归来清梦定家山。"]},{"t":"次韵张守四首 其二","f":"七言绝句","c":["新诗囊锦堕春窗，旋炷铜炉百和香。","试握毛锥支劲敌，独怜赤手强扶疮。"]},{"t":"次韵张守四首 其一","f":"七言绝句","c":["画舫前头碧湛空，晴云低影更溶溶。","横陈景物无央数，尽献诗翁阿堵中。"]},{"t":"次韵张守仲思食车螯","f":"七言绝句","c":["斤除介甲更加鞭，隽永丰腴旧所便。","蛏弟蛤兄从倚市，车公酒处信光前。"]},{"t":"次韵杨宰汲泉浸栀子花","f":"七言绝句","c":["山行不识小人羹，但有清寒饷瓦罂。","想见雪肤陪独夜，世间无比长官清。"]},{"t":"次韵杨宰思庭竹","f":"七言绝句","c":["数寻脆碧袅轻阴，岁不知寒暑不侵。","属厌吟风仍啸雨，尽收县解入琴心。"]},{"t":"次韵杨宰食野莲","f":"七言绝句","c":["小尝绀菂掉吟头，甓社湖阴风露秋。","仙实休誇华峰顶，吮霜咽蜜亦其流。"]},{"t":"次韵杨宰凌霄花","f":"七言绝句","c":["高花笑属赋花人，花自鲜明笔有神。","可惜人间两清绝，不教媚妩对闲身。"]},{"t":"次韵杨宰捕蝗宿兑岩四首 其四","f":"七言绝句","c":["龙公私我雨霶浪，酿酒须防有乞浆。","惭愧四邻千万室，略无笑语及时旸。"]},{"t":"次韵杨宰捕蝗宿兑岩四首 其三","f":"七言绝句","c":["去为民劳走险艰，停骖几问具茨山。","祇今欲致贤劳谢，诗债徒能准数还。"]},{"t":"次韵杨宰捕蝗宿兑岩四首 其二","f":"七言绝句","c":["旱蝗蔽土翳云空，遥想驱驰逐转蓬。","端坐赖君酬一饱，老颜可讳发惭红。"]},{"t":"次韵杨宰捕蝗宿兑岩四首 其一","f":"七言绝句","c":["归来闻道颇休闲，蝗事今随暑气残。","我欲一樽供软脚，还能冲雨过苏端。"]},{"t":"次韵杨宰爱竹","f":"七言绝句","c":["看竹排门爱靓深，青青不受雪霜侵。","谁知倦客幽寻去，老越风波亦此心。"]},{"t":"次韵赵帅","f":"七言绝句","c":["平山已自胜超然，况复莺花二月天。","管领莺花属仙伯，不应草草赋归田。"]},{"t":"次韵赵帅二首 其二","f":"七言绝句","c":["妓台香里漏声残，金步摇歌闹作团。","羯鼓更催银字管，等闲惊破一天寒。"]},{"t":"次韵赵帅二首 其一","f":"七言绝句","c":["天公一笑晚云残，戏与璇穹贴白团。","试问天风摇翠袖，玉肌何似玉笙寒。"]},{"t":"次韵赵帅五首 其五","f":"七言绝句","c":["南游可待再书催，芍药酴醾陆续开。","看自花开到花落，红蕖时候却归来。"]},{"t":"次韵赵帅五首 其四","f":"七言绝句","c":["红药主人修月手，渌樽许为故人开。","肯教客子如王式，一听骊驹却悔来。"]},{"t":"次韵赵帅五首 其三","f":"七言绝句","c":["一昨波光修禊事，宾奁俯枕玉奁开。","重游鸥鹭应偷眼，定记曾陪杖屦来。"]},{"t":"次韵赵帅五首 其二","f":"七言绝句","c":["前知红药翻阶处，别许金腰一朵开。","名在金瓯花会得，即看飞诏下天来。"]},{"t":"次韵赵帅五首 其一","f":"七言绝句","c":["平时花酒费诗催，块坐愁城谁为开。","六辈妖姬十从事，先生亲遣斩关来。"]},{"t":"次韵赵帅寒食四首 其四","f":"七言绝句","c":["夜雨勾芒正主臣，晴云暖霭晓来新。","小軿径趁遨头去，共醉郊园烂熳春。"]},{"t":"次韵赵帅寒食四首 其三","f":"七言绝句","c":["散吏容陪汉鼎臣，隆隆恩意为谁新。","重来画戟凝香地，烂醉琼枝璧月春。"]},{"t":"次韵赵帅寒食四首 其二","f":"七言绝句","c":["日佩诗囊侍贵臣，向人肯作白头新。","自今歌酒追随去，犹有风烟一半春。"]},{"t":"次韵赵帅寒食四首 其一","f":"七言绝句","c":["瘦岛寒郊祇外臣，先生俊逸更清新。","劝耕小出仍寒食，剩办新诗报答春。"]},{"t":"次韵赵帅蜡梅","f":"七言绝句","c":["窗底闲寻断续香，贴金谁此憩风裳。","汉姬懒赴昭阳燕，宫额涂成却覆觞。"]},{"t":"次韵袁宪打冰移舟三首 其三","f":"七言绝句","c":["东行定见野桥梅，望望花随驿使来。","曾约南枝春信否，急烦好句与催开。"]},{"t":"次韵袁宪打冰移舟三首 其二","f":"七言绝句","c":["留滞何曾念奋飞，君恩已布得徐归。","贤劳肯羡膏粱子，醉眼瞢腾坐妓围。"]},{"t":"次韵袁宪打冰移舟三首 其一","f":"七言绝句","c":["倚柂扶篙待打冰，回思鹢首漱波声。","定知行止非人计，料理诗愁唤曲生。"]},{"t":"次韵袁宪劳军许浦中路冰合二首 其二","f":"七言绝句","c":["细读清诗拟泣岐，问津平日几河湄。","只今西去须遵陆，平地风波恐更危。"]},{"t":"次韵袁宪劳军许浦中路冰合二首 其一","f":"七言绝句","c":["风声雪意恣冯陵，更挟霜华夜气凝。","水伯护河银作板，欲留公斗玉壶冰。"]},{"t":"次韵诸公绝句 其一","f":"七言绝句","c":["琳宇无尘夜色鲜，露明丛菊月临渊。","世间人境双清处，诵与西风更此编。"]},{"t":"次韵诸公绝句 其二","f":"七言绝句","c":["荆玉骊珠忽满前，未须攻石探涛渊。","南帆自诧归装富，准拟重呼阿买编。"]},{"t":"次韵郭帅梅三首 其三","f":"七言绝句","c":["后乘从公访古梅，梢含笑脸未全开。","不妨东閤撩诗兴，未分愁听起夜来。"]},{"t":"次韵郭帅梅三首 其二","f":"七言绝句","c":["薄游他日为寻梅，烂赏菁村十里开。","冰影玲珑想仍旧，梦为庄蝶认香来。"]},{"t":"次韵郭帅梅三首 其一","f":"七言绝句","c":["客子徒烦赋忆梅，怯寒未肯腊前开。","定知酒处频回首，有待江南信使来。"]},{"t":"次韵郭教授雪二首 其二","f":"七言绝句","c":["世纷长作眼中尘，酒力能回物外春。","清论挟霜诗映雪，即今超俗赖斯人。"]},{"t":"次韵郭教授雪二首 其一","f":"七言绝句","c":["霏霏透隙上承尘，想见园林玉树春。","明日银杯随宝马，城东应有探梅人。"]},{"t":"次韵钱倅诸公睡香花四首 其四","f":"五言绝句","c":["小篱护殷鲜，久厌杂芳眩。","风烟桃李蹊，一付檀槐战。"]},{"t":"次韵黄簿 其一","f":"七言绝句","c":["先生不著惠文冠，须信论才当价难。","法律剡章真未尽，盍言粹学辈豪韩。"]},{"t":"次韵黄簿 其二","f":"七言绝句","c":["挥毫丽句得旁观，字字悬黎间木难。","可但诗声高海内，有人金换过三韩。"]},{"t":"次韵答陈梦锡十首 其十","f":"七言绝句","c":["诗人锋铓不可触，瞢揽鲸牙撩虎须。","飞来此编更作意，诗行快对夔州图。"]},{"t":"次韵答陈梦锡十首 其六","f":"七言绝句","c":["冰檗未肯执名卿，搔头自剔书窗灯。","君家老人如椽笔，浙江鄞水倒泓澄。"]},{"t":"次韵答陈梦锡十首 其五","f":"七言绝句","c":["姜子嗜酒不良行，诸公俛顾惭登瀛。","尚堪坚坐作周鼎，底用诗名满凤城。"]},{"t":"次韵答赵文卿四首 其四","f":"七言绝句","c":["帘疏财许客窥班，未得缠头小破悭。","已结云愁蜚蝶梦，莫斜秋水蹙春山。"]},{"t":"次韵答赵文卿四首 其三","f":"七言绝句","c":["小燕招邀慰病颜，何曾雨涩与风悭。","分明喜鹊先知得，未晓飞鸣闹屋山。"]},{"t":"次韵答赵文卿四首 其二","f":"七言绝句","c":["平日诗声不易班，联翩属我未应悭。","得无纸贵咸阳市，当有人逢饭颗山。"]},{"t":"次韵答赵文卿四首 其一","f":"七言绝句","c":["才名一世未通班，天向诗人每坐悭。","不作上书来北阙，可无携妓醉东山。"]},{"t":"次韵答璧侍者五首 其五","f":"七言绝句","c":["欲买青山贷寓居，时临绝顶瞰平湖。","已容下榻烦重问，肯念吾贫折券无。"]},{"t":"次韵答璧侍者五首 其四","f":"七言绝句","c":["为向诗翁致命回，定应禅老笑颜开。","盘餐要是随宜饱，略具油葱市海苔。"]},{"t":"次韵答璧侍者五首 其二","f":"七言绝句","c":["狮子窟中狮子子，孤群慑怯更清孤。","当场不作春雷吼，底用吟诗压老夫。"]},{"t":"次韵答璧侍者五首 其一","f":"七言绝句","c":["佛屋连延跨翠微，看云手版向曾持。","重游不是寻春去，冷眼漂花捲絮时。"]},{"t":"次韵赠郭侯","f":"七言绝句","c":["郭侯智勇两俱长，驿骑何时诏检黄。","胡运于今已灰囗，看君万旅出渔阳。"]},{"t":"次魏知元韵三首 其三","f":"七言绝句","c":["江城半月从游乐，别去知君剩有诗。","相望置邮三舍便，幸能时寄慰相思。"]},{"t":"次魏知元韵三首 其二","f":"七言绝句","c":["魏郎日共无喧酒，旧学新诗得细论。","可见高情重离别，又同一舸宿烟村。"]},{"t":"次魏知元韵三首 其一","f":"七言绝句","c":["客中把酒挹江山，更藉诗人为解颜。","自是交游十年旧，向来相得立谭间。"]},{"t":"江行四首 其四","f":"七言绝句","c":["帆桅飞去划空明，人倚东风两翼生。","世事快人如此否，日斜三百不留行。"]},{"t":"江行四首 其三","f":"七言绝句","c":["远近青山不办看，翩翾征雁敢争先。","船头起浪风头孰，不假骖鸾自半仙。"]},{"t":"江行四首 其二","f":"词","c":["舟鹢凌乘著羽翰，摊钱三老喜安闲。","江豚白?欺人甚，喷浪跳波帆影间。"]},{"t":"江行四首 其一","f":"七言绝句","c":["帆饱舟轻去若梭，平生忠信傲风波。","忽然隐几惊摇兀，知是那吒石畔过。"]},{"t":"约徐吕二友访净慈老二首 其二","f":"七言绝句","c":["人间机巧厌相亲，南道吾今有主人。","谁与清游联此辔，吕兄孺子最真醇。"]},{"t":"约徐吕二友访净慈老二首 其一","f":"七言绝句","c":["魏紫千葩压曲栏，问君何似檐头看。","城西更有芳菲地，旧约重寻莫作难。"]},{"t":"观山四首 其四","f":"七言绝句","c":["道人动作千年调，京兆才馀五日留。","此去浮图桑下意，得无追忆费冥搜。"]},{"t":"观山四首 其三","f":"七言绝句","c":["山如豪俊略方隅，傲睨骄蹇未受拘。","为著孤亭凌缥渺，至今端委正衙趋。"]},{"t":"观山四首 其二","f":"七言绝句","c":["每从迫隘面孱颜，劣比缘墙见髻鬟。","好在此亭同把酒，与君全体看南山。"]},{"t":"观山四首 其一","f":"七言绝句","c":["晴春载酒小徘徊，倏作冲泥冒雨回。","毕竟山灵嫌俗驾，即今还殷阿香雷。"]},{"t":"过吕仙洞四首 其四","f":"七言绝句","c":["尘踪了鸟病催残，梦谒真人九转丹。","已熟浮生枯骨观，更悲凡质遇天难。"]},{"t":"过吕仙洞四首 其三","f":"七言绝句","c":["嵌岩中有玉为壶，不作嵇生守煅炉。","玩世肯尝东老酒，翻身时过洞庭湖。"]},{"t":"过吕仙洞四首 其二","f":"七言绝句","c":["天人蜕迹便天飞，混迹尘凡世得知。","岁历七朝踰六百，朝朝冷眼阅行尸。"]},{"t":"过吕仙洞四首 其一","f":"七言绝句","c":["神游八极此焉归，紫府天宽石作扉。","倦客重来炷沉燎，转头六十七年非。"]},{"t":"即事二首 其一","f":"七言绝句","c":["隥围山拥碧崚嶒，二载房陵冷似冰。","今日皇皇空载质，令人翻忆在房陵。"]},{"t":"即事二首 其二","f":"七言绝句","c":["形容肮脏水云宜，心意阑残欲语谁。","不作贵人炎冷面，北山逋客最相知。"]},{"t":"吟诗自笑用前韵 其二","f":"七言绝句","c":["退归我欲学真长，君定才名江夏黄。","考父旧尝睎吉甫，陵阳端的嗣黔阳。"]},{"t":"吟诗自笑用前韵 其一","f":"七言绝句","c":["文字光腾万丈长，锦官老杜豫章黄。","投荒忍死经人鲊，讨饭充肠上岳阳。"]},{"t":"呈程帅五首 其五","f":"七言绝句","c":["一樽规度雪寒朝，小辍鸣弓抗射雕。","未用军书送巾帼，故人祭灶有佳招。"]},{"t":"呈程帅五首 其四","f":"七言绝句","c":["客间久欲赋归欤，归去何人为起予。","平日呕心空子墨，羡公落笔便黄初。"]},{"t":"呈程帅五首 其三","f":"七言绝句","c":["不将杯酒破衰颜，轹月凌风取鬓班。","隽永要同无味味，雕搜聊乐不闲闲。"]},{"t":"呈程帅五首 其二","f":"七言绝句","c":["景物横前祇费才，何妨折简唤邹枚。","连朝积雨前宵雪，总为催诗陆续来。"]},{"t":"呈程帅五首 其一","f":"词","c":["平?陆海吸潘江，羽扇雍容筑受降。","许蔡衡湘全楚地，了知邾郐不在邦。"]},{"t":"张守有和章复次韵三首 其三","f":"七言绝句","c":["闲舒侧理题长句，漫与胎仙纪往回。","花径宿莺楼著燕，因思如愿赋归来。"]},{"t":"张守有和章复次韵三首 其二","f":"七言绝句","c":["接翼鸿冥聊尔尔，大书麟获更仪仪。","雄边仙伯横琴处，应道苏耽兴尽归。"]},{"t":"张守有和章复次韵三首 其一","f":"七言绝句","c":["一骨万金知未惬，五云七字不妨赊。","此翁久断扬州梦，径付凝香旧主家。"]},{"t":"张守送羊羔酒将以三绝次韵答之 其三","f":"七言绝句","c":["瓮中别作一家春，羒羜微生得效珍。","少贷陶家煎雪水，更论徐邈对贤人。"]},{"t":"张守送羊羔酒将以三绝次韵答之 其二","f":"七言绝句","c":["小槽清凝带膻香，酿法知非羸角羊。","拜赐未辞乾讲舌，呼儿留得荐蒸尝。"]},{"t":"张守送羊羔酒将以三绝次韵答之 其一","f":"七言绝句","c":["生尝跪乳资名教，死去遗芳谥碧香。","洗盏开尝吾未敢，称冤肯入菜羹肠。"]},{"t":"村居二首 其二","f":"七言绝句","c":["卷书揩目小披襟，睡起初便茗椀深。","一缕碧檀无与语，坐窗闲看竹移阴。"]},{"t":"村居二首 其一","f":"七言绝句","c":["五风十雨梅破夏，三青两黄麦欲秋。","山禽谇语野花笑，瘦筇随客下西畴。"]},{"t":"泛湖十绝句 其六","f":"七言绝句","c":["酒边凉意雨馀生，望夜重期看月明。","安得水仙会事发，巧随人意作阴晴。"]},{"t":"泛湖十绝句 其八","f":"七言绝句","c":["寻得诗人到醉乡，银壶玉麈倍增光。","小囊赋就鸳鸯锦，一路荷花别漾香。"]},{"t":"泛湖十绝句 其七","f":"七言绝句","c":["底许行庖旋不空，小舟如织浪花中。","盘珍俎实随供给，亦有红衣载短篷。"]},{"t":"泛湖十绝句 其十","f":"七言绝句","c":["楼前行客竞昂头，楼上齐声唱石州。","衮遍实催犹未彻，暑风晴月各新秋。"]},{"t":"泛湖十绝句 其五","f":"七言绝句","c":["桃叶相逢但交臂，李鬟何许费凝眸。","尔曹岂解文字饮，应道吾侪输此筹。"]},{"t":"泛湖十绝句 其九","f":"七言绝句","c":["玉人罢浴试梅妆，诗客挥毫落夜光。","因病覆觞今破戒，为渠豪饮为君狂。"]},{"t":"泛湖十绝句 其一","f":"七言绝句","c":["荷面跳珠小溅衣，酒边团扇已停挥。","湿云收尽人间暑，却度西山载雨归。"]},{"t":"泛湖十绝句 其二","f":"七言绝句","c":["浦溆楼台远近殊，樽罍随处小踟蹰。","高郎颇胜高常侍，解把西湖敌孟诸。"]},{"t":"泛湖十绝句 其三","f":"七言绝句","c":["银笔曾烦赞此君，即今墨色俨如新。","因君细数登龙日，十九年前入幕宾。"]},{"t":"泛湖十绝句 其四","f":"七言绝句","c":["嫩绿摇漪红藕香，雨膏烟腻午供凉。","西湖到眼真西子，莫信温柔别有乡。"]},{"t":"灵岩道中二首 其二","f":"七言绝句","c":["涉涧登山倦不胜，松间敲户有人应。","竹帘琐细炉烟直，小作蒲团入定僧。"]},{"t":"灵岩道中二首 其一","f":"七言绝句","c":["过尽南山过北山，幽花好鸟翠霏间。","满前风物牵诗兴，可是平生马上闲。"]},{"t":"闲居十首 其十","f":"七言绝句","c":["寒食清明一箭过，晚晴庭院绿阴多。","兔葵燕麦易轻脱，红药碧桃须孰何。"]},{"t":"闲居十首 其九","f":"七言绝句","c":["桃李争先不待催，梅花转首已青苔。","即今蜀种胭脂树，压倒群芳尚懒开。"]},{"t":"闲居十首 其八","f":"七言绝句","c":["病减还思近曲生，嚼花嗅蕊对空瓶。","不应斗酒钱三百，犹惜春衣耐独醒。"]},{"t":"闲居十首 其七","f":"七言绝句","c":["闭关不为赏心阑，咫尺东园到自难。","斟酌东君惜春色，破除十九作阴寒。"]},{"t":"闲居十首 其六","f":"七言绝句","c":["步屧归来未觉劳，迎门喧笑问儿曹。","笑翁浑似鱼千里，小圃周围日几遭。"]},{"t":"闲居十首 其五","f":"七言绝句","c":["破晓东风尚作寒，孤筇随客已媻姗。","绝知蚤起非吾事，要趁梨花带露看。"]},{"t":"闲居十首 其四","f":"七言绝句","c":["仙仙弄影俯琼瑶，月地香红苦见撩。","清梦定为蝴蝶去，杏花繁处宿良宵。"]},{"t":"闲居十首 其三","f":"七言绝句","c":["春来敢自贷衰慵，正要檀栾间白红。","爱竹少留枝策径，灌花分破著书功。"]},{"t":"闲居十首 其二","f":"七言绝句","c":["种桃接李不辞勤，旋作花前把酒人。","羡杀文禽映花语，飞来趁得见成春。"]},{"t":"闲居十首 其一","f":"七言绝句","c":["雪云脱坏漏朝阳，风物横前引兴长。","红糁紫蕤今次第，迁莺来燕费商量。"]},{"t":"陈君美许仲和赴省病不能出饯以二绝句 其二","f":"七言绝句","c":["何人把酒送扬舲，定复从容柳下亭。","共说归时柳阴合，与君衫色斗青青。"]},{"t":"陈君美许仲和赴省病不能出饯以二绝句 其一","f":"七言绝句","c":["修程快著祖生鞭，胜日同乘李郭船。","自愧不能扶病去，郭南亭上看登仙。"]},{"t":"陈总管坐上赠写竹妓二首 其二","f":"七言绝句","c":["此君写影道机熟，犹记涪翁诧子舟。","谁信红衣万钧笔，拟分此派嗣湖州。"]},{"t":"陈总管坐上赠写竹妓二首 其一","f":"七言绝句","c":["劲节苍梢笔底寒，一天风雪与坚顽。","回思拥扇宾筵见，却为娇娆一破颜。"]},{"t":"净居劝农三首 其三","f":"七言绝句","c":["簿书堆里得抽身，梅柳风前触眼新。","报答好春还著语，今朝犹喜是闲人。"]},{"t":"净居劝农三首 其二","f":"七言绝句","c":["今年春计定何如，说道家家甔石馀。","满意为翁开笑口，老夫心事祇耕锄。"]},{"t":"净居劝农三首 其一","f":"七言绝句","c":["妙胜庭前折小梅，净居门外蹑枯苔。","日烦禅老羞茶供，亲与田翁把酒杯。"]},{"t":"到房交代招饮四首 其二","f":"七言绝句","c":["檐外浮岚暖翠堆，道人亲眼为渠开。","餐钱官簿何须计，直为南山亦合来。"]},{"t":"到房交代招饮四首 其一","f":"七言绝句","c":["蹑尽巉岩气未苏，悔来坡下独长吁。","一观烟雾南山面，从昔名坡信厚诬。"]},{"t":"到房交代招饮四首 其三","f":"七言绝句","c":["胜日山堂共一樽，未妨窈窕对嶙峋。","髻分翠影眉争绿，人与南山各可人。"]},{"t":"和憙","f":"七言绝句","c":["仁杰狂甥趁猎人，颇能戴眼笑庭绅。","汉家退堡犹麻沸，正复羞为女主臣。"]},{"t":"咏史二首 其二","f":"七言绝句","c":["平侧区分偶俪匀，无阶更复古真淳。","浪言此秘无前睹，毕竟休文是罪人。"]},{"t":"咏史二首 其一","f":"七言绝句","c":["暴楚狂秦席卷中，谋臣战将各言功。","端知四百绵炎祚，祇属商山秃鬓翁。"]},{"t":"学宫诸生饮邀予与子野同之三首 其三","f":"七言绝句","c":["忍饥不嗅嗟来食，强项从教俗子嗔。","乘闲甘作不速客，好事无非我辈人。"]},{"t":"学宫诸生饮邀予与子野同之三首 其二","f":"七言绝句","c":["少日峨冠英俊场，课馀觞咏共徜徉。","孰知薄宦江湖去，频梦炉亭饼饦香。"]},{"t":"学宫诸生饮邀予与子野同之三首 其一","f":"七言绝句","c":["同簉儒宫把一觞，鹿鸣伐木奏深堂。","要防技痒论文地，莫忆前宵放酒狂。"]},{"t":"定海甲寅口号七首 其七","f":"七言绝句","c":["连宵飞雨喜滂流，已入梅天过麦秋。","二十年前如此晚，金城地抱却全收。"]},{"t":"定海甲寅口号七首 其六","f":"七言绝句","c":["邻家两两捉春归，笑语相过复叹咨。","共说飓头前夜作，几人莆网挂流尸。"]},{"t":"定海甲寅口号七首 其五","f":"七言绝句","c":["父子分头上海船，今年海熟胜常年。","官中可但追呼少，不质田输折米钱。"]},{"t":"定海甲寅口号七首 其四","f":"七言绝句","c":["水泛沟塍意欲餍，凌晨还复雨廉纤。","早秧未颔犹须插，晚谷无多不更㘱。"]},{"t":"定海甲寅口号七首 其三","f":"七言绝句","c":["已抄口数报隅官，岁后朝餔定不难。","且愿眼前彊健在，趁坊讨海过冬寒。"]},{"t":"定海甲寅口号七首 其二","f":"七言绝句","c":["田租有约不相违，比著丰年数已亏。","一饱分明郎首赐，几曾刺口问抽卑。"]},{"t":"定海甲寅口号七首 其一","f":"七言绝句","c":["长官清苦旧传闻，检放禾苗近四分。","毕竟不缘胥吏手，旱头科敛枉纷纭。"]},{"t":"庚子冬望雪二首 其一","f":"七言绝句","c":["冬尽风霜只薄寒，人将雨雪卜新年。","痴儿不问丰凶事，但快茆檐炙背眠。"]},{"t":"房陵十首 其十","f":"七言绝句","c":["翁媪同围老瓦盆，倒篘新酒杂清浑。","枧南枧北皆春社，且放乌犍卧晏温。"]},{"t":"房陵十首 其九","f":"七言绝句","c":["刈罢秋禾未敢慵，更须趁逐过残冬。","城中竹筊今年贵，盐茗新来免阙供。"]},{"t":"房陵十首 其八","f":"七言绝句","c":["农闲闾里有逢迎，白饮傍边骨在羹。","老稚不妨顽过日，边头难得是升平。"]},{"t":"房陵十首 其七","f":"七言绝句","c":["杯酒清浓肉更肥，咸言趁社极欢嬉。","丁宁向去坐年日，要似如今敛脯时。"]},{"t":"房陵十首 其六","f":"七言绝句","c":["跨牛待得夕阳回，在处诸嫲笑口开。","已借蜡钱输麦税，免教缉捕闯门来。"]},{"t":"房陵十首 其五","f":"七言绝句","c":["夏田少雨富来年，多雨何妨穑事秋。","已戒日供皮子面，更教晚稻饱霜收。"]},{"t":"房陵十首 其四","f":"七言绝句","c":["竹屋高低正复斜，蔚蓝影里著人家。","底消山峡三分瘴，争课卢仝七椀茶。"]},{"t":"房陵十首 其三","f":"七言绝句","c":["雩坛歌舞杂嗟吁，下酉犹濡上酉枯。","谁谓朝来一拆雨，欢声已觉沸通衢。"]},{"t":"房陵十首 其二","f":"七言绝句","c":["阴晴未敢捲帘看，苦雾濛濛鼻为酸。","政使病馀刚制酒，一杯要敌涝朝寒。"]},{"t":"房陵十首 其一","f":"七言绝句","c":["似闻仙伯厌乘龙，常混红尘市井中。","觌面未须趄避我，褰衣无计䟕寻公。"]},{"t":"招山阳高徐二生饮二首 其二","f":"七言绝句","c":["欲作山阴兴尽回，良思与子共衔杯。","要须人境俱清绝，好抱瑶琴踏雪来。"]},{"t":"招山阳高徐二生饮二首 其一","f":"七言绝句","c":["梅花时节屡开樽，欲赠梅花欠可人。","今日有人梅样好，迟君同赏雪中春。"]},{"t":"泊上虞驿来日行四首 其一","f":"五言绝句","c":["秋雨歇复下，西风微自凉。","不妨舟系柳，已贷汗反浆。"]},{"t":"泊上虞驿来日行四首 其四","f":"五言绝句","c":["龙公底戏剧，长啸暝江天。","雨鹊翻仍语，风舟舞不前。"]},{"t":"泊上虞驿来日行四首 其三","f":"五言绝句","c":["溪山可图画，风物忆吾乡。","渔艇鸥鹜乱，茅茨菱芡香。"]},{"t":"泊上虞驿来日行四首 其二","f":"五言绝句","c":["梁湖莽苍外，后去未云迟。","县市容吾恋，江潮不汝期。"]},{"t":"祈雨而应范簿有诗次韵四首 其四","f":"七言绝句","c":["山城粗满望霓心，老去私忧念自深。","更祝今宵继畴昔，并烦鲁史纪为霖。"]},{"t":"祈雨而应范簿有诗次韵四首 其三","f":"七言绝句","c":["久无音信日边来，忧国谁怜怆老怀。","想见天颜欢喜甚，鸳鸿入贺满尧街。"]},{"t":"祈雨而应范簿有诗次韵四首 其二","f":"七言绝句","c":["瓣香亲谒睡岩龙，高卧逶迤岂自公。","岩下望龙须一怒，向来作止系凶丰。"]},{"t":"祈雨而应范簿有诗次韵四首 其一","f":"七言绝句","c":["苍黄日日冒黄尘，敢意诚通主雨神。","晓起遽听沾足报，天心政尔念疲民。"]},{"t":"绍熙壬子劝耕妙胜四首 其四","f":"七言绝句","c":["桑条麦陇接比邻，社酒家炊丐路人。","风俗尚如它日否，凭谁细问故园春。"]},{"t":"绍熙壬子劝耕妙胜四首 其三","f":"七言绝句","c":["胜日乘闲觉半仙，笑摩老眼向风烟。","平章春事禽能语，媚妩韶光柳未眠。"]},{"t":"绍熙壬子劝耕妙胜四首 其二","f":"七言绝句","c":["每愧敲榜办赋租，会心还喜劝耕初。","渠侬嗣飨金穰庆，老子长捐柱后书。"]},{"t":"绍熙壬子劝耕妙胜四首 其一","f":"七言绝句","c":["县曹文墨厌拘缠，野饭山行旧所便。","祇道穷涂难措足，朝来风日为谁妍。"]},{"t":"苦雨次前韵四首 其四","f":"七言绝句","c":["骚窣松筠听夜喧，淙潺盆盎骇朝翻。","衰翁危坐追交态，旧雨轩车尚到门。"]},{"t":"苦雨次前韵四首 其三","f":"七言绝句","c":["安排看驾趁游人，禁籞犹迟汉帝巡。","留取晚香天一笑，倩谁寄语主林神。"]},{"t":"苦雨次前韵四首 其二","f":"七言绝句","c":["墨云筛雨密还疏，欲出涂泥恐溅裾。","恶况横陈费料理，枯棋浊酒有驱除。"]},{"t":"苦雨次前韵四首 其一","f":"七言绝句","c":["雨脚波头远接连，衣寒础润犯梅天。","谁怜旅食缁尘客，日问珠炊与桂然。"]},{"t":"雨中题柏氏壁二首 其二","f":"七言绝句","c":["苏端颇惯招新客，御叔何烦讶圣人。","未用平章旧新雨，一樽聊喜对情亲。"]},{"t":"雨中题柏氏壁二首 其一","f":"七言绝句","c":["行寻诘屈蹑崎岖，已谢邻翁果下驹。","北走松楸无数里，杖藜筋力尚枝梧。"]},{"t":"临泽寺留题","f":"七言绝句","c":["发冢诗书谩一官，旧游重到鬓毛斑。","尘埃可是山灵意，不待文移始厚颜。"]},{"t":"侯拉客归置饮再次韵","f":"七言绝句","c":["将军恩意为谁长，酒未阑残日脚黄。","傥有春风四弦手，真成留客醉浔阳。"]},{"t":"复次韵四首 其四","f":"七言绝句","c":["病肺还孤竹叶青，小园春去尚深扃。","春衫红药强相比，婢子可怜无性灵。"]},{"t":"复次韵四首 其三","f":"七言绝句","c":["十里髻鬟谁绾结，半天苍翠自嶙峋。","教儿莫惮依山住，阔领裁衣尽土人。"]},{"t":"复次韵四首 其二","f":"七言绝句","c":["昔上瞿塘滟预堆，盘涡如井放船开。","山行欢喜今非错，备见梢濆撇漩来。"]},{"t":"复次韵四首 其一","f":"七言绝句","c":["诸李辞章推李白，向来蜀道赋噫吁。","房陵山险犹如许，石穴巴邛定不诬。"]},{"t":"客夜不寐四首 其四","f":"七言绝句","c":["飞腾志意老来休，却听鸡声吟掉头。","催雪忆梅还得句，到家准拟阿儒求。"]},{"t":"客夜不寐四首 其三","f":"七言绝句","c":["清樽黄卷交期绝，芋火前头老懒残。","赖有平生短檠在，一灯明灭伴更阑。"]},{"t":"客夜不寐四首 其二","f":"七言绝句","c":["阵鸿轇轕上云衢，梦欲成时每破除。","少睡更堪寒夜永，新来熟遍少时书。"]},{"t":"客夜不寐四首 其一","f":"七言绝句","c":["久客情悰苦鲜欢，园林摇落菊花残。","北风作意吹霜晓，又报江梅一信寒。"]},{"t":"客枕不寐二首 其二","f":"七言绝句","c":["嗢喔邻鸡几番鸣，琤撞江浪欲无声。","拥衾宁复还家梦，望杀东窗未肯明。"]},{"t":"客枕不寐二首 其一","f":"七言绝句","c":["老羡平生睡作魔，矧因多病覆金荷。","起凭曲几频搔首，如此迢迢良夜何。"]},{"t":"春阴二首 其二","f":"七言绝句","c":["园林桃杏已无馀，雨挟春寒擅晓晡。","芍药红悭犹料理，海棠娇甚可枝梧。"]},{"t":"春寒六首 其三","f":"七言绝句","c":["衰年心绪自低摧，可是青春昧一来。","几日不教书作祟，为留病眼向花抬。"]},{"t":"春寒六首 其二","f":"七言绝句","c":["稍稍春光到眼中，冲寒试与小支筇。","杏花已尾樱桃拆，正要深红间淡红。"]},{"t":"春寒六首 其一","f":"七言绝句","c":["扫雪阶头晓未乾，东风作恶鼻仍酸。","西园点检江梅后，祇有樱桃不避寒。"]},{"t":"春寒六首 其六","f":"七言绝句","c":["平明欲敛云复厚，薄晚未休风更颠。","老怯春寒不宜出，下帷添火拥书眠。"]},{"t":"春寒六首 其五","f":"七言绝句","c":["清明寒食经旬是，笑问风寒更几馀。","小杏惜香春恰恰，新杨弄影午疏疏。"]},{"t":"春寒六首 其四","f":"七言绝句","c":["去年秫地伤秋潦，春酒浇醨不可亲。","红树梢头山鸟语，祇应笑我独醒人。"]},{"t":"春暖赠梅喜作二首 其二","f":"七言绝句","c":["手撚芳枝酹渌樽，东君乃有发生恩。","即今省暖铜瓶水，罗幕围香共晏温。"]},{"t":"春暖赠梅喜作二首 其一","f":"七言绝句","c":["晴日烘开栗玉葩，懒随霰雪送年华。","淮乡地冷开虽晚，竟是人间第一花。"]},{"t":"昼过荷叶浦二首 其二","f":"七言绝句","c":["一舟失得关生死，中夜何人肆夺攘。","外此湖江多乐土，忆常通夕听渔榔。"]},{"t":"昼过荷叶浦二首 其一","f":"七言绝句","c":["荷叶浦边支港多，凶人出没土人窝。","故人饭我非留滞，月黑天阴免夜过。"]},{"t":"相如二首 其二","f":"七言绝句","c":["逸德狂情赖补苴，文君端合婿相如。","白头曲里殷勤意，不愧先生谏猎书。"]},{"t":"相如二首 其一","f":"七言绝句","c":["中宵卒卒去临邛，卖酒垆边混僦佣。","想见令君醒后意，向人深悔谬为恭。"]},{"t":"赵介卿见简解嘲二首 其二","f":"七言绝句","c":["酒家旧识玄真子，街吏尝随杜牧之。","回首昔游堪一笑，暮年茶果祇僧期。"]},{"t":"赵介卿见简解嘲二首 其一","f":"七言绝句","c":["复閤朱楼绣箔褰，蕙兰风处各婵娟。","诗翁它日扬州梦，回施京华美少年。"]},{"t":"赵园饮三首 其三","f":"七言绝句","c":["酒边容角少年狂，扶路归来兴未央。","羡杀雄蜂雌蛱蝶，月膏烟腻宿花房。"]},{"t":"赵园饮三首 其二","f":"七言绝句","c":["收藏春色驻年华，珍重王孙好事家。","肯挽归骖共良夜，一天风露一林花。"]},{"t":"赵园饮三首 其一","f":"七言绝句","c":["不谓东君雨后春，尚多红紫待游人。","天香更有西京种，来伴宾筵笑脸新。"]},{"t":"赵通判有诗次韵二首 其二","f":"七言绝句","c":["短歌对酒不能长，犹胜车尘扑面黄。","我自关门宝崇鼎，从渠睎价尚咸阳。"]},{"t":"赵通判有诗次韵二首 其一","f":"七言绝句","c":["霍王无短似无长，惊见新诗写硬黄。","鱼在九渊终玉食，世间濡足羡浮阳。"]},{"t":"送吴子隆节推之官信州五首 其五","f":"七言绝句","c":["连城照乘动分珍，他日词坛著散人。","诗笔有神官有暇，楚鳞燕翼要频频。"]},{"t":"送吴子隆节推之官信州五首 其四","f":"七言绝句","c":["幕中婉画得斯人，郡政应从到日新。","银錵金苗休刺口，祇将耕稼富州民。"]},{"t":"送吴子隆节推之官信州五首 其三","f":"七言绝句","c":["共把离杯柳影边，柳枝如线拂归船。","枝枝似恨人轻别，颦不成眠更可怜。"]},{"t":"送吴子隆节推之官信州五首 其二","f":"七言绝句","c":["行行幕府泛莲初，井井官曹游刃馀。","当路急贤饥渴似，不须衔袖子公书。"]},{"t":"送吴子隆节推之官信州五首 其一","f":"七言绝句","c":["人生穷达后愚贤，宦路何妨小著鞭。","三釜吾今嗟弗洎，奉亲东下羡登仙。"]},{"t":"送鹌鸭腊龚养正二首 其二","f":"七言绝句","c":["骚人茹粥耐支离，过眼风光不到诗。","乡味慇勤劝开肉，未妨新句解人颐。"]},{"t":"送鹌鸭腊龚养正二首 其一","f":"七言绝句","c":["霜湖风草自徜徉，夜网晨弦不易防。","作意分甘资一饱，为撩清梦到江阳。"]},{"t":"郡斋鹤飞来作三诗还之 其一","f":"七言绝句","c":["倒颊翘然望四遐，芝田悬圃不应赊。","仙仙飞傍茅茨下，误认西湖处士家。"]},{"t":"郡斋鹤飞来作三诗还之 其三","f":"七言绝句","c":["君家矫矫乘轩骨，闻道今成赵璧回。","却拟黄堂掣铃问，夜光论斗几时来。"]},{"t":"郢州守风二首 其二","f":"七言绝句","c":["瓮盎轰豗恣击撞，佩环时亦奏铿锵。","风涛欲静犹须怒，一付天吴自抑扬。"]},{"t":"郢州守风二首 其一","f":"七言绝句","c":["惊风清旦捲黄沙，薄暮蜚云尚炮车。","今夜石城楼上角，不妨重听小梅花。"]},{"t":"徐南卿友竹轩二首 其二","f":"七言绝句","c":["啸风含月近窗扉，金锁珑璁凤尾齐。","况复赖君相引重，一时同作辟尘犀。"]},{"t":"徐南卿友竹轩二首 其一","f":"七言绝句","c":["皱縠香罗裹瓠壶，此君高韵岂其徒。","萧然相对心莫逆，敢谓徐郎山泽臞。"]},{"t":"晓枕二首 其二","f":"七言绝句","c":["铜丸惊破将军梦，银箭催登朝士车。","老朽布衾酣晓暖，晨乌夜鹤莫愁予。"]},{"t":"晓枕二首 其一","f":"七言绝句","c":["两鸭惊鸣转五更，幽人宿酒未全醒。","小轩祇似孤舟上，忆得霜湖带梦听。"]},{"t":"栖隐寺紫薇花二首 其二","f":"七言绝句","c":["绛霞影里一徜徉，甚欲搜诗与发扬。","马自虺隤尘染袂，句中羞说紫微郎。"]},{"t":"栖隐寺紫薇花二首 其一","f":"七言绝句","c":["深红浅紫碎罗装，竹树阴中独自芳。","已伴白莲羞远供，款陪黄菊荐陶觞。"]},{"t":"病起二首 其二","f":"七言绝句","c":["舞席歌筵自阔疏，曲生久送绝交书。","平生嗜好消磨尽，留得枯棋了索居。"]},{"t":"病起二首 其一","f":"七言绝句","c":["老去难堪痼疾缠，支离甘受众人怜。","出门定被将迎困，紧闭风窗听雨眠。"]},{"t":"袁本初二首 其二","f":"七言绝句","c":["嬖孽朝兄主父囚，女戎衔猾史苏忧。","便教官渡交绥去，二竖犹能乱冀州。"]},{"t":"袁本初二首 其一","f":"七言绝句","c":["入门偶藉移韩馥，健者何曾抗董公。","须信阿瞒人物论，但言玄德是英雄。"]},{"t":"读晋史二首 其二","f":"七言绝句","c":["只知成济犯乘舆，刘石凶威更有馀。","狼顾魂灵应自反，尚将鬼责怖公闾。"]},{"t":"读晋史二首 其一","f":"七言绝句","c":["司马家儿转首亡，奸欺三叶是馀殃。","区区牛氏何关汝，覆面犹须泪满床。"]},{"t":"都下春日","f":"七言绝句","c":["烟林红翠已班班，雨后春工不暇悭。","付与笙箫三万指，平分綵舫聒湖山。"]},{"t":"阅水教次前韵","f":"七言绝句","c":["戈船干柂截江长，杀气氛昏日气黄。","江畔诗翁泚椽笔，射蛟无复羡枞阳。"]},{"t":"阅史六首 其六","f":"七言绝句","c":["平时愤世谢王符，更肯佯狂踵接舆。","须信有心端有累，与君乘木用舟虚。"]},{"t":"阅史六首 其五","f":"七言绝句","c":["徐稚申屠晚见机，当时张邴是先知。","冥鸿久矣层霄上，置网弥山漫尔为。"]},{"t":"阅史六首 其三","f":"七言绝句","c":["树威立敌祇商君，俯仰欺诬莽更文。","何事君王自聪哲，三槐五鼎买崩分。"]},{"t":"阅史六首 其二","f":"七言绝句","c":["公安枯竹本何知，摽表精忠解不私。","应笑神奇甘臭腐，谗锋得意几馀时。"]},{"t":"阅史六首 其一","f":"七言绝句","c":["百战淮西仅奏功，澶渊欲战已平戎。","三纡相绂犹公道，长为莱公羡晋公。"]},{"t":"高祖二首 其二","f":"七言绝句","c":["坐馘关东扛鼎雄，指呼奴隶走王公。","祇缘夺嫡中心慊，反畏商山鹤发翁。"]},{"t":"高祖二首 其一","f":"七言绝句","c":["未推壮邑赏平津，已采先知赦奉春。","齐越淮南皆斧锧，狂胡遽指汉无人。"]},{"t":"偶题","f":"七言绝句","c":["雾红烟白忽横陈，雨后风光圣得新。","说似游人须著便，阴寒已破一分春。"]},{"t":"寄广教主僧二首 其二","f":"七言绝句","c":["麦绾银丝稻荐珠，春窗曾是饭伊蒲。","明朝再蜡登山屐，更肯开单共饱无。"]},{"t":"寄广教主僧二首 其一","f":"七言绝句","c":["回车半日赞公房，香积酥陀不一尝。","可但山行休脚力，免教饥火燎枯肠。"]},{"t":"寄张守仲思十首 其十","f":"七言绝句","c":["诗社同盟欲二年，吮宫含羽饱周旋。","仪真又属风骚将，定唤闲身续此弦。"]},{"t":"寄张守仲思十首 其八","f":"七言绝句","c":["衰慵潦倒知无用，禄遫扁舟昧此来。","满听胜谭心已足，浩然欲指弊庐回。"]},{"t":"寄张守仲思十首 其七","f":"七言绝句","c":["珍蔬解佐盘餐饱，妙剂真令病骨轻。","钟乳茈姜皆楚产，荐芹聊致野人诚。"]},{"t":"寄张守仲思十首 其六","f":"七言绝句","c":["迂船径欲一相过，安德桥西之字河。","未苦路长寒切骨，倚君一笑作春和。"]},{"t":"寄张守仲思十首 其五","f":"七言绝句","c":["衰年淡食当膏腴，不为闻韶味有馀。","定自迎门惊骨立，可须蓬语及河鱼。"]},{"t":"寄张守仲思十首 其四","f":"七言绝句","c":["知君喜客我携雏，径唤郎君到坐隅。","二字通家仍莫逆，可怜相对各缞粗。"]},{"t":"寄张守仲思十首 其三","f":"七言绝句","c":["相从软语说睽离，起我清谭更好诗。","别后忧虞今痛定，未须细诵悼亡辞。"]},{"t":"寄张守仲思十首 其一","f":"七言绝句","c":["一思交好一悲悽，楚峤吴山梦到迷。","怕说万山天样远，房陵更在万山西。"]},{"t":"寄赵帅三首 其三","f":"七言绝句","c":["先生列馆似翘材，惯见琼筵为客开。","夜夜元宵日寒食，一春尽可厕邹枚。"]},{"t":"寄赵帅三首 其二","f":"七言绝句","c":["银钩满纸堕荆扉，乐事如今与愿违。","抚己可怜多病过，忆公深愧食言肥。"]},{"t":"寄赵帅三首 其一","f":"七言绝句","c":["扬州灯火万家春，谁著诗翁寂寞滨。","旧腊新年无好况，何须更问紫姑神。"]},{"t":"寄赵宰三首 其三","f":"七言绝句","c":["北山何意阻清游，似为江山挽得留。","客未言归君好事，此盟端肯再寻不。"]},{"t":"寄赵宰三首 其二","f":"七言绝句","c":["猛士语难熊虎样，画楼山立水云间。","雄豪等作诗家助，酒处吟笺莫放闲。"]},{"t":"寄赵宰三首 其一","f":"七言绝句","c":["頫江山水檐楹外，壮观风烟画轴中。","诗客去留俱不恶，缓摇吟辔倚天风。"]},{"t":"寄郢州崔守八首 其八","f":"七言绝句","c":["牙板声中敛翠眉，时应歌我遣怀词。","岂知薄宦飘零去，无复风情似旧时。"]},{"t":"寄郢州崔守八首 其七","f":"七言绝句","c":["将军竞病旧能诗，黄绢于今玩色丝。","何日酒兵鏖笔阵，未应羽檄谂交绥。"]},{"t":"寄郢州崔守八首 其六","f":"七言绝句","c":["雍郎高韵似文同，水墨仍参二米风。","解搴山川归短幅，可能陆续寄来鸿。"]},{"t":"寄郢州崔守八首 其五","f":"七言绝句","c":["别乘修程骥騄驰，书来犹肯记衰迟。","每思胶漆班荆地，敢忘风波在莒时。"]},{"t":"寄郢州崔守八首 其四","f":"七言绝句","c":["碧香当日荐金船，桑落宜城不直钱。","一自黄堂沉醉后，至今追忆尚流涎。"]},{"t":"寄郢州崔守八首 其三","f":"七言绝句","c":["楚郢繁雄亚上都，莫愁风韵未应殊。","小园依旧深红色，曾辱遨头载酒无。"]},{"t":"寄郢州崔守八首 其二","f":"七言绝句","c":["尝记停骖古郢州，待晴曾是贾胡留。","锦囊亦有阳春句，不得亲题白雪楼。"]},{"t":"寄郢州崔守八首 其一","f":"七言绝句","c":["阳关声断酒杯残，昨梦回思变暑寒。","七见蟾蜍作圆缺，四冯鳞羽问平安。"]},{"t":"寄题高宾王诗后卷","f":"七言绝句","c":["韶頀充庭簉汉官，铺纾宏伟叹才难。","高郎袖有如椽笔，却伴秋虫吊夜寒。"]},{"t":"曹魏二首 其二","f":"七言绝句","c":["问卓诸公半虎狼，魏旗四指不留藏。","老瞒淯水如先死，不必炎刘果后亡。"]},{"t":"曹魏二首 其一","f":"七言绝句","c":["睢盱汉鼎漫心劳，梦觉俄惊马食槽。","马渐天飞龙在井，当涂能得几时高。"]},{"t":"梁元帝二首 其二","f":"七言绝句","c":["中外谁非肉骨恩，颙颙帝子亦王孙。","君王日握金银笔，忍署兵威极六门。"]},{"t":"梁元帝二首 其一","f":"七言绝句","c":["慢藏已重阿琳忧，君道平时况未优。","冀北羊肠各亡社，浪言建业胜荆州。"]},{"t":"隗嚣","f":"七言绝句","c":["诸父论情是至亲，若为见卖苟全身。","发崔冤魄旋无憾，眼见君侯杀伯春。"]},{"t":"喜雨二首 其二","f":"七言绝句","c":["招宝山邻娑竭宫，县峰仍接补陀峰。","晴晴雨雨皆如响，谬挹池鳗拜土龙。"]},{"t":"喜雨二首 其一","f":"七言绝句","c":["永宁开善皆留宿，梦破阶除急雨倾。","人道行车定膏泽，我知龙伯念春耕。"]},{"t":"喜雨口号呈陈守伯固十二首 其十二","f":"七言绝句","c":["雨后郊原小杖藜，行人相语各伸眉。","即今极目如云稼，曾是蝗虫盖地皮。"]},{"t":"喜雨口号呈陈守伯固十二首 其十一","f":"七言绝句","c":["岁收粗足蛰饥雷，不赖门生送酒杯。","坐遣将军扪腹笑，端知此惠有从来。"]},{"t":"喜雨口号呈陈守伯固十二首 其十","f":"七言绝句","c":["得句聊将颂作霖，开樽亦复陋孤斟。","南亭旧约何时践，志喜从公更一吟。"]},{"t":"喜雨口号呈陈守伯固十二首 其九","f":"七言绝句","c":["邦人苦旱日呻呼，公比邦人更瘠臞。","贺雨归来人竞问，邦君今日解颜无。"]},{"t":"喜雨口号呈陈守伯固十二首 其八","f":"七言绝句","c":["疠疾流时囊探丸，羸癃十九得安全。","再烦起死回生手，挽作山城大有年。"]},{"t":"喜雨口号呈陈守伯固十二首 其七","f":"七言绝句","c":["使君手有垂云帚，虐魃妖螟扫不馀。","十顷飞蝗戴蛆死，已濡银笔为君书。"]},{"t":"喜雨口号呈陈守伯固十二首 其六","f":"七言绝句","c":["钱轻币重病吾农，未有奇方起困穷。","粗遣年丰官籴粟，少令钱币各通融。"]},{"t":"喜雨口号呈陈守伯固十二首 其五","f":"七言绝句","c":["货绝交通腹殷雷，人家一雨便春台。","即看商贩接踵集，已有米船衔尾来。"]},{"t":"喜雨口号呈陈守伯固十二首 其四","f":"七言绝句","c":["醮坛初上水沉烟，甓社龙公敢晏眠。","为建清泠三万斛，坐令翠密舞中田。"]},{"t":"喜雨口号呈陈守伯固十二首 其三","f":"七言绝句","c":["未明出作夜深归，敢怨今年雨后时。","岂独旱杷全好在，晚秧不死尚堪移。"]},{"t":"喜雨口号呈陈守伯固十二首 其二","f":"七言绝句","c":["共说邦君祷雨时，衋如疾痛切肤肌。","公心一片秋空月，可但圆通大士知。"]},{"t":"喜雨口号呈陈守伯固十二首 其一","f":"七言绝句","c":["旱风虫孽久挻灾，好雨如今陆续来。","谁道天人不相与，青章解挽帝心回。"]},{"t":"寓吴门十首 其十","f":"七言绝句","c":["平时觞咏妨生理，此去狂疏托上官。","但使推敲贷冲节，不烦排日报平安。"]},{"t":"寓吴门十首 其九","f":"七言绝句","c":["禹益咨俞俨紫庭，藩星仍映使星明。","鄙夫少日三千牍，尽付诗情写治平。"]},{"t":"寓吴门十首 其八","f":"七言绝句","c":["稚子浪忧陶令老，山妻终誉仲卿贤。","虎头试写经行处，龙具宁甘未死前。"]},{"t":"寓吴门十首 其七","f":"七言绝句","c":["日日烟林野市间，路人应作老狂看。","排门赏竹宁辞骂，踏雪寻梅苦耐寒。"]},{"t":"寓吴门十首 其六","f":"七言绝句","c":["兴阑猛辍凌江棹，重看莺花茂苑春。","归自乘流留亦好，浙风淮俗总宜人。"]},{"t":"寓吴门十首 其五","f":"七言绝句","c":["向来勇策著书勋，一刻曾将白璧论。","老去光阴都不惜，静看乌兔役朝昏。"]},{"t":"寓吴门十首 其四","f":"七言绝句","c":["溪翁园客问何如，可讳浮生百计疏。","不惮典衣规得酒，长因乞米衒能书。"]},{"t":"寓吴门十首 其三","f":"七言绝句","c":["诸公念我闲无食，粟继舆台扣户频。","眼底梅花还索笑，酒肠诗胆已轮囷。"]},{"t":"寓吴门十首 其二","f":"七言绝句","c":["官卑责薄得徜徉，漫仕归来味更长。","它日故人多好事，笼鸡载酒未吾忘。"]},{"t":"寓吴门十首 其一","f":"七言绝句","c":["一寒驱去还干禄，万虑纷然祇爱山。","阅世恍如清梦觉，求田聊计白头闲。"]},{"t":"循资赵宰有贺诗次韵三首 其三","f":"七言绝句","c":["反唇馀子轻玄白，属目耆儒上紫清。","老境我甘追汗漫，明时君合订章程。"]},{"t":"循资赵宰有贺诗次韵三首 其二","f":"七言绝句","c":["蒿帛入门无几润，妻孥食粥有馀清。","轻肥腾趠非吾愿，矻矻雌黄且课程。"]},{"t":"循资赵宰有贺诗次韵三首 其一","f":"七言绝句","c":["宦涂跛鳖陵坡上，学舍寒蝉饮露清。","蹩躠强颜才跬步，不应天骥与论程。"]},{"t":"景安和章来再次韵谢设醴四首 其四","f":"七言绝句","c":["拜赐清诗醒醉昏，恍如帝所听新翻。","君才炙輠无穷尽，未敢先关月下门。"]},{"t":"景安和章来再次韵谢设醴四首 其三","f":"七言绝句","c":["玉盘盂侧玉为人，插羽瑶觞不计巡。","想送客归回醉盼，司花来梦斗精神。"]},{"t":"景安和章来再次韵谢设醴四首 其二","f":"七言绝句","c":["道装人映醉中姝，十二分行俨翠裾。","遥想翻阶丽清禁，似今群艳簉庭除。"]},{"t":"景安和章来再次韵谢设醴四首 其一","f":"七言绝句","c":["朅来取友得三贤，安石仁风乐广天。","七字不应呈此拙，诗肠老去已枵然。"]},{"t":"游山阳十首 其十","f":"七言绝句","c":["熙台楚观小开樽，老去登临易断魂。","蹀血龙荒平昔志，即今搔首望中原。"]},{"t":"游山阳十首 其九","f":"七言绝句","c":["刘伶台畔酹金卮，寂寂荒丘带晚晖。","今日先生不能饮，妇言屏弃未为非。"]},{"t":"游山阳十首 其八","f":"七言绝句","c":["多许金钗换好辞，长巾短帕缕金泥。","老来诗力知何似，细访香罗验旧题。"]},{"t":"游山阳十首 其七","f":"七言绝句","c":["会看亭下水涵空，菡萏香中理钓筒。","北道主人吾有托，不应独飨北窗风。"]},{"t":"游山阳十首 其六","f":"七言绝句","c":["高郎胸次著潇湘，亭枕城闉野趣长。","我欲亭西分一曲，白鸥波外自鸣榔。"]},{"t":"游山阳十首 其五","f":"七言绝句","c":["故人不复倒奚囊，但有荒阡荫白杨。","魂定可招吾得已，试吟楚些命巫阳。"]},{"t":"游山阳十首 其四","f":"七言绝句","c":["玳筵当日小红裳，珠压双丫十岁强。","回首方知但青子，胡琴声里怨茶商。"]},{"t":"游山阳十首 其三","f":"七言绝句","c":["官池二十四鸳鸯，锦綵争鲜伴醉狂。","翡翠有儿知更好，几时飞到酒樽傍。"]},{"t":"游山阳十首 其二","f":"七言绝句","c":["邗沟帆席即长淮，鬓未霜时惯往回。","绛县老人今若此，此生更复几番来。"]},{"t":"游山阳十首 其一","f":"七言绝句","c":["山阳城外舣舟初，先问黄公旧酒垆。","空有向来觞咏意，岁华不贷白髭须。"]},{"t":"游灵山二首 其二","f":"七言绝句","c":["何年山股创禅房，陵谷迁移不易量。","旧日中流小浮玉，如今欲到祇褰裳。"]},{"t":"游灵山二首 其一","f":"七言绝句","c":["高人避俗水云居，客子偷闲簿领馀。","本自毗耶病居士，不妨僧饭小躇蹰。"]},{"t":"游隐静往反四首 其四","f":"七言绝句","c":["梦觉篝灯曀曀明，碧鸡啼罢欲三更。","定知山雨阵头恶，但怪瀑声雷样鸣。"]},{"t":"游隐静往反四首 其三","f":"七言绝句","c":["一随俗驾走红尘，松竹生愁鹤怨人。","杯渡老师相悉否，野僧心地宰官身。"]},{"t":"游隐静往反四首 其二","f":"七言绝句","c":["烟树云生若有无，行舆咿轧路盘纡。","小风弄雨晴还落，身在龙眠水墨图。"]},{"t":"游隐静往反四首 其一","f":"七言绝句","c":["突兀南山万仞青，餍观山顶白云生。","今朝访道五峰去，却向白云生处行。"]},{"t":"游普向十首 其六","f":"七言绝句","c":["寺壁龙蛇石刻新，夔州十绝典刑存。","鹅溪为卷湖山去，拟与诗人到处论。"]},{"t":"游普向十首 其五","f":"七言绝句","c":["日冒风埃鬓脚黄，归怀绊骥可能忘。","谁知碧岭苍云外，占断人间五月凉。"]},{"t":"游普向十首 其四","f":"七言绝句","c":["齑盐未必劣僧蔬，尘里光阴易破除。","他日摩肩霄汉上，却须此室与藏书。"]},{"t":"游普向十首 其三","f":"七言绝句","c":["青林果熟星宿烂，修竹风来环佩鸣。","翠影扶疏僧宇静，吟馀屋角见云生。"]},{"t":"游普向十首 其二","f":"七言绝句","c":["一老昂藏物外高，陈陈胸次尽龙韬。","功名未疗湖山癖，却著袈裟替战袍。"]},{"t":"游普向十首 其一","f":"七言绝句","c":["西湖西岸三百寺，一一题名嗟未能。","他日诛茅追胜赏，却寻诗版验吾曾。"]},{"t":"游普向十首 其十","f":"七言绝句","c":["行穿老桧千寻影，归受凉荷十里风。","从此胜游萦客梦，梦随黄鹄下云空。"]},{"t":"游普向十首 其九","f":"七言绝句","c":["崇冈回首路萦盘，夕照明边小凭栏。","船閤浅沙催客上，玻璃影里见长安。"]},{"t":"游普向十首 其八","f":"七言绝句","c":["处士前身自水仙，天教清句纪山川。","即今秋菊寒泉意，双鹤飞来若个边。"]},{"t":"游普向十首 其七","f":"七言绝句","c":["远近僧垣共白云，萧然不著世间尘。","朝参夜讲庸何计，野饭山栖已可人。"]},{"t":"登頫江三绝赵宰增为四复次韵答之 其一 追和","f":"七言绝句","c":["泛香樽俎飞云上，著色江山泚笔前。","乾鹊鸣鸠共晴昼，长红短绿各华年。"]},{"t":"登頫江三绝赵宰增为四复次韵答之 其五 追和","f":"七言绝句","c":["东园北寺非无约，瘦骨禁寒未敢前。","寄语惊风并急雪，多情多感况中年。"]},{"t":"登頫江三绝赵宰增为四复次韵答之 其二 追和","f":"七言绝句","c":["流光何忍太匆匆，一段清欢欻梦中。","赖是缄藏玉雪句，老人他日苦头风。"]},{"t":"登頫江三绝赵宰增为四复次韵答之 其四 追和","f":"七言绝句","c":["两夜北风吹石裂，雪神骄蹇更淹留。","羁人坐叹肌生粟，媚白妖红耐此不。"]},{"t":"程帅寄诗见忆次韵四首 其四","f":"七言绝句","c":["子云属思旧深沉，脱手清诗语意新。","天上黄陈应首肯，授公此柄淑诸人。"]},{"t":"程帅寄诗见忆次韵四首 其三","f":"七言绝句","c":["车笠何人记旧盟，惟公不作白头新。","渠侬欲识九华伯，可但诗坛第一人。"]},{"t":"程帅寄诗见忆次韵四首 其二","f":"七言绝句","c":["清篇属我慰平沉，密密玄关领会新。","从此倚门麾捕影，更将形似许诗人。"]},{"t":"程帅寄诗见忆次韵四首 其一","f":"七言绝句","c":["扰扰飞潜易陆沉，化工刺手斩然新。","饮光一笑知谁继，试把玄机举似人。"]},{"t":"程言聚散有感次前韵 其三","f":"七言绝句","c":["垂柳摇丝千尺长，柳阴深处转鹂黄。","把杯借听歌声醉，绝胜酸寒尉溧阳。"]},{"t":"程言聚散有感次前韵 其四","f":"七言绝句","c":["步趁游人欢意长，谁交莺燕强雌黄。","凭栏凝伫多佳丽，底羡簪花醉洛阳。"]},{"t":"程言聚散有感次前韵 其二","f":"七言绝句","c":["群芳围坐引杯长，满目深红间浅黄。","寄语东君好怜客，水西花外慢颓阳。"]},{"t":"程言聚散有感次前韵 其一","f":"七言绝句","c":["不须劝醉翠眉长，莫问何时腰下黄。","剩喜相逢各强健，免教闻笛赋山阳。"]},{"t":"谢王提干召饮三首 其三","f":"七言绝句","c":["不惯香风拥妓车，分当清坐冷官衙。","归来自笑杀风景，却把茶瓯对菊花。"]},{"t":"谢王提干召饮三首 其二","f":"七言绝句","c":["宾筵笑语杂丝弦，说到山翁更粲然。","衰鬓岂应妆面侧，陈编只合粉袍前。"]},{"t":"谢王提干召饮三首 其一","f":"七言绝句","c":["坐上红衣未放歌，客间冷面釂金荷。","惊飞可待闻檀板，拟奈吾家故事何。"]},{"t":"谢刘提干墨竹见遗二首 其二","f":"七言绝句","c":["龙孙袅袅初辞箨，凤尾娟娟拟受风。","疏影向人翩欲舞，梦残依约月庭空。"]},{"t":"谢刘提干墨竹见遗二首 其一","f":"七言绝句","c":["王孙笔自徐州派，戏为诗翁写渭川。","眼底疏枝攲密叶，静含寒雨暝苍烟。"]},{"t":"谢两知县送鹅酒羊面二首 其二","f":"七言绝句","c":["麦生宜配卧沙羊，鹅炙仍便碧酒香。","陡觉今年好冬节，朝来红日为谁长。"]},{"t":"谢两知县送鹅酒羊面二首 其一","f":"七言绝句","c":["僧样斋厨冰样官，饥凭脱粟食无单。","不因同里兼同姓，肯念先生苜蓿盘。"]},{"t":"谢张德恭送糟蚶三首 其三","f":"七言绝句","c":["谁与江瑶角长雄，一时风味两无同。","吾儿不友王文度，底肯分甘及乃公。"]},{"t":"谢张德恭送糟蚶三首 其二","f":"七言绝句","c":["压倒淤泥白莲藕，半捐介甲露秾纤。","玉川水厄那知此，急具姜葱唤阿添。"]},{"t":"谢张德恭送糟蚶三首 其一","f":"七言绝句","c":["旧笺虫介甘温性，樽俎风流每策勋。","况复餔糟小酲后，眼中群品此其君。"]},{"t":"跋简斋二帖","f":"七言绝句","c":["夜光一百八十七，有底六丁忘下收。","密勿端知紫皇侧，镇欀犹计子孙谋。"]},{"t":"新林小憩见花二首 其二","f":"七言绝句","c":["略得花边一欠伸，罗衫归去满缁尘。","鸣鸠乳燕空多思，苦雨凄风不贷春。"]},{"t":"新林小憩见花二首 其一","f":"七言绝句","c":["白玉毬团青玉枝，幽芳不恨见春迟。","酴醾过后榴花未，管领风光更是谁。"]},{"t":"瑞岩寺三首 其三","f":"七言绝句","c":["已到平生未到山，朝来白水涨田间。","要须乐事成三绝，更倩诗翁露一斑。"]},{"t":"瑞岩寺三首 其二","f":"七言绝句","c":["横前石廪疑无地，步入莲宫别有天。","说道三山环弱水，不应回首羡巢仙。"]},{"t":"瑞岩寺三首 其一","f":"七言绝句","c":["岭岫周围罅缝无，胜流三百锁冰壶。","客来误作囚山想，猛忆门前自坦涂。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其十","f":"七言绝句","c":["诗到双峰自一家，纷纶仙卉杂天葩。","几时共载西湖去，千纸看公写物华。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其九","f":"七言绝句","c":["矲矮栏干锦绣筵，栏边仍泊女郎船。","凭栏笑指玄真子，不是诗仙是酒仙。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其八","f":"七言绝句","c":["已规觞咏了馀龄，径自无何到大庭。","左界何人与调护，酒星移近少微星。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其七","f":"七言绝句","c":["行行抚事念前贤，修竹祠西碧嶂前。","不复船归下双鹤，空缘酒渴酌寒泉。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其六","f":"七言绝句","c":["老来已谢著书忙，但向清游访睡乡。","寄语深师与包叟，可无客枕假云堂。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其五","f":"七言绝句","c":["何须履道写新图，不用悲歌缺唾壶。","岩壑清奇皆我有，利名缰锁向来无。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其三","f":"七言绝句","c":["重到西湖可便回，前年待得水芝开。","凭君问取闲鸥鹭，亲见跳珠溅客来。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其二","f":"七言绝句","c":["湖山引兴尚能长，小贷诗愁放酒狂。","蝴蝶应怜落春后，无聊时近绿樽傍。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其一","f":"七言绝句","c":["客舟日日野芳前，鶗鴂鸣时始息肩。","无絮可漂花可藉，良辰乐事属明年。"]},{"t":"暮春泛西湖次口号韵呈程待制十首 其四","f":"七言绝句","c":["几饭南山佛老宫，诗昌谭胜每舂容。","不妨重就山间宿，蔬笋香茶未阙供。"]},{"t":"漏泽院四绝句 其四","f":"七言绝句","c":["粹公颇似庐山远，美酒还因我辈沽。","想得静看豪饮罢，一灯弥勒伴跏趺。"]},{"t":"漏泽院四绝句 其二","f":"七言绝句","c":["隽游分破北窗眠，笑撚吟髭看控弦。","久袖飞驰银管手，为渠涂改角弓篇。"]},{"t":"漏泽院四绝句 其一","f":"七言绝句","c":["雪翎如扇十钧弓，霹雳声前玉斝空。","人似堵墙争指似，少年场里著衰翁。"]},{"t":"漏泽院四绝句 其三","f":"七言绝句","c":["将军弓力今羊侃，病渴归来似长卿。","抹羽尚堪支十槊，忆看衔尾饿鸱鸣。"]},{"t":"漫与","f":"七言绝句","c":["与世端如上濑船，还家稍办买山钱。","松风吹断蓬瀛梦，诗酒淋漓送暮年。"]},{"t":"管仲二首 其二","f":"七言绝句","c":["平生勋业载成书，胁制诸侯祇霸图。","盍继车攻奏嘉颂，迄今璧帛簉东都。"]},{"t":"管仲二首 其一","f":"七言绝句","c":["棠潜俄正鲁封圻，施伯安翔稛载归。","尸授夷吾宁复此，君臣应愧始谋非。"]},{"t":"题九老图二首 其二","f":"七言绝句","c":["帝怜忧国许归田，犹得幽居俯涧瀍。","应笑诗人赋招隐，茹芝带索只臞仙。"]},{"t":"题九老图二首 其一","f":"七言绝句","c":["凉亭燠馆尘埃外，野鸟溪花俎豆前。","但爱林泉映华发，岂知勋烈载青编。"]},{"t":"题人家壁","f":"七言绝句","c":["等是黄粱未熟时，车尘马足竟胡为。","山翁不起功名想，足谷多田正自奇。"]},{"t":"题史髯词卷二首 其二","f":"七言绝句","c":["南风未蛰浙江波，倦客闲愁似许多。","安得双鬟如阿素，红檀声里釂金荷。"]},{"t":"题史髯词卷二首 其一","f":"七言绝句","c":["方朔岁星仍客星，窃桃他日太狂生。","几时又泛灵槎去，平掇天孙翠织成。"]},{"t":"题史髯诗卷后二首 其二","f":"七言绝句","c":["脑脂侵眼耐昏眵，诗卷犹便小字题。","浪信奇方须损读，即今刮膜胜金篦。"]},{"t":"题史髯诗卷后二首 其一","f":"七言绝句","c":["平生一士万金多，更恨诗人饿涧薖。","羁旅忽成开笑口，软红尘底得阴何。"]},{"t":"题因师百雁图二首 其二","f":"七言绝句","c":["闻道崔公作芦雁，端如庄叟玩鯈鱼。","鶱翔唼啑妙百态，君看老因般礴馀。"]},{"t":"题因师百雁图二首 其一","f":"七言绝句","c":["蓼滩芦渚好徜徉，肯便云天去作行。","未用选奴防夜燎，不妨结伴傲晨霜。"]},{"t":"题因师蒲桃图二首 其二","f":"七言绝句","c":["晶荧压架绀珠圆，苒蒻萦风露叶鲜。","病酒人方渴羌似，为师开卷忍馋涎。"]},{"t":"题因师蒲桃图二首 其一","f":"七言绝句","c":["因师写物三昧手，公取天机付笔端。","坐想瑛盘分磊磈，忆尝贝齿冰甘寒。"]},{"t":"题因老松江烟雨图二首 其二","f":"七言绝句","c":["千里湖山宿雾昏，倚栏一笔解平吞。","渔郎好在收纶罢，想踞笭箵共一樽。"]},{"t":"题因老松江烟雨图二首 其一","f":"七言绝句","c":["远峰近薄鉴中浮，每泊行舟十日留。","雨望晴临俱不恶，最怜烟霭暝高秋。"]},{"t":"题毕直閤翻经图三首 其三","f":"七言绝句","c":["中原正朔合天王，细读遗书瘿作囊。","老子披图揩病眼，为公重炷石炉香。"]},{"t":"题毕直閤翻经图三首 其二","f":"七言绝句","c":["伯图无继昧尊王，独抱残经析渺茫。","地下威文应吐气，人间宋李解升堂。"]},{"t":"题吴子隆兼隐二首 其二","f":"七言绝句","c":["元亮官居亦松菊，次山生事有笭箵。","酒如欸乃声中醉，目向平反笑处青。"]},{"t":"题吴子隆兼隐二首 其一","f":"七言绝句","c":["盛吉低眉亦问囚，不疑断狱但春秋。","定知小试皮鞭罢，却唤樵青荐茗瓯。"]},{"t":"题坟庵壁四首 其四","f":"七言绝句","c":["寂寞江湖吏隐翁，平生纯默养胸中。","即今技痒馀诗癖，时眩晴霄作綵虹。"]},{"t":"题坟庵壁四首 其三","f":"七言绝句","c":["钟鸣已饭尚来游，竹好排门不待求。","争席馈浆吾不计，此身沧海信虚舟。"]},{"t":"题坟庵壁四首 其二","f":"七言绝句","c":["损益才通理洞明，不应知死异知生。","惜无人把宣尼语，说似当年尚子平。"]},{"t":"题坟庵壁四首 其一","f":"七言绝句","c":["糊口卑官似不逢，解将觞咏当千钟。","劣优何似隆中叟，投老归来作卧龙。"]},{"t":"题张省干扇","f":"七言绝句","c":["前溪天阔渌泱泱，溪上诗翁引兴长。","安得南风吹小艇，吟看千盖拥红妆。"]},{"t":"题杜彦敷山茶","f":"七言绝句","c":["丹艳浓妆媚晏温，谁招妃子醉时魂。","此花信出此君下，那有诗人来叩门。"]},{"t":"题驿舍二首 其二","f":"七言绝句","c":["官曹有底著迂疏，祇合江湖老钓徒。","萍梗可能忘在莒，莼鲈祇有梦归吴。"]},{"t":"题驿舍二首 其一","f":"七言绝句","c":["客到淮乡话楚乡，长将天末指襄阳。","如今漂泊君休问，又过襄阳十舍彊。"]},{"t":"题柏氏壁二首 其二","f":"七言绝句","c":["梦觉号呼攧鹞风，忽惊肤粟似深冬。","凄凉敛白收红后，赖有春醪琥珀浓。"]},{"t":"题柏氏壁二首 其一","f":"七言绝句","c":["客里春光似许忙，还家馀几酒边狂。","酴醾芍药芳期在，不问芜菁满意黄。"]},{"t":"题济胜七物 一拄杖","f":"七言绝句","c":["惊蛇却犬破莓苔，筇竹随公几往回。","龙化葛陂应未忍，为扶衰病作陈雷。"]},{"t":"题济胜七物 七村童","f":"七言绝句","c":["貌野言伧却近真，客前疏略不能嗔。","折花替我簪纱帽，看竹须渠问主人。"]},{"t":"题济胜七物 二扇","f":"七言绝句","c":["何人月样剪霜绨，改就新诗却自题。","为惜持杯折花手，免教遮日步苏堤。"]},{"t":"题济胜七物 三钱箧","f":"七言绝句","c":["与人替得杖头闲，日日莲塘柳岸边。","烂醉质衣吾不问，归时犹有买舟钱。"]},{"t":"题济胜七物 五酒榼","f":"七言绝句","c":["相从有命每倾舒，不寄辕端即坐隅。","肯落苏家悭妇手，深藏云待不时须。"]},{"t":"题济胜七物 六钉鞋","f":"七言绝句","c":["几步山间属雨馀，徐行犹可当安舆。","计功高出芒鞋上，傍险冲泥得屡书。"]},{"t":"题济胜七物 四笔囊","f":"七言绝句","c":["毛锥老去未轻投，革带罗囊特命收。","准拟西胡持酒处，偕翁濡首破诗愁。"]},{"t":"题赵秀才壁","f":"七言绝句","c":["日日危亭凭曲栏，几山苍翠拥烟鬟。","连朝策马冲云去，尽是亭中望处山。"]},{"t":"题赵景安二亭 尺五二首 其一","f":"七言绝句","c":["山亭缥缈五云连，瑞霭灵河最近天。","当念江湖吏尘客，举头见日独悽然。"]},{"t":"题赵景安二亭 尺五二首 其二","f":"七言绝句","c":["仙乐惯常醒醉梦，市香不断袭衣裾。","何须更羡城南杜，丹地黄扉即诏除。"]},{"t":"题赵景安二亭 云涛二首 其一","f":"七言绝句","c":["坐看银山捲坏云，涛头蜚过不逡巡。","世间壮观何人领，付与亭中笔有神。"]},{"t":"题赵景安二亭 云涛二首 其二","f":"七言绝句","c":["闛沓每疑坤轴动，撞唐更恐日车翻。","凭栏待得波声寂，擘絮依然挂海门。"]},{"t":"题项处士山堂二首 其二","f":"七言绝句","c":["久安楚俗眠云屋，又向吴侬倒药囊。","出处无心俱乐地，世间何处不山堂。"]},{"t":"题项处士山堂二首 其一","f":"七言绝句","c":["一庵小憩俗间劳，月牖风轩俯鸟巢。","我亦青衫倦游者，羡君先办盖头茅。"]},{"t":"题扇七首 其七","f":"七言绝句","c":["广寒二十五万户，跪奉素娥听指呼。","落屑欲堆悬圃满，人间但爱玉轮孤。"]},{"t":"题扇七首 其六","f":"七言绝句","c":["峨眉山北雪极目，方丈海中冰作壶。","我自飙轮随所往，怜渠局息寄洪炉。"]},{"t":"题扇七首 其五","f":"七言绝句","c":["裁就霜纨未副挥，濡毫欲下更迟迟。","昔游尚记芜湖夜，把酒中秋见月时。"]},{"t":"题扇七首 其四","f":"七言绝句","c":["东绢须题黄绢辞，老来斲句不能奇。","定知烁石流金日，记我持觞赏雪时。"]},{"t":"题扇七首 其三","f":"七言绝句","c":["闻道广寒修月手，静看如鉴忽如眉。","即今扇里乘鸾女，解笑嫦娥不自持。"]},{"t":"题扇七首 其二","f":"七言绝句","c":["吴霜有信镜先知，楚雨无踪梦自迷。","风榻烧香作僧过，罗襟得句为谁题。"]},{"t":"题扇七首 其一","f":"七言绝句","c":["桃叶渡头鱼噞春，莫愁堂上燕依人。","玉觞欲举心先醉，痛忆当时迹未尘。"]},{"t":"题扇集句五首 其五","f":"七言绝句","c":["绿槐高柳咽新蝉，绫扇唤风阊阖天。","见欲扫床悬麈尾，簟纹如水帐如烟。"]},{"t":"题扇集句五首 其四","f":"七言绝句","c":["自恨寻春去较迟，古来四事巧相违。","如今说著成离恨，曾为梅花醉不归。"]},{"t":"题扇集句五首 其三","f":"七言绝句","c":["竹里高亭灯烛光，月移花影上西厢。","蔗浆金椀冰盘冻，始信人间五月凉。"]},{"t":"题扇集句五首 其二","f":"七言绝句","c":["庭院深深深几许，美人绵渺在云堂。","落花游丝白日静，锦荐金炉梦正长。"]},{"t":"题扇集句五首 其一","f":"七言绝句","c":["宝扇重寻明月影，月边仍有女乘鸾。","主家阴洞细烟雾，姑射仙姿不畏寒。"]},{"t":"题高缙之剑室二首 其二","f":"七言绝句","c":["皇家威德憺遐荒，何物楼兰尚颉颃。","想见诗人攲枕处，云霄中夜有光芒。"]},{"t":"题高缙之剑室二首 其一","f":"七言绝句","c":["高郎櫑具映峨冠，沈燎茶铛一室安。","游刃圣经千载计，即今长铗未须弹。"]},{"t":"题乾明寺壁","f":"七言绝句","c":["不待车轮四角生，欲行还驻为交情。","又成一笑渌樽晚，诗卷竹风相与清。"]},{"t":"题龚养正孩儿枕屏二首 其二","f":"七言绝句","c":["眼中何止舞雩音，况是君家积庆重。","梦里送来烦孔释，要令门户继荀龙。"]},{"t":"题龚养正孩儿枕屏二首 其一","f":"七言绝句","c":["小屏光洁雪难如，写出嬉然同队鱼。","索句拥书皆薄相，笑啼嗔喜莫怜渠。"]},{"t":"题傅商卿家壁二首 其二","f":"七言绝句","c":["酒处清谭烛下棋，归期初未厌迟迟。","若为径作翩然去，明日阴晴可得知。"]},{"t":"题傅商卿家壁二首 其一","f":"七言绝句","c":["表表两卿吾莫逆，青刍白饭玉为醅。","因循桑下成三宿，解后花时更一来。"]},{"t":"题彭尉轩壁三首 其三","f":"七言绝句","c":["轩成首作梅仙客，再到园池更可观。","日有脊令栖小树，时看鸂鶒下前滩。"]},{"t":"题彭尉轩壁三首 其二","f":"七言绝句","c":["甓社家居水四环，房陵官舍祇重山。","客中一旦兼双美，山影江光衽席间。"]},{"t":"题彭尉轩壁三首 其一","f":"七言绝句","c":["小轩肯许置琴书，客邸僧垣总不如。","岂但郎君可棋酒，旧便江水煮江鱼。"]},{"t":"题椿桂堂四首 其四","f":"七言绝句","c":["雁影联翩上绛绡，庭兰再世更奇标。","义方可但燕山窦，行跨当年八叶萧。"]},{"t":"题椿桂堂四首 其三","f":"七言绝句","c":["蒙庄漫诧楚冥灵，独秀吾今陋却生。","更笑田家紫荆树，每随人意作枯荣。"]},{"t":"题椿桂堂四首 其二","f":"七言绝句","c":["灵椿移植自仙宫，丹桂年年不办供。","材荐明堂皆巨栋，君家培殖富阴功。"]},{"t":"题椿桂堂四首 其一","f":"七言绝句","c":["日日高堂笑脸新，五株芳桂拱灵椿。","枝萦非雾根盘石，共阅壶中不尽春。"]},{"t":"题溪桥雪月图","f":"七言绝句","c":["雪野无人访夜阑，冰壶绝景画中看。","桥边觉欠梅枝在，姑射嫦娥各耐寒。"]},{"t":"题臧子仪扇","f":"七言绝句","c":["买邻千万许儿赊，老子诗成赖指瑕。","门枕醴泉交让木，行人不问识君家。"]},{"t":"题潘德久侍儿扇","f":"七言绝句","c":["袜尘去眼恨成堆，赋客当年浪费才。","何似天风吹雾鬓，乘鸾新自月边回。"]},{"t":"题潮出海门图二首 其二","f":"七言绝句","c":["卷里涛波快一披，苍山踊起雪山驰。","浮天沃日无穷意，到我春窗病酒时。"]},{"t":"题潮出海门图二首 其一","f":"七言绝句","c":["绝岛平冈捲欲空，两崖相对屹穹崇。","即今画手兼诗笔，更与江山角长雄。"]},{"t":"赠包道二首 其二","f":"七言绝句","c":["何妨尘外却尘中，风舞寒漪月印空。","洗钵与渠同一饱，未忧交臂失回公。"]},{"t":"赠包道二首 其一","f":"七言绝句","c":["吟风啸月是真常，何处无何更有乡。","我与吕仙俱不死，静看乌兔幻炎凉。"]},{"t":"赠何符山人二首 其二","f":"七言绝句","c":["冷看俗态诙嘲里，缓阅年光醉梦间。","想得酒瓢诗卷外，此生无物更相关。"]},{"t":"赠何符山人二首 其一","f":"七言绝句","c":["小诗落纸粲春葩，传遍侯家与主家。","未怪东来将只影，十年囊笔饭京华。"]},{"t":"赠净慈主人五首 其五","f":"七言绝句","c":["师似蜚云未定居，我方薄宦走江湖。","鼎山他日过从约，借问今犹记得无。"]},{"t":"赠净慈主人五首 其四","f":"七言绝句","c":["寺前寺后花如锦，相见游人拨不开。","好把春光供一笑，从渠尘袜涴苍苔。"]},{"t":"赠净慈主人五首 其三","f":"七言绝句","c":["识君方吏虎存边，已叹疲羸雪满颠。","别后漂零怯人问，穷山往返费三年。"]},{"t":"赠净慈主人五首 其二","f":"七言绝句","c":["炊珠爨桂走门徒，须信高人道不孤。","政使过门尽侯主，也须拳棒做工夫。"]},{"t":"赠净慈主人五首 其一","f":"七言绝句","c":["平时野饭与岩栖，忽向皇都作住持。","见说禅和蜂蚁聚，心闲祇似瑞岩时。"]},{"t":"赠相士潘翁二首 其二","f":"七言绝句","c":["凉凉寂寂不关天，自诡诗穷五十年。","君比老夫痴又甚，更教斲句当行缠。"]},{"t":"赠相士潘翁二首 其一","f":"七言绝句","c":["平时镜里笑头颅，道我为官已近谀。","但遣馀年犹甲子，不妨绛老尚泥涂。"]},{"t":"赠相者二首 其二","f":"七言绝句","c":["材同樗栎将安用，官带笭箵亦漫为。","更欲品题人所弃，君痴尤胜老夫痴。"]},{"t":"赠相者二首 其一","f":"七言绝句","c":["人言庞艾可功名，独取臞儒子么生。","槁项犹多吟拥鼻，好移君眼与公卿。"]},{"t":"赠赵丞四首 其四","f":"七言绝句","c":["共约京都看早春，枣骝缓踏软红尘。","要君弹压湖山景，莫惜新篇举似人。"]},{"t":"赠赵丞四首 其三","f":"七言绝句","c":["我衰但作一廛计，认古宣城为故乡。","待得故人来作牧，试吟打鸭起鸳鸯。"]},{"t":"赠赵丞四首 其二","f":"七言绝句","c":["君家鸾镜照芙蓉，笑我衣襦绽不缝。","想见后堂颓醉玉，梁州按罢晚妆慵。"]},{"t":"赠赵丞四首 其一","f":"七言绝句","c":["老懒无诗到雪梅，僧窗驼坐拨萁灰。","朝来好语成快读，匕箸惊投不为雷。"]},{"t":"赠郭高叔三首 其三","f":"七言绝句","c":["翠扇红牙浅黛愁，梁尘飞下晚云留。","贯珠未竟金杯侧，却欠周郎一转头。"]},{"t":"赠郭高叔三首 其二","f":"七言绝句","c":["燕台赋就尚缄囊，已作新声绕杏梁。","见说负山常夜半，能言鹦鹉枉关防。"]},{"t":"赠郭高叔三首 其一","f":"七言绝句","c":["护香深閤写乌丝，有底朱楼望得知。","与问天津倚栏客，庸非青琐窃桃儿。"]},{"t":"赠琴妓二首 其二","f":"七言绝句","c":["千纸争传戛玉词，一庭浑卧借书瓻。","从今有问新知识，径说江城女项斯。"]},{"t":"赠琴妓二首 其一","f":"七言绝句","c":["梦中曾揖蔡文姬，焦尾亲传半夜衣。","莫向诗人弹别鹄，免烦衰泪对君挥。"]},{"t":"襄阳二首 其二","f":"七言绝句","c":["采药仙人去不还，鹿门山翠郁孱颜。","霜髯尚困卑官缚，自问胡颜上此山。"]},{"t":"襄阳二首 其一","f":"七言绝句","c":["自怜薄宦走红尘，相见山灵厌俗氛。","咫尺岘山无计到，祇应飞雨是移文。"]},{"t":"丁酉道中暮春","f":"五言律诗","c":["去家如昨日，节物转头非。","风处绿自舞，雨馀红顿稀。","野桥平水过，村路蹑花归。","趁得酴醾在，筝琶拂旧衣。"]},{"t":"丁簿到芜湖书不至","f":"五言律诗","c":["几日到于湖，交情未合疏。","相望百里地，不寄一行书。","待此宽相忆，何人念索居。","朔风吹雁断，徙倚正愁予。"]},{"t":"七夕","f":"七言律诗","c":["龙旌凤扇一相迎，知费青禽几寄声。","天上经年才旧约，人间转盼便深更。","凉河只向樽前落，微月偏来酒面明。","后夜玉琴弹别鹤，独应乾鹊梦魂惊。"]},{"t":"九日登神居留题","f":"七言律诗","c":["行行十刻冒风沙，骤喜深堂放马挝。","旋报阴云漏红日，共追佳节把黄花。","多烦沽酒留元亮，莫漫移文调孟嘉。","未竟笑谭人树醉，檐栖片月欲翻鸦。"]},{"t":"九日登楼","f":"七言律诗","c":["县曹逢节犹忙迫，阴雨乘秋每接连。","九日欢娱异前日，几年晴霁有今年。","湖山入座褰珠箔，萸菊挼香荐玉船。","帽委西风判一醉，故人应未笑华颠。"]},{"t":"十六夜张丞有诗次韵","f":"七言律诗","c":["灯夕胜游皆遌意，可无歌酒答丰年。","云藏玉斧重修月，乐奏壶仙小隐天。","雁阵低空危欲堕，龙公驱雨未成眠。","惟应铁锁银花句，落纸明朝万口传。"]},{"t":"又对厅","f":"七言律诗","c":["黄堂绿影转槐龙，锦绣围中度好风。","珠履相辉人峙玉，金罍更劝酒如空。","逢辰正自千龄会，胜日何妨一醉同。","来岁从公话今日，钧天应簉未央宫。"]},{"t":"又对厅","f":"七言律诗","c":["绿舆初下玉龟山，小驻黄堂相府莲。","上客居多天下士，主人况自地行仙。","九光霞里闻谭笑，三素云中度管弦。","来岁日边桃荐碧，帝觞应共醉钧天。"]},{"t":"又通衢","f":"七言律诗","c":["清微风动万年枝，瑞纪流虹诞圣时。","天上玉卮山比寿，侯邦锦席酒如池。","满城淑气生英簜，夹道欢声度綵旗。","来岁望公天仗侧，尚应回首记吴儿。"]},{"t":"又悼石湖老人","f":"七言律诗","c":["老商笑不待三年，枵腹人人得果然。","商俗均沾傅岩雨，中行羞死绕朝鞭。","探原已茹丘轲胾，落笔聊差屈宋肩。","缅想神游知有处，定骖鸾鹤戏芝田。"]},{"t":"上巳溪上燕二首 其二","f":"七言律诗","c":["杜若洲边卓旆旌，佳晨一醉万金轻。","春光仅有一分在，天气可能三日晴。","解道兰亭亦陈迹，肯吟楚些怆幽情。","人生到处皆儿戏，笑看争标斗两鲸。"]},{"t":"上巳溪上燕二首 其一","f":"七言律诗","c":["后溪分占羽觞浮，雷隐欢声半棹讴。","况我闲官似犀首，为渠领客作鳌头。","玻瓈影里妆光腻，桃李香中步障留。","病骨得晴堪近酒，与君同拜醉乡侯。"]},{"t":"上外朝山","f":"七言律诗","c":["度陇凌坡冒百艰，今朝又上外朝山。","当车狠石通人过，交道飞萝要手攀。","猿坐泬寥犹啸诧，雁惊巉绝故飞还。","临风却快尘埃眼，全楚山川指顾间。"]},{"t":"上峨桥早行","f":"七言律诗","c":["一从箠楚替陈编，渐惯山行野店眠。","白氎风霜鸡唱后，黄尘岐路马蹄前。","光阴付我千茎雪，伏腊何时二顷田。","寄语淮乡隐君子，浪言梅福是神仙。"]},{"t":"山行寄程帅","f":"七言律诗","c":["雨馀支径湿平沙，恰称卑官下泽车。","杂树暝烟森立槊，乱峰迎客俨排衙。","水禽时弄蹁跹影，野草争开细碎花。","久忆山行此如愿，不应回首更思家。"]},{"t":"山居十首 其十","f":"五言律诗","c":["丁年陪友旧，尘雾去骎骎。","不赖学问力，终孤云水心。","无波真古井，跃冶岂祥金。","抚己知今是，扁舟钓碧浔。"]},{"t":"山居十首 其九","f":"五言律诗","c":["一室市声外，生经良不孤。","园花非独笑，风竹巧相娱。","为客求鹅母，供家课橘奴。","残年温饱尔，外此亦何须。"]},{"t":"山居十首 其八","f":"五言律诗","c":["蕉鹿谢依乘，孤高乃得朋。","闲谈每褐父，清晤或邻僧。","止酒玄真子，居家杜伯升。","此心安隐处，蜩鸴傲鹍鹏。"]},{"t":"山居十首 其七","f":"五言律诗","c":["萍梗才糊口，爬沙亦畏涂。","悠然三径地，有此百金躯。","乘兴聊吟笔，无弦且槁梧。","幽居喜客醉，未遣秫田芜。"]},{"t":"山居十首 其六","f":"五言律诗","c":["涉世惯多遌，还欣惬此心。","鸡孙当岁稔，竹母值秋阴。","言配香粳软，行须绿影深。","继今摩腹去，风日更萧森。"]},{"t":"山居十首 其五","f":"五言律诗","c":["鸟息我亦倦，行行取径微。","石棱妨错足，藤蔓每钩衣。","森木各天籁，连山同夕晖。","推门吟袖冷，满带野风归。"]},{"t":"山居十首 其四","f":"五言律诗","c":["居深自少客，儿辈省应门。","日课午钟饭，生涯三亩园。","嗜鱼亲蜑户，辍果及王孙。","不惜苔钱破，横纵步屧痕。"]},{"t":"山居十首 其三","f":"五言律诗","c":["忽作断过访，经旬闲瘦筇。","慵添和诗债，病减灌园功。","石鼎袅轻碧，庭柯零碎红。","竹君如见慰，竟日啸窗风。"]},{"t":"山居十首 其二","f":"五言律诗","c":["咀毒横戈地，财堪博一羞。","时流正攘臂，老子解抽头。","秦楚蜗两角，蹠夷貉一丘。","向来回晚照，了不见全牛。"]},{"t":"山居十首 其一","f":"五言律诗","c":["山间有好事，时肯问何如。","束送箸头薤，鲜分匙面鱼。","披襟偕我饱，揽发为君梳。","一笑尘劳外，都无病可祛。"]},{"t":"马息山","f":"七言律诗","c":["猿蹊鸟道且攀隮，暝霭顽苍只尺迷。","狠石忽开防地裂，屯云不散讶天低。","眼高欲了三千界，梦断犹惊七百梯。","回望故山真可指，杜鹃肠断为谁啼。"]},{"t":"书刘元之教授劄子后","f":"七言律诗","c":["碧酒清歌兴未央，挽留行色为风光。","小人政自属餍足，老子工于作乐妨。","舞雪放闲愁踏月，梦云惊散冷禁霜。","明朝一寄相思字，旅雁无情亦断肠。"]},{"t":"书怀二首 其二","f":"五言律诗","c":["薄宦爬沙地，平生一不施。","才名将底用，齿发欻如斯。","自笑书汗马，谁今手不龟。","惟馀五色笔，忍赋四愁诗。"]},{"t":"书怀二首 其一","f":"五言律诗","c":["俛仰人间世，才为一笑资。","百年羊胛熟，万事虎头痴。","文字聊遮眼，功名浪朵颐。","浮生如此尔，况复病馀衰。"]},{"t":"仁于庵","f":"五言律诗","c":["䆉稏围僧屋，檀栾隔槿篱。","月池聊濯足，雪壁剩留诗。","里社皆囷廪，钟鱼亦岁时。","平生松隐赋，回首十年迟。"]},{"t":"元日","f":"七言律诗","c":["爆竹声中杂笑呼，斗杓插海寺钟初。","椒觞带梦随小饮，桃板得诗仍自书。","愒日晚涂知内讼，占风吉卜定非虚。","新年旧管新收累，大府隆宽傥贷予。"]},{"t":"元日访丁端叔安抚二首 其二","f":"七言律诗","c":["节中应接可辞烦，客子回车重慨然。","比我过秦应一笑，想君出峡富千篇。","前知此别非久别，定复新年胜故年。","红药紫薇方次第，莫占风色问春田。"]},{"t":"元日访丁端叔安抚二首 其一","f":"七言律诗","c":["几夜徒劳梦帝宸，行赀已橐更逡巡。","北山祇合追逋客，南道于今欠主人。","表表德名当世重，堂堂公议有时申。","继今重策冲霄足，鹗表胡宁后隐沦。"]},{"t":"元夜病起二首 其二","f":"五言律诗","c":["节物撩佳兴，浮生盍自宽。","山城如许乐，灯市不多寒。","微步漂香细，行歌惜夜阑。","何人攲醉帽，朱袖簇归鞍。"]},{"t":"元夜病起二首 其一","f":"五言律诗","c":["霁色莫澄鲜，和声入管弦。","人家无事日，时节放灯天。","璧月红尘外，东风绿酒前。","强陪儿女笑，病骨得轻便。"]},{"t":"厅事落成致语口号","f":"七言律诗","c":["向晚帘栊上玉钩，县人应指小瀛洲。","龙兰烟外调宫羽，罗绮香中拥献酬。","百祀规模新壮观，一时文武极风流。","月明鼓吹烦重赋，终恐清新愧少游。"]},{"t":"天申节致语","f":"七言律诗","c":["遐想云璈奏未央，璇舆金箓庆生商。","九光霞里停仙仗，万岁声中奉帝觞。","天上擗麟供乐事，人间舞凤侈恩光。","小臣愿效华封祝，试颂灵椿寿圣皇。"]},{"t":"太硕人臧氏挽章二首 其二","f":"七言律诗","c":["帝恩三沐寿亲筵，更数何人福庆全。","纸眩鸾回馀旧诰，地占牛卧忽新阡。","阴功不倚长年药，补处仍开上品莲。","欲纪哀荣付丰石，诸儒当有笔如椽。"]},{"t":"太硕人臧氏挽章二首 其一","f":"七言律诗","c":["德风千祀蔼芳馨，生享修龄殁更荣。","早岁衣冠贤德耀，莫年门户寄升卿。","迹陈莫嗣登堂拜，匏系空驰执绋情。","里巷万人缌布会，一应如我泪河倾。"]},{"t":"文炳近岁节感怆作诗宽之","f":"七言律诗","c":["严侯才气旧无朋，晚作江淮肉食僧。","饱对风烟吐膏馥，时因节物动销凝。","君今宛是林和靖，我亦何如杜伯升。","浊酒寒菹共一笑，未妨同剔课诗灯。"]},{"t":"无题三首 其二","f":"五言律诗","c":["浪出嗟何补，归来乐有馀。","山川付不借，天地托蘧庐。","酒熟聊呼客，钩垂不在鱼。","平生栖遁意，政用盖迂疏。"]},{"t":"无题三首 其三","f":"五言律诗","c":["卧病十四五，秋来身自轻。","已拚不籍在，宁复可怜生。","每笑隐者传，尚存身后名。","灌园聊日力，分药且交情。"]},{"t":"无题三首 其一","f":"五言律诗","c":["薄宦受风梗，还家归岫云。","行人与乔木，老色竟平分。","末路惭周朴，穷交有墨君。","看渠绶若若，千骑诧乡枌。"]},{"t":"王母致语口号","f":"七言律诗","c":["天仗凌晨拱未央，君王亲奉紫霞觞。","社鸣当纪乾坤辟，筴授端知日月长。","为祝尧龄辞翠水，闲留羲驭顿扶桑。","儿家不上千秋鉴，自摘蟠桃寿圣皇。"]},{"t":"邓倅有诗次韵","f":"七言律诗","c":["袖手从公辟不怀，天心月胁有馀才。","将坛贾勇知无敌，册府新除定见催。","楚国谁今衙屈宋，欧门我亦后苏梅。","锦囊得句无虚日，尽卷淮山胜槩回。"]},{"t":"冬至","f":"五言律诗","c":["至节占天意，丰登又必然。","相风绿漪静，宾日矞云鲜。","比屋皆生意，穷阎有醉眠。","端容衰病宰，索句海山前。"]},{"t":"对客再次韵","f":"七言律诗","c":["客来一笑同乡味，便粉秋菰刷藕泥。","糟浥子姜仍旧法，笼缄乾笋俨新题。","白鱼紫蟹空濡沫，窘兔惊麋想砀迷。","自揣臞儒合蔬粝，放麑终恐愧巴西。"]},{"t":"归有日喜作","f":"七言律诗","c":["夜灯晨饭棘围重，槛束飞猱鹤在笼。","敢效骚人悲迫阨，祇防举子诮冬烘。","抟风定有庄鹏化，得隽从知冀马空。","明日还家压新酒，菊登金蕊拒霜红。"]},{"t":"归自湖西","f":"五言律诗","c":["晨具湖西饭，还家腹果然。","怒风长擘席，急浪不鸣船。","身觉青冥上，情留白鸟边。","衰年端一快，整帽向云天。"]},{"t":"归欤老秋","f":"七言律诗","c":["已办求田问舍谋，登临那复更悲秋。","蟹肥与客争先把，稻熟催儿彻晚收。","霜后峰峦添峭措，波间鸥鹭剧风流。","寰中胜处天应惜，付与痴儿祇暗投。"]},{"t":"正月十六夜大雪次张守诸公韵二首 其二","f":"七言律诗","c":["诗款铃斋到即通，细工时肯博粗工。","政声已独当时步，人士饫观前辈风。","未分清新命开府，可能简远尽安丰。","谭间和气熏人醉，不觉栖栖客路中。"]},{"t":"正月十六夜大雪次张守诸公韵二首 其一","f":"七言律诗","c":["阳阖阴开意莫穷，东君衒巧似良工。","红莲熄燄人收市，丹杏开时雪滚风。","韵语真宜咏飞絮，短歌当有颂元丰。","一番壮观俄漂忽，已落诗人卷轴中。"]},{"t":"正月十四日雪","f":"七言律诗","c":["乡园灯市颇豪奢，客子扁舟恰到家。","月姊层云藏宝鉴，雪神千手扑天葩。","未容火树陪宵燕，谩说江梅擅岁华。","苦忆醉穿罗绮阵，小軿吟度赤城霞。"]},{"t":"正仲和帅属被盗二首 其二","f":"七言律诗","c":["向来忠信倚垣墙，诲盗如今坐慢藏。","望意漫言疑圣智，奇文不合吐光芒。","玉川空屋遭窥瞰，子敬青毡果在亡。","赖有平生千牍在，未妨捃载作归装。"]},{"t":"正仲和帅属被盗二首 其一","f":"七言律诗","c":["衣囊缄鐍竟胡为，祇与偷儿便挈携。","髻重得无猜祖珽，璧亡遮莫议张仪。","馆人求屦古未免，有力负山人得知。","不用经营办春服，旧纫兰芷扈玄蓠。"]},{"t":"正觉寺","f":"七言律诗","c":["细穿诘曲上高寒，一鹫青冥杳霭间。","栏楯攲浮沧海影，东南重见紫金山。","方壶入眼鲸堪跨，璧月依人桂易攀。","闻说老禅佳寝饭，一生无梦落尘寰。"]},{"t":"用赠朴翁旧韵二诗送徐南卿南归 其一","f":"七言律诗","c":["飞鹏尺鴳计穷通，今古幽人一笑中。","等是劳生浮大块，谁能诡遇诧良工。","书堪引睡聊遮眼，酒可祛愁胜作公。","此意平章有同社，绝怜相望马牛风。"]},{"t":"用赠朴翁旧韵二诗送徐南卿南归 其二","f":"七言律诗","c":["莫将半菽羡千钟，生世谁非囿数中。","荐福议碑雷已震，浩然遌意句徒工。","我知寒饿怜颜阖，人说乘除有志公。","穷鬼趁渠来败类，秋禾一昔仆霜风。"]},{"t":"石城","f":"七言律诗","c":["山岩水缭石为城，千古馀风尚典刑。","竞诧君王启蓝缕，不无艇子载娉婷。","流连犹问圭堪柲，兆朕虚传蜜作萍。","更惜谗锋发兰尚，祇今日月炳骚经。"]},{"t":"石湖生日致语口号","f":"七言律诗","c":["寿筵高敞老仙家，帘影中间五色霞。","碧酒旧须麟作脯，雕盘新荐枣如瓜。","玉壶缥缈非尘世，金狄依稀记岁华。","胜日年年攲醉帽，鬓香长点吉云花。"]},{"t":"立春","f":"五言律诗","c":["春信葭灰动，寻知寒事休。","光阴从冉冉，身世判悠悠。","鬓影看银胜，官期志土牛。","羸骸更元命，惜为斗升留。"]},{"t":"立春前一夕雪二首 其二","f":"七言律诗","c":["雪龙侵夜正衔枚，破晓郊原玉作堆。","云叶攀翻徒自舞，瑶花顷刻为谁开。","土膏已遽宜农事，綵胜何妨映酒杯。","幻作冰壶天一噱，梦回品物各春台。"]},{"t":"立春前一夕雪二首 其一","f":"七言律诗","c":["天仙几夜集瑶台，剪水筛琼不受催。","直遣瑞花将腊去，尽驱和气与春回。","坐窗客有吟飞絮，对酒人应唱落梅。","雪与相如俱末至，可能草赋压邹枚。"]},{"t":"交割州事致语口号","f":"七言律诗","c":["一时律吕韵金丝，用播中和乐职诗。","所喜玳筵重启日，还当璧月再圆时。","伊凉聒夜铿千杖，兰蕙回春艳十眉。","明日酒醒还得句，东游夸与大堤儿。"]},{"t":"任满交割郡事致语口号","f":"七言律诗","c":["星屏已喜一樽俱，嗣启芳筵合郡符。","袅袅细香生玉醴，飔飔凉吹度冰壶。","锦纹眩旋明回雪，云影依微觅贯珠。","乘醉言分当卜夜，火城璧月共通衢。"]},{"t":"任满交割倅事致语口号","f":"七言律诗","c":["黄堂冰峙两飞仙，不遣纤尘到绣筵。","龙麝香中挥玉麈，蕙兰丛里釂金船。","即今别乘符初合，伫看丹墀璧再联。","来岁凉飔生殿阁，帝觞同捧听钧天。"]},{"t":"再口占次韵","f":"七言律诗","c":["君家朱閤隔嚣尘，可欠宾筵兰蕙春。","横草定铭鞮汗石，穿杨新赐上方银。","几时酾酒招嘉客，不假倾囊得丽人。","莫坐风悭仍雨涩，祇将诗笔诧无邻。"]},{"t":"再用前韵赠高司理共八首 其八","f":"七言律诗","c":["帝旅曾观武事扬，如君文势整堂堂。","了知一笔无前古，坐遣诸生丧所长。","丹桂高攀霄汉迥，捷书西下姓名香。","贝宫鳌禁应馀地，看展平生补衮章。"]},{"t":"再用前韵赠高司理共八首 其七","f":"七言律诗","c":["腰钱几夜梦维扬，上雨傍风祇此堂。","人笑铅刀那用割，自知袜线岂能长。","课诗坛畔独飞动，问字人来且碧香。","径欲披衣还旧隐，二天宁久溷苏章。"]},{"t":"再用前韵赠高司理共八首 其六","f":"七言律诗","c":["苏李宗风我举扬，少陵公按子开堂。","官曹此地文书省，诗社从今日月长。","山滴晓烟收后翠，莲漂天女戏时香。","可孤煮饼分彊韵，正使铜花涩印章。"]},{"t":"再用前韵赠高司理共八首 其五","f":"七言律诗","c":["俗里毫丝起抑扬，请君时闭读书堂。","渭清肯混泾流浊，凫短徒忧鹤胫长。","千载流传防造次，百年表立要馨香。","了知此印君堪付，过眼尨凉忽报章。"]},{"t":"再用前韵赠高司理共八首 其四","f":"七言律诗","c":["诗语庸非自播扬，流传朋旧定哄堂。","儒书投老空成癖，舞袖平生不解长。","黄鸟啄残丹杏颗，清风摇动绿筠香。","山城寂寞便吾懒，劣胜精神弊句章。"]},{"t":"再用前韵赠高司理共八首 其三","f":"七言律诗","c":["衰宗如此况他扬，碌碌诸雏欠肯堂。","薄宦幽忧殊未醒，故园归梦可胜长。","杯盘顿顿家鸡嫩，翁媪呜呜社酒香。","犹记比邻笑行客，夏畦龙断为金章。"]},{"t":"再用前韵赠高司理共八首 其二","f":"七言律诗","c":["帅幕群才赖激扬，衰迟犹喜后升堂。","雷封局缩聊偿债，衮字褒嘉但寸长。","再试真成不龟药，九言终佩辟邪香。","龙门梦断谁知己，几诵桑阿赋末章。"]},{"t":"再用前韵赠高司理共八首 其一","f":"七言律诗","c":["少年场里独鹰扬，他日悬知玉作堂。","小试问囚穷两造，徐看载笔擅三长。","得诗遽眩珠玑烂，玩味还疑齿颊香。","风月无穷才不尽，坐须乔木拥千章。"]},{"t":"再用韵寄丁知县三首 其三","f":"七言律诗","c":["别时把酒欲沾襟，楚翼吴鳞要嗣音。","撞玉餍听辞客语，断金深得故人心。","对床风雨终前约，满眼湖山念独吟。","何日水云淮上宅，草荒三径肯深寻。"]},{"t":"再用韵寄丁知县三首 其二","f":"七言律诗","c":["南楼酌酒未分襟，啅鹊啼乌亦好音。","晴日倒红生笑颊，烟梧摇渌涨杯心。","可堪岁月供行色，尽把江山博醉吟。","不继芜湖留十日，焦峰浮玉恣幽寻。"]},{"t":"再用韵寄丁知县三首 其一","f":"七言律诗","c":["旗亭风月小披襟，慰我东归听足音。","潮水去来当有信，岫云出入自无心。","酒杯乘兴从妨梦，诗律缘愁久废吟。","明日扬舲回白首，烟横北固棹千寻。"]},{"t":"再次习池诗韵寄程帅二首 其二","f":"七言律诗","c":["春意垂垂如我老，客怀领略欠当时。","倏惊鶗鴂鸣清昼，便有蜻蜓点碧池。","酒榼相过但溪友，锦囊馀几问庐儿。","芳辰渠尽人离索，苦念从公乘烛嬉。"]},{"t":"再次习池诗韵寄程帅二首 其一","f":"七言律诗","c":["南园胜绝真堪画，边上谁为李伯时。","山纳嫩岚侵密坐，花骈红影闯清池。","吟笺传遍鸳鸿友，舞袖轻于翡翠儿。","东府西州皆四釜，若为长伴酒边嬉。"]},{"t":"再次张丞韵","f":"七言律诗","c":["龙职阴晴肯转圜，寒侵春事倍常年。","弥旬稔听盆翻雨，一室何殊瓮里天。","多病可堪严酒戒，高舂未慭枕书眠。","忘忧蠲忿疑无策，小草论功亦浪传。"]},{"t":"再次杨宰游土山韵","f":"七言律诗","c":["志公岩顶云萦绕，罗汉洞前山郁盘。","鲧禹镌镵那用许，乾坤包纳若为宽。","我行六月犹春服，谁遣千岩起暮寒。","思与三花古仙伯，往还游戏辔青鸾。"]},{"t":"再次前韵二首 其二","f":"七言律诗","c":["起柁扬帆趁便风，狎鸥惊雁水烟中。","裹香荐彘聊随俗，计日听鸡等自公。","诗句涤愁收一一，酒杯浇别悔匆匆。","与君二纪陈雷契，犹遣时人笑两穷。"]},{"t":"再次前韵二首 其一","f":"七言律诗","c":["解缆征涂一怆神，房陵十舍望西秦。","苦无勋业裨昭代，久分江湖著老身。","三楚上游常定伯，六朝陈迹渺愁人。","不缘俛仰悲凉甚，可博临风得句新。"]},{"t":"再次赵侯韵","f":"七言律诗","c":["理窟疏明面面通，如君襟抱古贤同。","孤标碧落行霜月，胜韵芳林度蕙风。","妙语宁惟压元白，大封端合启龟蒙。","规恢伫看收功去，自勒丰碑纪殪戎。"]},{"t":"再次韵 其三","f":"七言律诗","c":["横前整整万全兵，自笑空弮借背城。","更遣齐竽混东郭，坐令鹄卵化南荣。","黄陈得法仍宗派，甫白论情自弟兄。","顾我无能邹贾役，放公笔力擅西京。"]},{"t":"再次韵 其四","f":"七言律诗","c":["因诗衰病顾徒然，凿井今犹未及泉。","药幻霜须端有待，囊缄玉唾愧无传。","冥心拟学无言子，授诀今犹不老仙。","探妙卫生俄两得，信知穮蓘解逢年。"]},{"t":"再次韵 其二","f":"七言律诗","c":["从公囊笔看西边，不比分弓出酒泉。","觞咏每忘秋漏永，平安晏有夕烽传。","痼肠顿已蜂腰病，妙手亲逢鹤背仙。","归捋霜须诧儿子，为翁试校故新年。"]},{"t":"再次韵","f":"七言律诗","c":["好时好节工恼客，投老祇思深闭关。","鹤膝痛医终是病，蛾眉公夺岂容悭。","浩歌已减落梅曲，苦思更妨颓醉山。","冷语陋姝何所似，贫家矮屋劣成间。"]},{"t":"再次韵","f":"七言律诗","c":["解橐临风得好怀，祇令公等费诗才。","行装并喜鸱夷满，春意如烦羯鼓催。","饭白重供飞雪鲙，眼青还对照溪梅。","滞留不恶归仍好，笑杀山阴兴尽回。"]},{"t":"再次韵 其一","f":"七言律诗","c":["门第应疑甚不庭，翩随府檄下山城。","江梅作意先秋拆，槛菊多情擅晚荣。","饮处凝香严画戟，客间张丈间殷兄。","主宾缥缈蜚埃外，信有人间小玉京。"]},{"t":"再次韵二首 其一","f":"七言律诗","c":["雪神不袖嘘枯手，嗣岁丰登预告成。","泚笔径烦书上瑞，载涂况已沸欢声。","骑驴有客搜新句，扶路何人趁晚晴。","一笑与渠分乐事，的知琼露胜宜城。"]},{"t":"再次韵二首 其一","f":"七言律诗","c":["饱食频频祇鸒斯，可堪迅景隙驹驰。","不逢犹是桐为弩，当价胡宁菌作芝。","天籁寂时三弄笛，楚山穷处四愁诗。","将坛可复宜衰病，此柄须君为主持。"]},{"t":"再次韵二首 其二","f":"七言律诗","c":["近墅何妨一再行，后车应著老弥明。","诗成直压抢榆上，谭胜宁容鄙吝萌。","鸥鹭一滩窥语笑，松筠千挺峙寒清。","从今好绘斜川集，莫靳流传到帝城。"]},{"t":"再次韵二首 其一","f":"七言律诗","c":["铅墨才为一饱谋，还因跋疐赋休休。","南州习俗难驯扰，北客迂疏易悔尤。","世味辰星今落落，归心风旆正悠悠。","知非况自五十九，为问衰翁底更求。"]},{"t":"再次韵二首 其二","f":"七言律诗","c":["欲辔青骢试小行，拥衾待得晓窗明。","端知霁日浑无价，可信啼鸠识未萌。","胜处风烟堪一醉，是家池馆擅双清。","不忧儿辈妨人乐，倚赖诗豪五字城。"]},{"t":"再次韵二首 其二","f":"七言律诗","c":["自揖高人拥鼻吟，湖滨诗酒便论心。","天教联绶同民社，日许挑灯订古今。","刺眼未妨翻著袜，跃炉宁问不祥金。","简编自有千年计，迟子追还正始音。"]},{"t":"再次韵二首 其一","f":"七言律诗","c":["郡政只今多暇日，名园欲到指苍茫。","能诗有客怜侯喜，好士惟公继郑庄。","促膝未妨渑似酒，转头当复玉为堂。","联金缀玉真吾事，剩刻坚珉表士乡。"]},{"t":"再次韵二首 其一","f":"七言律诗","c":["宋璞隋珠不当偿，平时佳思堕荒茫。","老规种秫师陶令，备有前茅愧楚庄。","蜂鹤搅肠空轧轧，鹳鹅严阵怯堂堂。","即今全胜输公等，自占床敷霸睡乡。"]},{"t":"再次韵二首 其二","f":"七言律诗","c":["历块飞黄可得追，加鞭十驾浪驱驰。","不应猗顿怀周朴，敢向天仙话土芝。","晚傍涪翁观落笔，了知高叟固为诗。","谬为恭敬吾何取，政恐龙泉有倒持。"]},{"t":"再次韵十首 其十","f":"五言律诗","c":["靖节瓶无粟，思归更命车。","慵垂督邮带，况袖子公书。","老我须闲适，尘缘得破除。","还应与鸥鹭，分占碧溪渔。"]},{"t":"再次韵十首 其九","f":"五言律诗","c":["仕为饥寒迫，归怜兴味长。","卜居从诡谲，勿药幸康强。","邻拟千钱买，书开万卷藏。","残年文字癖，更欲竞流光。"]},{"t":"再次韵十首 其八","f":"五言律诗","c":["进业湖海窄，取名丝缕轻。","因君论前辈，卫道有金城。","潢潦先知本，机缄贵用情。","灵台与秋日，烱烛古今明。"]},{"t":"再次韵十首 其七","f":"五言律诗","c":["中天有台阁，自问汝何能。","世路信薄命，吏曹须异称。","北归甘醉叟，西上且聋丞。","执友论文地，能无兴可乘。"]},{"t":"再次韵十首 其六","f":"五言律诗","c":["城西山水窟，早晚命篮舆。","胜绝僧能有，拘挛我不如。","山云侧步踊，雪壁细行书。","它日尝般礴，萧然乐有馀。"]},{"t":"再次韵十首 其五","f":"五言律诗","c":["朝家无阙政，秋禜继春雩。","恤纬怜吾怯，知言敢自诬。","闭阴宁董傅，为己肯杨朱。","未断蜗缘壁，仍多豕负涂。"]},{"t":"再次韵十首 其四","f":"五言律诗","c":["吴门诗酒伴，入社记吾曾。","香篆温难烬，铜壶冷易冰。","赓酬恕吾老，声价放渠增。","衰谢犹回首，思分蔀屋灯。"]},{"t":"再次韵十首 其三","f":"五言律诗","c":["客舍无佳晤，君来肯小留。","衣穿从见肘，赋好似登楼。","论世聊扪舌，输棋不计筹。","明窗坐方稳，寒日为谁遒。"]},{"t":"再次韵十首 其二","f":"五言律诗","c":["曲巷才人迹，泥涂没屐深。","未妨冲雨到，要伴掉头吟。","大巧专亭毒，何时扫疹淫。","浊醪君莫厌，排闷勉孤斟。"]},{"t":"再次韵十首 其一","f":"五言律诗","c":["重见发更白，羁栖偕在行。","余嗟遽如许，子亦可怜生。","玉粒书新券，霜蔬煮破铛。","诗成莫浪出，或取世儒轻。"]},{"t":"再次韵小雪馀言别 其一","f":"七言律诗","c":["舞霙飞霰闹中庭，已办持杯听渭城。","汉水襄山骤漂忽，早梅晚菊自枯荣。","雪神作意凌风伯，客子归途待日兄。","蹀躞霜蹄从踣铁，穿林䠞石赋于京。"]},{"t":"再次韵小雪馀言别 其二","f":"七言律诗","c":["语别诗翁玉麈边，已催歌舞压香泉。","日陪色笑庸何取，橐捃篇章敢浪传。","还舍剩书银笔字，今朝犹是玉壶仙。","后山幸自坡公客，谁遣离怀怆暮年。"]},{"t":"再次韵马主簿二首 其二","f":"七言律诗","c":["左顾衰翁底取斯，转头归马又西驰。","剩催阿买抄新稿，大胜斋房纪瑞芝。","乐岁人家皆有酒，高秋天气总宜诗。","霜花露菊留迎客，预戒西成省控持。"]},{"t":"再次韵马主簿二首 其一","f":"七言律诗","c":["冥搜成癖漫勤斯，缅想骚人正坐驰。","点化今逢万金剂，神奇蒸出九华芝。","三吴才隽应焚砚，万里风烟尽入诗。","盍与元刘论伯仲，未容郊岛更矜持。"]},{"t":"再次韵四首 其一","f":"七言律诗","c":["新酿开缸渌蚁浮，旧辞仍缺唾壶讴。","宦涂要处难插手，诗社丛中常引头。","倒载肯陪山简醉，反关莫厌孟公留。","秋田粗可供佳客，不比封君亦素侯。"]},{"t":"再次韵四首 其二","f":"七言律诗","c":["翰墨场中对抗旌，黄陈一笔万钧轻。","武安屋瓦秋鼙震，湘水波光夜月晴。","沮洳求鱼真自笑，渚涯向若倍驰情。","吾生恨落任公后，不见投纶掣海鲸。"]},{"t":"再次韵四首 其三","f":"七言律诗","c":["尸祝代庖良过矣，即今坐啸免嘲讴。","陶朱计食鱼万尾，景略有儿牛十头。","甫里过从劳梦寐，辋川归去忌迟留。","大弨一弛吾通袖，冷看逢蒙中射侯。"]},{"t":"再次韵四首 其四","f":"七言律诗","c":["韵语联翩到浚旌，楚珩非重夜光轻。","吟成品物回春态，诵处东风放晓晴。","抖擞锦囊娱我老，涤除愁斛见君情。","固应诗胆骜无本，刺手霜牙摩怒鲸。"]},{"t":"再次韵自诳简宾王二首 其二","f":"楚辞体","c":["庾郎胸次枉堆愁，冯衍才名迄不投。","归去来兮岁华晚，末如何矣鬓毛秋。","令威心事千年鹤，张翰生涯一叶舟。","回首月堂金谷梦，却怜海蜃结飞楼。"]},{"t":"再次韵自诳简宾王二首 其一","f":"七言律诗","c":["鱼避清澄鸟爱昏，陶翁归计酒盈樽。","山田雨足鸠呼妇，篱院春深竹有孙。","百首旋编新赋咏，三生犹忆旧精魂。","小摩他日红尘眼，闲送蜚云过海门。"]},{"t":"再次韵后篇戏朱 其二","f":"七言律诗","c":["似闻新酝敌宜城，想对檐花又独倾。","别乘工为海鲸吸，广文当念露蝉清。","投醪频遣春浮颊，盗印宁无夜闯营。","约束长须牢闭户，瓮间防有毕先生。"]},{"t":"再次韵后篇戏朱 其一","f":"七言律诗","c":["淙淙雨势欲沈城，衮衮辞源亦对倾。","辟户浑疑云气近，诵诗如在玉壶清。","射知猿臂须穿札，陈怯鱼丽且闭营。","只把两君新句法，为歌丰乐诏诸生。"]},{"t":"再次韵呈张守","f":"七言律诗","c":["使君刘白信其朋，笑我顽然粥饭僧。","打睡正便檐日煖，味诗还喜蔗浆凝。","破阴风软梅犹小，弄影云疏月渐升。","一自藏钩得新句，莫停吟笔到烧灯。"]},{"t":"再次韵呈张守 其一","f":"七言律诗","c":["乌衣雏燕正依栖，又见南风递赤泥。","宣室殊恩子夜对，天章清问御书题。","可无上药蠲民瘼，有待司南觉世迷。","好在论功继皋益，毋庸问管渎曾西。"]},{"t":"再次韵呈张守 其二","f":"七言律诗","c":["朋旧携持过陋栖，炊香瀹雪鲙拖泥。","酒浇礧磈聊娱老，诗愬酸寒最切题。","种秫集功今有约，对棋销日不嫌迷。","千奴别去平安否，时欲拿舟甓社西。"]},{"t":"再次韵呈章守","f":"七言律诗","c":["吾儒交贺得宗师，片善盱衡置百非。","小驻锋车宣室召，时观谭麈頖宫挥。","诗坛已许公馀论，邻烛何曾靳寸辉。","此意急须笺阿衮，不因鱼稻久忘归。"]},{"t":"再次韵张德恭二首 其二","f":"七言律诗","c":["平日疏愚但意行，每从师友仰高明。","如君况是庭兰秀，向我防讥冻芋萌。","柏悦悬知待松茂，渭流终不溷泾清。","新诗应敌才馀事，纸价于今贵列城。"]},{"t":"再次韵张德恭二首 其一","f":"七言律诗","c":["公家父子书林杰，力探希微析混茫。","膝上风流识文度，鯈游领解契蒙庄。","六花阵势容摩垒，五凤规模见肯堂。","自叹吾儿豚犬尔，祇宜耕牧守穷乡。"]},{"t":"再次韵复文炳","f":"七言律诗","c":["君犹芹泮老宾朋，我似房公再世僧。","烟径幽寻春澹沲，月窗冷语夜澄凝。","人情感旧多为祟，酒盏浇愁更计升。","笑命棋枰同永夜，旋添萁火上篝灯。"]},{"t":"再次韵送张守 其四","f":"七言律诗","c":["性资凉踽系时轻，青眼惟公底里倾。","砥柱颓波储硕望，阳春穷谷见高情。","青冥蜚上应回首，陆续诗来可待盟。","念我老无当世意，拟从樵牧寄馀生。"]},{"t":"再次韵送张守 其三","f":"七言律诗","c":["唾壶声里晚凉轻，风自虚徐月自倾。","诗好要从知者道，格高今识古人情。","三熏谁定分膏馥，十袭吾方守诅盟。","预恐幽居念离索，时须开卷慰愁生。"]},{"t":"再次韵送张守 其二","f":"七言律诗","c":["未解州符累已轻，辞源满意酒边倾。","颉颃前辈真无愧，褒拂迂儒每过情。","老境更堪听别语，书邮当复固齐盟。","吴山正合供酬唱，安得风前两翼生。"]},{"t":"再次韵送张守 其一","f":"七言律诗","c":["目送归帆风翮轻，赠诗还笑字攲倾。","如公风义仍知己，计我隆污合用情。","想觐龙颜新得意，未忘牛耳旧同盟。","周旋尚可诸公后，肯放江湖了此生。"]},{"t":"再次韵答节推二首 其二","f":"七言律诗","c":["亏成久不挠心旌，老阅人间百事轻。","却笑平生甘淡薄，每缘行乐问阴晴。","羽觞饧粥同春事，卧醉行歌见俗情。","击钵更遭强敌困，可能赤手控奔鲸。"]},{"t":"再次韵答节推二首 其一","f":"七言律诗","c":["透幕穿帘香雾浮，行云低影傍清讴。","游人是处歌鼓腹，佳客伴翁吟掉头。","令节可孤三日醉，归期犹有一春留。","诗坛酒会容先歃，莫问将军老不侯。"]},{"t":"再次韵答许节推二首 其二","f":"七言律诗","c":["步屧巉岩屏骑旌，松风茵露为谁轻。","已无桃李擅春事，忽有鸟乌啼晚晴。","羽客不妨同水厄，宿酲端解败诗情。","开缄又拜同寮赐，锦段中含掉尾鲸。"]},{"t":"再次韵答许节推二首 其一","f":"七言律诗","c":["起依筇竹似桴浮，改就新词却自讴。","囊锦斩关聊袖手，酒兵推户且扶头。","东风已拆红踯躅，碧树更啼黄栗留。","醒醉醉醒殊未沬，不应通守羡通侯。"]},{"t":"再次韵答陈居仁二首 其二","f":"七言律诗","c":["丁年也办刺天蜚，几梦西垣与北扉。","未簉时英书汗简，已烦溪友寄当归。","桑榆境界宁辞冷，芹藻杯盘可得肥。","说似故人应绝倒，衰颜五十盍知非。"]},{"t":"再次韵答陈居仁二首 其一","f":"七言律诗","c":["篱菊擎霜又著花，插花犹记醉君家。","两州札翰虽频寄，一笑班荆迄未涯。","酒处赋成千载计，床头易熟数年加。","珠玑属我元无踵，坐想挥毫写物华。"]},{"t":"再次韵答程帅高机宜四首 其三","f":"七言律诗","c":["高郎笔势未姑徐，千纸珠玑欬唾馀。","春兴漂萧陵野马，夜窗清绝冰金蜍。","诸公交口传黄绢，蜚诏褒贤定赤车。","亦使穷山拜嘉惠，衰翁击节正冯虚。"]},{"t":"再次韵答程帅高机宜四首 其二","f":"七言律诗","c":["名德谁今挺古风，人嗟汲直合居中。","挥毫有物鬼落胆，与世无心云度空。","倚听金銮拜新渥，又烦竹马走群童。","贝宫风露鳌峰月，行矣辉华映两瞳。"]},{"t":"再次韵答程帅高机宜四首 其一","f":"七言律诗","c":["自分迂愚著海滨，诸公荐力漫忱恂。","摧颓晚境空多感，局缩穷山亦再春。","故里归耕虽有约，中田敬馌遂无人。","何由消破愁千斛，甓社春浓莫计巡。"]},{"t":"再次韵答程帅高机宜四首 其四","f":"七言律诗","c":["倒海翻湖袖手观，揆子才思坐天悭。","愁攻心折仍无赖，债压头低不办还。","坐想赓酬联白璧，祇令翘企仰高山。","拙疏却喜便衰病，赢得萧斋尽日闲。"]},{"t":"再次韵谢张守得新居","f":"七言律诗","c":["得巢归翼惬卑栖，尚卷风茅落冻泥。","病树缘阶旋培植，旧书堆案细签题。","地非新野聊龙卧，人似东屯剩客迷。","身世只今供冷笑，百川东注月行西。"]},{"t":"再次韵谢惠诗 其二","f":"七言律诗","c":["小家茨竹即为堂，暇访深林索豫章。","平日床头但周易，看人笔落便灵光。","庳隆赋质嗟多样，良楛论材要当行。","莫向黔娄问奇货，长沙舞袖可能长。"]},{"t":"再次韵谢惠诗 其一","f":"七言律诗","c":["百镒籯金数仞堂，何如盥手颂佳章。","夺胎信自非凡剂，献佛当知便放光。","斤运向来车合辙，影斜还惜雁分行。","衰年离绪谁禁得，镜里新丝莫计长。"]},{"t":"再次韵酬俞君任","f":"七言律诗","c":["闯首亨衢属壮年，即今奔骛恐徒然。","时情合退羊肠步，宦路难加马腹鞭。","朱紫浪惊流俗眼，风骚要拍古人肩。","归休计办君当贺，儿辈新营种秫田。"]},{"t":"再次韵赠张德恭 其二","f":"七言律诗","c":["辞锋森列看分朋，退作穷山苦行僧。","每读严诗惊我倒，亦知舜绩待公凝。","丝纶指日从天下，阊阖摩霄接武升。","更想班衣奉亲寿，五云低护九枝灯。"]},{"t":"再次韵赠张德恭 其一","f":"七言律诗","c":["老寻诗法得良朋，转处骊珠悟后僧。","帝所宫商中夜奏，仙盘沆瀣未秋凝。","乐天不幸逢元稹，季友而来有彦升。","交手当家亲父子，为君别本记传灯。"]},{"t":"再次韵赠张德恭 其三","f":"七言律诗","c":["闯门不乏远方朋，辟席浑如问话僧。","笔底烟云无尽藏，谭间霜霰不寒凝。","身行建德欢谣里，人在春台瑞日升。","老子生涯漫訾省，拥书犹傍短檠灯。"]},{"t":"再次韵赠张德恭 其四","f":"七言律诗","c":["同门谁定肯论朋，拙似苕鸠懒似僧。","病减不辞诗语拙，归来少贷客愁凝。","老欺鬓发丝千丈，籴仰官仓日五升。","台閤中天清梦断，分眠山店问渔灯。"]},{"t":"再次韵赠俞德瑞 其一","f":"七言律诗","c":["珠轩绣毂辗香尘，回首西湖罗绮春。","便合行歌访花柳，可辞买笑费金银。","清吟自属当千客，劝醉那无第一人。","肯学孤山旧居士，平生诗酒祇僧邻。"]},{"t":"再次韵赠俞德瑞 其三","f":"七言律诗","c":["襟袂犹缁客路尘，攀追强踏帝城春。","落身穷僻才全璧，敌己游从半佩银。","枉却近臣开荐口，颇尝内地著痴人。","君看捉笔青灯夜，得句欢呼聒四邻。"]},{"t":"再次韵赠郭高叔","f":"七言律诗","c":["知君诗价旧连城，不作渠侬苦瘦生。","血指有人惭妙斲，空弮如我合输平。","珠同鱼目曾非匹，鼓过雷门定见轻。","久已传抄呼阿买，陶编可复置闲情。"]},{"t":"再次韵赠高宾王二首 其二","f":"七言律诗","c":["虞卿与世得穷愁，枘凿方圆岂易投。","政复有文衙屈宋，须防罪我坐春秋。","千株已种柴桑菊，万斛空横野渡舟。","可惜玉堂挥翰手，独缘羁旅赋登楼。"]},{"t":"再次韵赠高宾王二首 其一","f":"七言律诗","c":["尘外高人谢宦昏，生全天爵哜衢樽。","逸民佳传须银笔，常侍流风见耳孙。","入洛真能折伧父，浮湘更欲吊英魂。","男儿有志轻万里，辟世何如金马门。"]},{"t":"再游虎丘二首 其二","f":"五言律诗","c":["令节携壶客，当年伏虎山。","诗成云气上，人语画图间。","官作三年住，时须半日闲。","从今碧眼老，几送醉中还。"]},{"t":"再游虎丘二首 其一","f":"五言律诗","c":["阖庐归骨地，僧宇庇高丘。","又趁能诗伴，来为吊古游。","英雄馀幅纸，岁月莽东流。","未解山前客，相逢更说愁。"]},{"t":"再次韵呈杨侍郎","f":"七言律诗","c":["左符得请未逾年，民誉朝评两蔼然。","补衮工夫旧荷橐，承流政绩暂蒲鞭。","周衡可迓须分陕，孔室容窥顾及肩。","侧伫翘材著枚叟，看公亲反汶阳田。"]},{"t":"再赠泽卿商卿道旧三首 其三","f":"七言律诗","c":["过眼纷纷更问为，幽人生死况能齐。","海桑恐碍日车辙，宸极劣为天磨脐。","臧谷君方堕书蠹，研桑我亦笑醯鸡。","晚知战胜轻千乘，悔厌晨盐与暮齑。"]},{"t":"再赠泽卿商卿道旧三首 其二","f":"七言律诗","c":["隆污非是莫端倪，瞢蹈觞深试汩齐。","荆璞笑渠忘卫足，坞金何策赎然脐。","悠悠塞上悲亡马，断断尸乡丛养鸡。","可是世纷吾屑去，平生结习晚吹齑。"]},{"t":"再赠泽卿商卿道旧三首 其一","f":"七言律诗","c":["一昨西风散马蹄，肯如接淅去东齐。","人家炊玉香馥鼻，禾垄如云高过脐。","饮隽不无惊渴虎，醉归同约候鸣鸡。","二卿好客家声在，遮莫茅柴荐韭齑。"]},{"t":"同高叔不愚如晦饮再次韵二首 其二","f":"七言律诗","c":["珠帘深里按金丝，幻出扬州杜牧诗。","共引玻璃扶窈窕，更烦侧理写瑰奇。","一欢有约能如愿，四者求并每后时。","却念少陵从郑老，得钱沽酒话襟期。"]},{"t":"同高叔不愚如晦饮再次韵二首 其一","f":"七言律诗","c":["诗老掀髯吟掉头，红妆间坐眼波秋。","快倾良夕如渑酒，宛是当时锁燕楼。","想有疏帘窥白下，可无急鼓衮伊州。","凭君更挽刘师命，宽破三年烂熳游。"]},{"t":"圩上","f":"五言律诗","c":["小村山影里，山脚水明沙。","春事初移柳，人家未摘茶。","生儿了门户，馔客有鱼虾。","笑我尘埃者，奔驰鬓易华。"]},{"t":"壮观亭为真州作","f":"七言律诗","c":["频年入梦此跻攀，骤觉平时气象还。","吴客到应忘月观，淮乡胜不数平山。","飞檐曲槛霄霏处，叠嶂横江几席间。","见说能诗好宾主，风雷落笔每乘闲。"]},{"t":"岁晚言怀 其一","f":"五言律诗","c":["病在岁云除，相羊小石渠。","连朝无出日，进药止观书。","旧苦将迎困，新惭诵说疏。","官曹不事事，世恐诮相如。"]},{"t":"岁晚言怀 其二","f":"五言律诗","c":["纸屋酣春意，霜空凝冻云。","甘违酒伴约，稍策睡乡勋。","寂寂观腾踔，堂堂敛放纷。","冥心得今我，回首谢前闻。"]},{"t":"岁晚言怀 其三","f":"五言律诗","c":["雀响初防雪，鸦骄恐报晴。","徒妨一老梦，莫究二虫情。","虚籁吹群动，洪炉寄短生。","只今观物化，未替白鸥盟。"]},{"t":"托人卖马二首 其二","f":"七言律诗","c":["闲人徐步觉优游，马似羞贫意不留。","久厌短衣随射虎，更怜匣剑佩耕牛。","楚山好处聊双屩，淮水生时办一舟。","如子长才当柄用，伫看干旆拥鸣驺。"]},{"t":"托人卖马二首 其一","f":"七言律诗","c":["伴我山城惯崄巇，长因马健感吾衰。","三年粗了痴儿事，并日犹嗟灶妇炊。","会见千金市龙种，可能一笑换蛾眉。","还家劣有枯藤在，神驾尻轮得自欺。"]},{"t":"早步湖上","f":"七言律诗","c":["忽忽京尘渍客衣，正须轩旷一伸眉。","独行初日葱茏处，不待游人杂遝时。","鱼乐暗摇亭树影，风轻闲弄水云姿。","因循又耐箫歌聒，早晚湖山细入诗。"]},{"t":"次丁嘉会韵二首 其二","f":"七言律诗","c":["尘里清风忽满襟，诗成正始识遗音。","才轻馀子今文举，气压诸豪复季心。","棋罢蜡灯衔烬暗，酒阑庭树挟霜吟。","百年衮衮须今夕，岁晚鸥盟要重寻。"]},{"t":"次丁嘉会韵二首 其一","f":"七言律诗","c":["倦驻频题醉后襟，离群自叹阙知音。","卜邻未暇论前约，著语聊须慰此心。","小挽归轩清夜饮，忆尝对卧白头吟。","中年畏别犹轻别，添我霜毛又几寻。"]},{"t":"次儿辈戏商卿设醴韵二首 其二","f":"七言律诗","c":["将命长须脚未移，联翩客马已来齐。","菊花旋采浮云液，罗幕宽围护麝脐。","醉里有诗皆虎凤，区中无物不虫鸡。","主宾等是龙津客，未分金鳞卧瓮齑。"]},{"t":"次儿辈戏商卿设醴韵二首 其一","f":"七言律诗","c":["水豢山肤自土宜，况邀从事到青齐。","宾筵大嚼宁虚口，灶妇深颦想噬脐。","烂醉岂无醒酒鲙，明朝重阅不鸣鸡。","扶头更忆松江晓，旋买鲈鱼薤捣齑。"]},{"t":"次日再次韵三首 其二","f":"七言律诗","c":["微吟缓步惬晴沙，聊谢愔愔载妇车。","时遣贳貂村店酒，回思缚虎长官衙。","春山好著屏中色，吟笔谁添锦上花。","不妨习池风月主，只今何处问诗家。"]},{"t":"次日再次韵三首 其一","f":"七言律诗","c":["山行风色怒飞沙，山末屯云涌炮车。","伏轼不容同蝶梦，问炊犹可趁蜂衙。","龟鱼泛渌熹晴日，草树留春著晚花。","暮憩自怜尘满面，五浆先馈定谁家。"]},{"t":"次王帅韵","f":"七言律诗","c":["使君觞客及公荣，慰我他时渴德深。","已为穆生重设醴，更闻正始嗣遗音。","打围红袖留连舞，论槛黄花取次簪。","恰似雄边台上醉，回头岁月叹侵寻。"]},{"t":"次王帅韵后诗呈叶教授 其一","f":"七言律诗","c":["业履冰壶器镆邪，元戎韬略况儒家。","功名自昔须横草，南北于今赖灌瓜。","村墅稻田黄罢亚，塞垣榆树老丫叉。","为公著意收诗稿，传与中都万口誇。"]},{"t":"次王帅韵后诗呈叶教授 其二","f":"七言律诗","c":["功名回首负年华，梨枣诸雏未克家。","老计生涯须下泽，才非世用但匏瓜。","为儒仅博肱三折，谋食宁羞手一叉。","青眼故人犹念此，肯持巴唱向人誇。"]},{"t":"次王仲衡尚书韵","f":"七言律诗","c":["著脚功名马络头，人生君所几居州。","惟公德操朱弦直，映世冰壶白月秋。","久已短长冥尺寸，可须肮脏羡伊优。","即今千里讴谣地，赢得挥斤五凤楼。"]},{"t":"次瓜州","f":"五言律诗","c":["云曀平山塔，烟明老濞城。","客行判费日，舟泊细论程。","闸水清兼浊，潮天雨复晴。","未须归有梦，午枕惬凉生。"]},{"t":"次沈倅韵呈王漕","f":"七言律诗","c":["王家流庆水倾东，不独乌衣纪数公。","天畀臧孙当有后，人迟汲直未居中。","凤巢衮衮九文羽，鹏路摇摇万里风。","隔坐从今几云母，定知周鲁各元功。"]},{"t":"次陈宰韵","f":"七言律诗","c":["觥筹交错舞僛僛，晓色侵窗客未知。","便整醉魂乘款段，尚馀吟兴属酴醾。","还家拟趁宝璎珞，唤客重乾金屈卮。","著意风烟与调护，免教花意恨归迟。"]},{"t":"次陈梦锡韵二首 其二","f":"七言律诗","c":["思君采艾叹如年，眼底羁愁只自煎。","破梦有来惊剥啄，冲泥径欲跨连钱。","新篇端复千年计，旧集犹须百手传。","早晚聚头三日语，麈边闲听有源泉。"]},{"t":"次陈梦锡韵二首 其一","f":"七言律诗","c":["薄雪晶瑩压屋茅，未须桂玉计晨庖。","已便盐絮明愁眼，更喜乌鸢得夜巢。","小听骚人赋梁苑，旋看春意满东郊。","忍寒便拟寻梅去，梦想瑶英点旧梢。"]},{"t":"次林计议喜雪韵","f":"七言律诗","c":["雪缟长空纻带翻，数知冬意未阑残。","岁功告瑞须三白，客子凭高耐一寒。","拍塞闲郊瑶圃阔，晶荧危堞玉龙蟠。","归来冻坐追清赏，重把君诗剪烛看。"]},{"t":"次前韵谢胡运属二首 其二","f":"七言律诗","c":["炉烟袅袅上晴丝，伴阅长须送似诗。","眼著昏花予已老，句锵哀玉子能奇。","随人趋步庸非俗，取意妆梳自入时。","大手只宜台閤里，不应犹话鹿门期。"]},{"t":"次前韵谢胡运属二首 其一","f":"七言律诗","c":["耐暑初宵露白头，诗来分我一襟秋。","露飞琼滴漙苍竹，月漾金波冰小楼。","政用桐君弦白雪，便烦从事到青州。","此怀未满须笺与，更为狂生赋远游。"]},{"t":"次韵赵夷仲 其二","f":"七言律诗","c":["坐听严更一再通，卓肩搜句夜虫同。","拜嘉杰作开囊锦，似为衰翁疗首风。","紫诰君宜步西掖，苍颜我欲隐东蒙。","鞬櫜文陈甘三舍，百胜将军正总戎。"]},{"t":"次韵赵夷仲 其一","f":"七言律诗","c":["赵侯才望屹撑空，肯我过从笑语同。","妙论全胜十年读，清篇分饷一襟风。","珷玞可用酬昆璞，涎颡何曾梦锦蒙。","莫把诗声陵此老，迟君谒帝画平戎。"]},{"t":"次赵解元韵 其二","f":"七言律诗","c":["兴刘止用一编书，万轴垂签或腐儒。","表表君今超北学，多多我已悔东隅。","声华看续诸公后，尔雅深知一笔无。","缩手袖间真老矣，灌园蓄㹀了朱愚。"]},{"t":"次赵解元韵 其一","f":"七言律诗","c":["养病年来懒著书，逢人掉臂睨迂儒。","愁边好客从天下，谭处清风起座隅。","愧我多言终不近，似君知已未应无。","酸咸嗜好虽殊禀，政恐渠侬诮太愚。"]},{"t":"次诸公韵","f":"七言律诗","c":["回首舟餐野店栖，何殊子美咏青泥。","朅来贤将先回盼，径上诗坛许命题。","举白烂陪山简醉，凝香到有武陵迷。","异时过计今方悔，曾虑谈间彼子西。"]},{"t":"次宿北阿韵","f":"五言律诗","c":["闻道篮舆去，遥岗复近阿。","诗应吊孝逸，碑或赞头陀。","静者官糊口，公朝礼作罗。","怜君日阡陌，尘土扑阴何。"]},{"t":"次崔帅韵","f":"七言律诗","c":["虎塞风云自壮怀，诗坛尤见不凡才。","至音忽作锵金发，急笔宁须击钵催。","属餍重尝项上脔，拜嘉如嗅陇头梅。","还家定遣比邻怪，珠璧光芒重载回。"]},{"t":"次喜雨韵","f":"七言律诗","c":["被旱农家怒伏龙，衰翁岁望甚于农。","人方半菽延朝夕，我亦频年阙釜钟。","洒润似惊萁火冷，骤寒不贷布衾重。","有来喜雨清新句，一笑令人失病容。"]},{"t":"次曾左司韵赠俞德瑞","f":"七言律诗","c":["班荆同冒软红尘，一种东风两样春。","隽饮放君颜似赭，幽居怜我鬓如银。","简编自诳供良夜，要襋渠今有好人。","把酒若歌归缓缓，不妨折简唤东邻。"]},{"t":"次韵什邡马主簿二首 其二","f":"七言律诗","c":["纷纷过眼甚螽斯，胆掉惊逢骥騄驰。","献替付君温省树，朝晡还我故山芝。","荆江蜀栈聊舒啸，卷耳思齐正采诗。","回首定传天上信，囊荷知傍紫皇持。"]},{"t":"次韵什邡马主簿二首 其一","f":"七言律诗","c":["陶谢前踪一笔追，掀天声价旧风驰。","瑞时不数九文羽，换骨疑餐三秀芝。","蜚电烛岩方左席，明珠照乘忽清漪。","裹创瞢欲凌坚阵，可讳含毫不自持。"]},{"t":"次韵元卿二首 其二","f":"七言律诗","c":["笑携佳句又冲寒，政用消忧觞咏间。","酒贱粗能留子醉，食贫未暇惨予颜。","搜诗杜老方须药，强项萧生且抱关。","旧约偶耕犹念否，霜林雪竹正斓斑。"]},{"t":"次韵元卿二首 其一","f":"七言律诗","c":["君自才高与世疏，我顽能使此溪愚。","医师久已肱三折，赋客枵然屋四隅。","莫道十年同好恶，相过一笑间忧虞。","胸中圭角今馀几，诗胆由来已破觚。"]},{"t":"次韵方秘正 其二","f":"七言律诗","c":["小窗危坐正凝愁，诗客华编肯见投。","明月拜嘉千斛赐，清风分送一襟秋。","路迷端倚司南驾，金换还随过海舟。","誇与湖山须快读，涌金门外倚曾楼。"]},{"t":"次韵方秘正 其一","f":"七言律诗","c":["静女无媒未易昏，幽人乐地但琴樽。","诗声况自推侯喜，墙仞悬知陋叔孙。","拜手行申不敏谢，慕贤正黯索居魂。","拘拘泄柳非君匹，老子来时肯闭门。"]},{"t":"次韵王知军夜坐有怀","f":"七言律诗","c":["梦想天兵下不其，壮心摇荡受风枝。","摄衣试作听鸡舞，穷我庸非造物儿。","腰下谁悬苏子印，城中人笑董生帷。","西来江左夷吾在，小敌才堪剑首吹。"]},{"t":"次韵王编修二首 其二","f":"七言律诗","c":["老誓捐书断苦吟，君苗笔砚戴逵琴。","因君又试推敲手，揆我终惭缴绎音。","漫作蠹鱼餐朽策，倏听鹎鵊语中林。","肉台盘客曾丁字，碧酒留宾听浅深。"]},{"t":"次韵王编修二首 其一","f":"七言律诗","c":["落手新诗吮复吟，自甘壁角挂枯琴。","祈光已吸金茎露，张野俄聆帝乐音。","疗我平生风雅渴，放君高步隽英林。","人间梦想珊瑚树，龙护灵湫万仞深。"]},{"t":"次韵王签判","f":"七言律诗","c":["奥学闻君不近名，声华犹是压时英。","诗篇向我肯挥扫，句法惊人浑老成。","未厌泛莲依卫幕，只今荐鹗达周京。","明朝置酒当投辖，万斛洪源看倒倾。"]},{"t":"次韵王签判二首 其二","f":"七言律诗","c":["五鬼侵陵两鬓苍，振穷扫白分无妨。","酒徒丛里投名懒，诗社中间趁课忙。","尘暗凤笙空自叹，风惊雁字不能行。","向君草草追强韵，政复通人笑楚狂。"]},{"t":"次韵王签判二首 其一","f":"七言律诗","c":["客中谁者伴闲身，祇有苍槐与翠筠。","回首昔游惊梦断，故人重见倍情亲。","簿书简省官居好，月露清圆句语新。","千里相思匪天意，聚头一笑此何因。"]},{"t":"次韵王漕起秀亭","f":"七言律诗","c":["梦蹑常山万仞巅，宝符千载尚依然。","乌孙有底枭凭夜，赤子能忘蚁就膻。","正朔会须还禹服，登临聊复对吴天。","明年重放危亭目，万旅公方北首燕。"]},{"t":"次韵归路微雪","f":"五言律诗","c":["卓荦康时略，昂藏报主身。","冲风还按辔，飞雪却宜人。","帝渥先春遍，诗题触目新。","行行何样好，归路玉为尘。"]},{"t":"次韵石湖居士见梅","f":"七言律诗","c":["东风犹是玉为尘，静女冰肌小带皴。","尚压芳华擅春事，枉当穷腊议花神。","仙姿绝俗遗群妒，鼎实收功看一新。","疏影暗香吾袖手，且容诗伯继黄陈。"]},{"t":"次韵石湖居士瓶中早梅二首 其二","f":"五言律诗","c":["罗帷护春色，群木未昭苏。","绝胜翻香坐，聊陪琢句臞。","天资便静独，冰影倚空无。","后夜逢姑射，仙家白玉壶。"]},{"t":"次韵石湖居士瓶中早梅二首 其一","f":"五言律诗","c":["诗翁静三昧，筇杖壁间横。","小閤自清绝，幽芳从瘦生。","巧当窗影见，时映烛花明。","底用寻春去，冲寒踏月行。"]},{"t":"次韵石湖居士晴窗遣兴","f":"七言律诗","c":["阊门车马隐晴雷，我亦临风咏快哉。","平碧际空烟羃历，蔫红照影水萦回。","园翁门巷初沾絮，游子杯盘欲荐梅。","落晚小家还馔客，旋篘春瓮取新醅。"]},{"t":"次韵石湖居士游虎丘","f":"七言律诗","c":["山灵知我欲巾车，岫幌云扃已韨除。","竹葆松幢平几席，碧烟红影认林庐。","饭分禅供清无敌，饮属诗流兴有馀。","莫话长安牢落客，付渠尘土曳长裾。"]},{"t":"次韵记别程帅谷城旅梦","f":"七言律诗","c":["金翘摇曳玉丁东，宾主依然醉笑同。","旧事忽随残漏断，新愁不逐晓云空。","挑灯旋拂穿帷雪，揽辔还禁逆帽风。","回首梦魂飞到处，壶公窟宅五云中。"]},{"t":"次韵任解元喜雨二首 其二","f":"七言律诗","c":["跪奉炉香幸见怜，人言匹庶可回天。","及今一睹盆倾势，满意重占斗覆年。","仅息黄尘昏永昼，几时翠羽冒中田。","此心安得顽如石，水旱丰凶付偶然。"]},{"t":"次韵任解元喜雨二首 其一","f":"词","c":["寄语今年主雨神，当知小雨未康屯。","人心正切霶?望，农事深愁晼晚春。","朽壤旧尝封蚁穴，停云空复叠鱼鳞。","鲰生宿蕴天人学，无计王前拜手陈。"]},{"t":"次韵刘宰","f":"七言律诗","c":["倾盖回舟一再逢，向来淮左又江东。","自惊岁钥催衰白，况说京尘踏软红。","吏役吾方百寮底，诗工君更古人中。","挽留重试传杯手，得醉歌呼兴未穷。"]},{"t":"次韵刘常甫见赠二首 其二","f":"七言律诗","c":["笔阵平时枉计功，钝锤那办突铦锋。","灞桥雪里嗟良苦，饭颗山头记昔逢。","斲句自知穷有相，从人财博缪为恭。","彭郎小隐刘郎宅，抖擞尘襟听所从。"]},{"t":"次韵刘常甫见赠二首 其一","f":"七言律诗","c":["重来触目总宜诗，颇费行吟与坐思。","旧友相过有嘉惠，满篇更喜胜前时。","连朝把玩惊飞动，万象低摧受控持。","尘翳玉笙嗟耳冷，何人度曲颤鸾篦。"]},{"t":"次韵同年诸公环碧叙同年会 其三","f":"七言律诗","c":["聚首论年不计官，寥寥故事复开端。","俯容我辈输心语，更遣时流洗眼看。","庾亮宾筵无尽兴，昌黎文饮有馀欢。","舍人妙句还新样，白雪赓酬政自难。"]},{"t":"次韵同年诸公环碧叙同年会 其二","f":"七言律诗","c":["春意温然侍上官，松醪更劝语更端。","行厨剩遣黄头载，下客何曾白眼看。","杰在汉庭方眷注，功将周室更祗欢。","孰知末至慈恩旧，老境犹歌行路难。"]},{"t":"次韵同年诸公环碧叙同年会 其一","f":"七言律诗","c":["天瓢挹注拱仙官，更阅诗仙锦绣端。","离合不忘车笠誓，留传当并画图看。","玄谭想有蛟龙听，得醉仍均客主欢。","俛仰谪仙三百载，从知乐事继今难。"]},{"t":"次韵回涂打冰欲遵陆","f":"七言律诗","c":["转头风日破坚冰，未用穿危冒滑行。","瀚海无波聊整棹，阳春有脚莫论程。","诗情动处髭频撚，使事閒时酒细倾。","冯问逢迎黄发叟，里间欢意为谁生。"]},{"t":"次韵早春","f":"七言律诗","c":["良辰邀醉得钱无，雪后郊原翠欲铺。","无力晚风摇柳线，有情新日养花肤。","寻芳拟贷愁边意，照水还惊病后臞。","春到祇思为圃乐，剩移杞菊种鸡苏。"]},{"t":"次韵朱万卿五首 其五","f":"五言律诗","c":["平时歌酒伴，云散与风流。","白发潘怀县，青衫许散愁。","生怜自谋拙，人谓不堪忧。","只拟江湖去，狂吟和棹讴。"]},{"t":"次韵朱万卿五首 其四","f":"五言律诗","c":["一雨动三日，沟塍皆怒流。","风凉欺酒力，喜色寄诗愁。","不待桑林祷，俄宽杞国忧。","丰登知有象，满听载涂讴。"]},{"t":"次韵朱万卿五首 其三","f":"五言律诗","c":["彼姝绿窗子，欧靓亦其流。","裙衩何因瘦，眉梢不贮愁。","唾花新得意，庭草共忘忧。","雌凤求凰曲，人前莫误讴。"]},{"t":"次韵朱万卿五首 其二","f":"五言律诗","c":["风义陶朱裔，斗南无此流。","悬知禁厨脔，不赋畔牢愁。","笔落无千载，谈间散百忧。","尽抄新乐府，惜欠雪儿讴。"]},{"t":"次韵朱万卿五首 其一","f":"五言律诗","c":["陈雷好宾主，亹亹各风流。","末座仍枚叟，捐金得莫愁。","浓欢兼卜夜，暇日赖销忧。","近按梁州谱，何妨一再讴。"]},{"t":"次韵朱秀才二首 其二","f":"七言律诗","c":["儒冠林立更鸿生，经倚菑畬道可耕。","便合摘髭书桂籍，未须拥鼻避时名。","似闻眕梦成三耳，会见惊人取一鸣。","讲易露门谁第一，伫君重席振家声。"]},{"t":"次韵朱秀才二首 其一","f":"七言律诗","c":["萧斋愁兴倩谁宽，笼鹤昂霄顾羽翰。","自昔诗深知武谔，肯辞雨湿过苏端。","心期落落空轩豁，世事悠悠拙控抟。","正枕诵君悲壮语，梦随飞将蹑鞮汗。"]},{"t":"次韵朱通判严上舍 其四","f":"七言律诗","c":["子元才望未专城，玉面醪敷且细倾。","宠辱尽捐身外事，醺酣聊乐圣之清。","分甘亦复怜吾老，饮湿终惭不自营。","归去须君传此法，秫田百亩便平生。"]},{"t":"次韵朱通判严上舍 其一","f":"七言律诗","c":["蜀庄漂泊阖闾城，独向陶朱意气倾。","诗写闲情易为好，雨鏖炎暑欲争清。","居同蚁穴晴犹闭，归笑鸠巢老未营。","久拟投君渠保社，援毫空复可怜生。"]},{"t":"次韵朱通判严上舍 其二","f":"七言律诗","c":["君家名酒压吴城，肯向时流取次倾。","篘玉谁今窥正色，班荆渠定赏真清。","双壶问字宁能许，一醉留宾不办营。","莫惜驱车饷元亮，须防结袜要王生。"]},{"t":"次韵朱通判严上舍 其三","f":"七言律诗","c":["万手抄诗遍洛城，老怀可但向来倾。","采菱白雪方迭奏，蜚雨晓风相与清。","价重欲输和氏璧，令严谁犯伏波营。","即今貂尾那容续，更判工夫费此生。"]},{"t":"次韵朱解元雪","f":"七言律诗","c":["掉头取别未经旬，已积胸中几斛尘。","密雪忽明银海夜，端忧空负玉花春。","笔驱和气君何健，囊致新诗我未贫。","胜日兔园当有赋，可能客右欠斯人。"]},{"t":"次韵自序","f":"七言律诗","c":["丁年拾芥视功名，可但纫兰茹落英。","深愧官曹无所补，向来志愿几馀成。","分营伏腊耕淮壤，久绝音邮到帝京。","尚有好贤馀习在，老怀端合向君倾。"]},{"t":"次韵严上舍","f":"七言律诗","c":["待月尚思前度月，中天圆璧不留分。","即今霜气挟灵籁，如许金波乘坏云。","念我吴牛终喘夜，忆君冀北忽空群。","睡魂作魔病作祟，犹赖清诗来解纷。"]},{"t":"次韵严文炳兼简张守二首 其二","f":"七言律诗","c":["梅梅柳柳护深行，倦客重游眼更明。","谷鸟自应寻旧约，渚兰潜欲换新萌。","诗工已可醒人醉，赋就当须冰坐清。","老我客渠真得计，梦魂无复凤凰城。"]},{"t":"次韵严文炳兼简张守二首 其一","f":"七言律诗","c":["嬉游有愿自今偿，回首春容已浩茫。","霁景偏迟张锦地，小园秀出卧云庄。","梅林破玉香沾袂，池水摇漪渌泛堂。","茶具笔床陪语笑，未妨日饮慰还乡。"]},{"t":"次韵何学谕送行二首 其二","f":"五言律诗","c":["湖山迎客棹，触目总宜诗。","回首蓬莱近，平生汗漫期。","衰年得奇观，往事属怀思。","何日鸱夷去，扁舟共翠眉。"]},{"t":"次韵何学谕送行二首 其一","f":"五言律诗","c":["新诗念报答，呫嗫未能书。","落笔群英右，惟君一敌如。","穷愁疏翰墨，客路费羲舒。","延閤青冥上，摩研正望渠。"]},{"t":"次韵何符山人二首 其二","f":"七言律诗","c":["晓看明玑下网丝，物华俱属喜晴诗。","一词不措重呈拙，七字鼎来当更奇。","喜鹊啅人真作意，蜗牛屏迹似知时。","湖山好处长谣去，拟赴苏堤胜日期。"]},{"t":"次韵何符山人二首 其一","f":"七言律诗","c":["门下轩裳不转头，何人皮底著阳秋。","独烦客子冲泥屐，屡到衰翁听雨楼。","从昔诗声追正始，即今宾友验宣州。","清篇快读彊人意，未觉京尘厌薄游。"]},{"t":"次韵吴江陈学长送行二首 其二","f":"七言律诗","c":["白首诗书未亢宗，还纡墨绶揖王公。","玉堂金马拌身外，法护僧弥且眼中。","自诡嘘枯酬雅志，肯从束湿就奇功。","垂虹高士知心客，定信襟期出处同。"]},{"t":"次韵吴江陈学长送行二首 其一","f":"七言律诗","c":["诗人六十合恩袍，平日周庠重誉髦。","旧学堪重汉儒席，新文欲仆楚人骚。","等观得丧心无累，饱阅豪英眼更高。","闻道青箱富嘉颂，诏音早晚召王褒。"]},{"t":"次韵张司户 其二","f":"七言律诗","c":["他日犹能说宦游，老禁多病厌漂流。","近临西蜀窥鲛室，旧傍东溟看蜃楼。","归计已嗟霜蟹晚，吟声闲伴候虫秋。","尘冠径欲留神武，万顷苍茫漾白鸥。"]},{"t":"次韵张司户 其一","f":"七言律诗","c":["橘颂精灵杂远游，如君信是古诗流。","吴门肯问鲈鱼鲙，东武当营燕子楼。","有底挥毫挟风雨，定知贮腹尽阳秋。","即看珥笔鸳鸾右，莫漫江城诧狎鸥。"]},{"t":"次韵张丞","f":"七言律诗","c":["邦人邑吏总堪怜，茶供炉熏共吁天。","占雨几孤霞粲晓，望霓何啻日为年。","翻黄已熟村村麦，平渌行看处处田。","拟倩龙公作霖手，更烦终惠息头燃。"]},{"t":"次韵张丞 其一","f":"七言律诗","c":["县人灯夕旧尝看，夜敞窗扉晓不关。","胜赏继应追俗尚，晴晖巧与破天悭。","招邀便拟日复日，容易遽吟山上山。","更乞紫姑丰乐语，为添喜色到颜间。"]},{"t":"次韵张丞 其二","f":"七言律诗","c":["长日官曹迄未闲，佳辰一笑颇相关。","万情同乐那容失，四者来并每坐悭。","歌酒恐孤灯市月，烟霏犹曀海门山。","龙公可复会事发，汛扫阴霾弹指间。"]},{"t":"次韵张丞二首 其二","f":"七言律诗","c":["槁梧闲据自沈吟，投老真成负此心。","酒沃渴鲸悲事往，官随跛鳖笑吾今。","进为终愧周人朴，归去曾无陆子金。","尚赖君诗慰牢落，时清聋聩发纯音。"]},{"t":"次韵张丞二首 其一","f":"七言律诗","c":["夫君腹笥尽奇谋，每叩谈锋听不休。","诵赋久嗟无此作，荐贤端合拔其尤。","小迟荣路观掀趠，聊为同寮盖谬悠。","政恐诸公有推挽，平时果艺仰由求。"]},{"t":"次韵张丞月试士人","f":"七言律诗","c":["居有斋庖教有官，诸生肯复计安闲。","充庭数贡知非远，造物于人本不悭。","思苦得无金注拙，眼明终眩锦花斑。","自怜惯秉雌黄笔，案牍如今拄屋山。"]},{"t":"次韵张守与润守总卿诗四首 其四","f":"五言律诗","c":["向我能忘势，张侯却甚真。","频分代舍饭，遣濯客裾尘。","长日无知己，因君爱此身。","可须砭剂力，振臂起漳滨。"]},{"t":"次韵张守与润守总卿诗四首 其三","f":"五言律诗","c":["残年仍旧学，平日亦新书。","酒渴今司马，岩栖昔幼舆。","梦无三字拜，家有五车储。","但谂催诗烛，吾衰冀少徐。"]},{"t":"次韵张守与润守总卿诗四首 其二","f":"五言律诗","c":["渔樵送晚景，天地著陈人。","涧底离奇干，人间浩荡春。","峨冠才识字，何策可资身。","不拟千言赋，忉忉慁大钧。"]},{"t":"次韵张守与润守总卿诗四首 其一","f":"五言律诗","c":["天阶玉作笋，此地合垂绅。","尚戒专城驭，虚逢吁俊辰。","公方阅竹马，名已荐枫宸。","政恐经纶去，诸公拱后尘。"]},{"t":"次韵张守劝农 其二","f":"七言律诗","c":["眼向囊书老不明，合遵宽教事农耕。","雨馀骤变菖条绿，晓起欣聆布谷声。","谭笑俾民无死徙，丰凶转手有虚盈。","衰翁倍荷殷勤意，缄致无非翠织成。"]},{"t":"次韵张守劝农二首 其二","f":"七言律诗","c":["竞簉行轩亲色笑，教条初不作风霜。","为公醉德仍醇酎，惠我温言亦报章。","重见桐乡敬朱邑，不须畏垒诧庚桑。","受廛定许休吾老，已戒诸雏计裹粮。"]},{"t":"次韵张守劝农二首 其一","f":"七言律诗","c":["传闻载酒西郊晓，迎候前旌拥老农。","贤守承宣先劝课，太平风俗见声容。","官堤烟树纡红缬，沙岸风蒲袅紫茸。","想憩凝香倒囊锦，银钩侧理叠千重。"]},{"t":"次韵张守劝耕二首 其二","f":"七言律诗","c":["三揖清扬岁两更，烦公倒屣费逢迎。","抽簪仕籍心弥厉，撰屦词坛计欲成。","西洛况闻高纸价，苏州从昔擅诗声。","拙衰枉作登龙客，领略玄谭自阿平。"]},{"t":"次韵张守劝耕二首 其一","f":"七言律诗","c":["吾徒一笑似关天，离合胡宁付偶然。","梦境萍蓬渺云水，旧游花柳更风烟。","交情缱绻今犹昔，妙句传抄喜欲颠。","廷尉归须结袜客，为公饱饭计留年。"]},{"t":"次韵张守王勉夫二首 其二","f":"七言律诗","c":["世味平时虫臂轻，独留意气与君倾。","向来缱绻资磨玷，拟话分携已怆情。","盛际功名方策足，他年车笠肯渝盟。","汉廷取重张廷尉，可待区区结袜生。"]},{"t":"次韵张守王勉夫二首 其一","f":"七言律诗","c":["两隽诗声敢重轻，苍山对峙大川倾。","形为幼眇无遗恨，有入题评莫遁情。","未许曹刘夸独步，不应邾莒合逃盟。","清篇读罢重看镜，似觉青丝鬓脚生。"]},{"t":"次韵张守泛春亭","f":"七言律诗","c":["小退铃斋复此亭，自公喜色更津津。","再纡皇眷分忧寄，坐镇江城与物春。","长日雍容少公事，共谁谈笑作诗人。","撚髭惯厕分题客，元亮柴车已命巾。"]},{"t":"次韵张守妻闵忌","f":"七言律诗","c":["莱妻魂逝不容招，敢问何方处寂寥。","老去更堪听薤露，病来久不近金蕉。","声摇夜梦蛩相吊，垢翳篝衣雨辄潮。","细读君诗重悽惋，隐侯肤骨不胜销。"]},{"t":"次韵张守赴真州辞家","f":"五言律诗","c":["争引依风领，须公布惠慈。","深恩手摩拊，数计月盈亏。","岁事方援溺，情亲更语离。","来时雁天阔，触目总宜诗。"]},{"t":"次韵张守晓起","f":"七言律诗","c":["客亭移枕待残更，起趁邻鸡第二声。","了了每添新悟解，营营无复旧心情。","兴来命酒禁诗瘦，老去衰容怯镜明。","况是杏花浓露晓，不应蒙被问春晴。"]},{"t":"次韵张守涂中逢节二首 其二","f":"五言律诗","c":["赏心仍令节，十事九相违。","老境家犹远，愁城日合围。","客涂君尚叹，世路我知非。","羡杀乡居子，耕梁木叶衣。"]},{"t":"次韵张守涂中逢节二首 其一","f":"五言律诗","c":["涂中岁遒尽，江影暮澄凝。","柏酒惟宗武，河梁似李陵。","问津田叟傲，捩柂长年能。","系缆才沙觜，人家已上灯。"]},{"t":"次韵张守涂中生日","f":"七言律诗","c":["诸雏称寿纪桑蓬，此会频年客路逢。","抚事祗令伤急景，持杯随分发衰容。","心缘羁旅长多遌，情为思亲政复钟。","更惜齐眉旧兰友，今春觞咏断相从。"]},{"t":"次韵张守惠山","f":"五言律诗","c":["诗伯心如水，熊轓再护边。","教条父老舞，姓字裔夷传。","客到牵铃索，诗成仰屋椽。","平吞云梦泽，聊酌隐之泉。"]},{"t":"次韵张秀才雪","f":"七言律诗","c":["可是春皇吝物华，群仙剪水作奇葩。","壶中天地浑糜玉，风处园林尽勒花。","宿火煖寒聊榾柮，夜光落手忽惊嗟。","忍饥遽拟搜诗谢，何异空肠更饮茶。"]},{"t":"次韵张直閤避暑","f":"七言律诗","c":["红榴照眼笋穿阶，峭閤登临快此来。","净境祛烦仍客共，醉乡逃暑更书催。","庭阴碎喜风头动，虹影明看雨脚回。","万事屏除诗债迫，此心抖擞未容灰。"]},{"t":"次韵张德恭主簿二首 其二","f":"七言律诗","c":["汉南独步有登楼，肯为衰翁吟掉头。","价比连城容品裁，句专八米见风流。","生涯枯泽鸣饥鹤，老去惊波荡白鸥。","当念饭山人似削，撩人更遣耐新愁。"]},{"t":"次韵张德恭主簿二首 其一","f":"七言律诗","c":["一日乘闲燕画楼，连宵飞梦只楼头。","掾郎谈麈惊飞雹，公子吟毫涨怒流。","归去定谁扶下马，重来有约属驯鸥。","可堪风雨妨人乐，却向卢家访莫愁。"]},{"t":"次韵李寿卿明府忆梅 其二","f":"七言律诗","c":["炯若横陈耐冻枝，清篇细读更重披。","即令扶病揩尘砚，痛忆寻芳载酒时。","政使雪霙来眼底，却愁霜鬓被花欺。","暗香疏影君能事，何处羁人敢语诗。"]},{"t":"次韵李寿卿明府忆梅 其一","f":"七言律诗","c":["不分无花空折枝，探梅要趁未纷披。","忆常月地携筇去，似许风裳倚竹时。","庄蝶认香怜梦短，墨君写影竟谁欺。","故人底事江南北，驿使来时仅好诗。"]},{"t":"次韵杨帅留客赏雪二首 其二","f":"七言律诗","c":["园林花絮忽冥冥，水墨工夫忆李成。","琼树挽春争炫昼，玉龙转野寂无声。","绮罗樽俎诸宾醉，箫鼓楼台九陌晴。","不比游仙向来梦，真陪仙伯燕曾城。"]},{"t":"次韵杨帅留客赏雪二首 其一","f":"七言律诗","c":["锡羡端知自杳冥，更资和气与烘成。","餍观搅海翻云势，旋听摧檐泻竹声。","狎坐鸳鸯方荐笑，窥檐乌鹊已熹晴。","从公草赋梁园罢，未羡将军下蔡城。"]},{"t":"次韵杨枢视圩游隐静","f":"七言律诗","c":["劝相江糜畚锸忙，却回小队访山房。","松风不约炉烟直，昼晷潜随僧话长。","政外辍闲知有味，区中得醉浪名乡。","铜丸好句长哦罢，坐听惊猿堕莽苍。"]},{"t":"次韵杨枢喜雨","f":"七言律诗","c":["神护天关色正庄，挽回帝眷一丝香。","人间雨信先鸣鹳，仙界雷翁叱卧羊。","剡剡青秧迷迥野，浮浮白水溜方塘。","丰年信出为霖手，恳悃忧民意叵忘。"]},{"t":"次韵杨宰","f":"七言律诗","c":["我方獭髓疗蜂腰，渠自才华盖代豪。","州掾聊容养文豹，玉音催去踏金鳌。","联芳君亦花封最，双峙人推玉笋高。","看即提衡霄汉上，得无交口话啼号。"]},{"t":"次韵杨宰","f":"七言律诗","c":["君方总辔冒尘沙，我亦青灯未著花。","县宰忧民暇黔突，道人有饭即为家。","倦温村酿萁火暗，笑撚吟髭风帽斜。","等有灞陵桥上兴，不妨频著小诗誇。"]},{"t":"次韵杨宰二首 其二","f":"七言律诗","c":["五斗宁辞小折腰，簿书那久困才豪。","得无狸豹惊雕虎，妙有钩丝掣巨鳌。","诗就鼎来宫锦肠，闲中眼与楚云高。","横陈景物无央数，付子秋崖万窍号。"]},{"t":"次韵杨宰二首 其一","f":"七言律诗","c":["早缘官事坐儿痴，晚悟骚人赋汩泥。","耐病久闲金騕袅，扶衰时近玉东西。","词场尚友心终在，诗力逢君价自低。","欲试成风须妙质，莫怀章甫问雕题。"]},{"t":"次韵杨宰公田道上","f":"五言律诗","c":["人有褰裳去，时闲野渡舟。","知君问彫瘵，随处访深幽。","岁事方关念，村醪不破忧。","贳租仍己责，或可继前脩。"]},{"t":"次韵杨宰次郎裴","f":"五言律诗","c":["信次尚村落，食眠随晓晡。","山瓶馀濩倒，僧宇谒伊蒲。","笑挟兔园策，问收鱼澳租。","前滩起鸥鹭，为我作前驱。"]},{"t":"次韵杨宰述怀","f":"五言律诗","c":["为儒如此尔，粮食第晨晡。","诗漫南山杞，愁连董泽蒲。","宾筵阙鹅炙，券负有牛租。","久要惟穷鬼，文成不受驱。"]},{"t":"次韵杨宰秋尾雪","f":"五言律诗","c":["密雪界秋冬，悲欢可得同。","祥如关岁事，时合奏场功。","政要肉骨手，民方霜叶风。","强吟盐絮句，面不盖羞红。"]},{"t":"次韵杨宰食莲戏作 其二","f":"七言律诗","c":["诗到衰翁耐病时，辟渠三舍更何疑。","才高王俭幕中隽，气慑孙郎帐下儿。","向我论交得无意，他时怀旧更长思。","莲茎把玩不为腹，羡杀逢人饮上池。"]},{"t":"次韵杨宰食莲戏作 其一","f":"七言律诗","c":["平时莲实吾羊枣，日饫甘寒不自疑。","病恐伤生严食事，居多节口甚婴儿。","舌融沆瀣诗能说，手掬珠玑我属思。","对酒移风劳想像，静看千柄泛前池。"]},{"t":"次韵杨宰宿北阿","f":"七言律诗","c":["寒事峥嵘念解携，芳樽忆共拆红泥。","邮筒空有诗相续，夫子东归我复西。","剌剌掀林朔风驶，沈沈閤雪晚云低。","巴歌拟报阳春赠，未敢从人索品题。"]},{"t":"次韵杨宰野步","f":"五言律诗","c":["筇杖陪随去，漂然不系舟。","云低山影暝，风定竹林幽。","病减柳臂感，老无蒿目忧。","吟诗如蚀月，玉斧傥能脩。"]},{"t":"次韵杨宰野步","f":"七言律诗","c":["眼边室迩叹人遐，再见惊飙衮雪花。","岁歉民劳真诿子，泥行草宿又谁家。","题诗山寺神应助，问俗村区日易斜。","随处棠阴诵遗爱，他年剩著翠珉誇。"]},{"t":"次韵杨宰雪","f":"五言律诗","c":["对雪动遐想，此情今古同。","饶为灞桥句，会奏蔡城功。","耻卧袁安屋，思乘列子风。","高翔广乐地，眩旋九霞红。"]},{"t":"次韵杨宰游神居","f":"七言律诗","c":["峰顶留云一鹫骞，山腰涵碧老蛟蟠。","鹍鹏翻海十洲近，江汉分流三楚宽。","曾是乘闲上埃霭，小留舒啸倚高寒。","想君缓憩双凫舄，不羡冲霄吴綵鸾。"]},{"t":"次韵杨宰樊汊","f":"五言律诗","c":["龙岂分勤惰，司存想异方。","禜雩均此意，丰歉竟殊疆。","惠戒憎漏网，君宁专击强。","东南有偏熟，鄙语未应忘。"]},{"t":"次韵言怀","f":"七言律诗","c":["房陵回首望淮东，物土人情未易同。","比屋蜂悬人带瘿，乱山戟立势凌空。","污鲰共餍川人食，简朴仍存太古风。","破我残年七百日，尽抛诗卷酒杯中。"]},{"t":"次韵陈秀才二首 其二","f":"七言律诗","c":["七字开缄粲陆离，元非剑气烛圜扉。","夜光信出老蚌壳，锦段遽分邻女机。","庭赋继今行北阙，市娼过眼忽南威。","蜚腾可但荣亲计，我亦他年得俊归。"]},{"t":"次韵陈秀才二首 其一","f":"七言律诗","c":["吏治因循俗已疵，可无柱后济宽慈。","顾惭德化一何取，敢意古人三不欺。","剔蠹方图洗熏染，放麑端复惎衰迟。","成君今段莱衣笑，莫更风前赋百罹。"]},{"t":"次韵陈学正 其二","f":"七言律诗","c":["自审江湖槁项翁，浪将张邴并高风。","就闲耕钓真无说，投合侯王况不工。","策足不应诸俊后，如君宁复老夫同。","亟须秉烛欢游地，行簉英雄入彀中。"]},{"t":"次韵陈学正 其一","f":"七言律诗","c":["区中尘外自由身，囊不留钱最入神。","便约春秋同保社，不妨天地著陈人。","园翁溪友曾无间，野蔌山肴继荐新。","却叹声名雪堂老，莫年岭海梦峨岷。"]},{"t":"次韵陈倅赵宰双竹","f":"七言律诗","c":["两君深结此君缘，句里萧森堕我前。","笋茁便应欺瑞麦，诗成端合付双莲。","窗间俪影斜新月，风处骈梢袅绿烟。","会拟韩公颂连理，为渠小辍枕书眠。"]},{"t":"次韵陈梦锡","f":"七言律诗","c":["手板夤缘替荷锄，从渠争挟子公书。","三年已办青箱蠹，一饱才分代舍鱼。","烟烬萁炉朝兀兀，窗明风霰夜疏疏。","独思把酒看君醉，墨汁淋浪点翠裾。"]},{"t":"次韵周秀才","f":"七言律诗","c":["暇日枝筇对摇落，衰年悲感为谁多。","政疏里俗有嗫呫，身远贵游无孰何。","耐病阻陪吹帽醉，祛愁聊复击樽歌。","诗来起我湖海兴，梦逐狎鸥分白波。"]},{"t":"次韵招饭不赴","f":"七言律诗","c":["吏能儒业实惭名，晚喜论交盖代英。","千里久劳魂梦往，一欢犹阻咄嗟成。","粲花论胜违频听，击钵诗工况莫京。","别后槱溪萦望眼，此心川水漫东倾。"]},{"t":"次韵林子长","f":"五言律诗","c":["诗坛旧同歃，攀附不无因。","揽辔今肤使，回辕记老身。","云泥知已隔，谭笑尚容亲。","不记棋前酒，当时定几巡。"]},{"t":"次韵林子长一首","f":"七言律诗","c":["使华不袖生春手，绛老泥涂亦使年。","病后隐沦甘甫里，向来魂梦颇祁连。","受廛已傍乡三老，对客还矜我二天。","处士一星君漫记，会扬光彩映台躔。"]},{"t":"次韵罗春伯提举","f":"五言律诗","c":["龙公靳飞雨，盍趁望时来。","尚及丰年计，真令笑口开。","池莲端自若，月地信佳哉。","倚槛西风夜，题诗判费才。"]},{"t":"次韵郑同年饯行","f":"七言律诗","c":["一官自食天水草，群隽追奔风马牛。","俭幕胡宁效涓滴，孔装未拟借膏油。","交情顾我失一臂，才地较君输几筹。","更引功名挽衰朽，天生江水不西流。"]},{"t":"次韵战舰","f":"七言律诗","c":["下濑千艘旧擅名，汉家虓将况飞英。","呼韩款渭人胥后，小耿平齐事竟成。","击楫定无违庙算，覆盂端有奠神京。","圣君动静天人合，持满何妨亦定倾。"]},{"t":"次韵赵帅四首 其二","f":"七言律诗","c":["北归客子谩贪忙，河欲生冰野覆霜。","他日鹳鹅常避敌，即今竿木又逢场。","思迟正坐相如渴，文好知熏武仲香。","妙语鼎来吾拜手，乳泉更用汲银床。"]},{"t":"次韵赵帅四首 其三","f":"五言律诗","c":["我亦饱参僧，赢粮走百城。","诸公传句法，夫子擅诗声。","自笑屠龙误，时须画鹜成。","峨肩出苦语，蛩夜共凄清。"]},{"t":"次韵赵帅四首 其二","f":"五言律诗","c":["腹里群经笥，毫端五字城。","少陵宁漫兴，侯喜欲无声。","窃听锵金奏，仍闻破竹成。","君知盥手处，毛骨为谁清。"]},{"t":"次韵赵帅四首 其三","f":"七言律诗","c":["月姊多情闯绮窗，停云著意护飞霜。","艳桃秾李宽围坐，舞雪歌云各擅场。","醉倒不堪酬礼数，归来赢得梦魂香。","明朝谁省扁舟客，但载茶铛与笔床。"]},{"t":"次韵赵帅四首 其一","f":"五言律诗","c":["藩方人奠枕，楚尾铁为城。","晓日熙仁惠，春雷殷政声。","护边一李绩，增户几王成。","笑指琼花露，如公彻底清。"]},{"t":"次韵赵帅四首 其四","f":"七言律诗","c":["舟子喧呼解缆忙，驼裘答飒冷禁霜。","行分槁项新岐路，心属毛锥旧战场。","谈笑惯陪北海酒，馥膏拟炷后山香。","诗筒傥肯生毛羽，飞到幽人梦蝶床。"]},{"t":"次韵赵帅岁暮","f":"五言律诗","c":["虚心观物变，投老得诗穷。","玄草居然白，炉萁却暂红。","诗缘梅隽发，愁倩酒消融。","未用凌羁客，疏帘逗雪风。"]},{"t":"次韵赵帅登平山堂 其三","f":"七言律诗","c":["修月于今第一功，后车九万蜀笺红。","诗供寒食莺花课，袖拂平山杨柳风。","匝坐蕙兰歌似剪，生香笑语酒如空。","胡床不减南楼兴，今古风流正自同。"]},{"t":"次韵赵帅登平山堂 其二","f":"七言律诗","c":["平章景物我何功，犹博宾筵醉颊红。","欢甚锐戈思却日，吟馀豪兴欲凌风。","急觞泛滟春浮渌，掺鼓喧轰雁堕空。","白雪拜嘉仍袖手，汗颜终恐坐雷同。"]},{"t":"次韵赵帅登平山堂 其一","f":"词","c":["东皇未慭养花功，远近娇红乱老红。","胜赏已容陪隽轨，凭虚仍喜受雄风。","小?蜀井寒冰齿，旋俯波光碧蘸空。","更看诗翁落椽笔，弹丸句法许谁同。"]},{"t":"次韵赵帅赏古梅","f":"七言律诗","c":["把酒花前量自宽，花同人意惬轻寒。","盈盈似驾翠虬起，特特为邀青眼看。","纸贵共誇诗律细，客来旋报粉香残。","若为白璧青钱费，可问东君博此欢。"]},{"t":"次韵赵教授 其一","f":"七言律诗","c":["争米何心问斗城，聚蚊底许太狂生。","未遑饩粟如子罕，谩复公言付阿平。","缓我愁肠千缕结，羡君笔力万钧轻。","何时去上中和颂，却用诗情写物情。"]},{"t":"次韵赵教授 其二","f":"七言律诗","c":["携孥西垒复东城，触处千愁百恨生。","如许尧民艰粒食，未应汉法废常平。","爱君长策三农重，泥古迂儒一芥轻。","会略文移倒陈廪，一时骨肉慰皇情。"]},{"t":"次韵袁丈知府喜雨","f":"七言律诗","c":["使君今代段荆州，指顾为霖旱不忧。","比屋便令开笑口，散人亦复掉吟头。","封君擅富宁容数，义廪赒贫可待求。","想阅贺章天更喜，津津玉色动凝旒。"]},{"t":"次韵袁宪雪二首 其二","f":"七言律诗","c":["天怜梅蕊怯摧残，善后何妨小作悭。","一雪应期真望外，三诗说喜想颜间。","瑶花已兆食四釜，沉炷为通天九关。","捲帐盍酬民气乐，苏台持酒挹湖山。"]},{"t":"次韵袁宪雪二首 其一","f":"七言律诗","c":["犯雪回帆岁遽残，自怜雨涩更风悭。","从游已落邹枚后，著语渠能季孟间。","梦逐蜚仙凌色界，谁因逋客护云关。","独思快目毗陵晓，玉衬金波妥锡山。"]},{"t":"次韵袁提刑劳军许浦中路风雨","f":"七言律诗","c":["方隅咫尺俨威颜，穷谷回春不作难。","渥泽欲随金节到，先声已失铁衣寒。","来时敢惮风将雨，泊处仍听浪卷滩。","天自与公供壮观，海涵云物正阑干。"]},{"t":"次韵郭教授雪二首 其一","f":"七言律诗","c":["皇心忧喜与民同，帝意深怜岁不丰。","瑶检何时下仙界，瑞花一昔覆寰中。","和声已自消疵疠，陈廪从知饱困穷。","今世皋夔活国手，信知人职代天工。"]},{"t":"次韵郭教授雪二首 其二","f":"七言律诗","c":["诗力骎骎雅颂同，人言平处逼熙丰。","清篇自昔传平水，妙曲何人和郢中。","颇怪鲸牙须手揽，悬知鼠技笑吾穷。","衰慵合袖推敲手，且可旁观斲鼻工。"]},{"t":"次韵高机宜送别 其一","f":"七言律诗","c":["棋枰诗课忆同堂，转首暄寒几蔀章。","每叹羁离念陈迹，更因衰病感流光。","亟催江鹢休停棹，已信溪禽不乱行。","鱼澳芋区真好在，连宵归梦为谁长。"]},{"t":"次韵高机宜送别 其二","f":"七言律诗","c":["士价如君定玉堂，陈陈腹笥汉文章。","即今綵笔春争媚，它日青藜夜有光。","诗力不劳凌汝辈，才名况自溢班行。","清篇见属吾何取，愧闯辞坛阙寸长。"]},{"t":"次韵高宾王见投四首 其四","f":"七言律诗","c":["知君斲句为祛愁，得句须防有暗投。","我病床头但周易，人谁皮里著阳秋。","骑驴久袖推门手，载酒慵移捉月舟。","祇命君诗作三益，伴翁听雨卧徐楼。"]},{"t":"次韵高宾王见投四首 其三","f":"七言律诗","c":["檐花如雾湿黄昏，犹梦君前白兽樽。","但有红尘染衣袂，更堪碧草思王孙。","逃威正坐齐竽谬，歈舞难招楚客魂。","回首仙曹云雨上，谁云九虎踞天门。"]},{"t":"次韵高宾王见投四首 其二","f":"七言律诗","c":["病念还家可奈愁，客中日月急梭投。","土花晕壁迎梅雨，海燕将雏送麦秋。","沾袖正怜珠陨睫，关门能复玉为舟。","支头閤膝高舂卧，黄奶青奴共此楼。"]},{"t":"次韵高宾王见投四首 其一","f":"七言律诗","c":["残年病眼苦眵昏，尽屏甘腴誓绿樽。","龙树难逢刮膜手，孟公顾有独醒孙。","颇烦十吏供挥扫，无奈诸峰役梦魂。","友义惟公记衰疾，新编肯到雀罗门。"]},{"t":"次韵高缙之二首 其二","f":"五言律诗","c":["奚囊走湖海，襟度极风流。","学力隐一敌，才华追二刘。","与时君有用，漫仕我非优。","它日霄霏上，诗成复寄不。"]},{"t":"次韵高缙之二首 其一","f":"五言律诗","c":["能事馀千牍，幽期自一丘。","向来书襞积，不疗客漂流。","小挹苏耽鹤，同歌宁戚牛。","几时诗酒社，相属话天游。"]},{"t":"次韵寄王帅属","f":"七言律诗","c":["才华奔逸可能追，我识王郎自壮时。","酒处每看鲸吸海，书成还想墨为池。","穷交徒自怜东野，孰看于今敬道儿。","莫靳诗筒数还往，人生何处不儿嬉。"]},{"t":"次韵寄汪教授二首 其二","f":"七言律诗","c":["客路何人起病怀，论交今得谪仙才。","每当玉麈玄谭胜，不问铜壶漏箭催。","鲁泮旧常烹瓠叶，广平聊复赋江梅。","揆予傥可陪英轨，莫向诗筒靳往回。"]},{"t":"次韵寄汪教授二首 其一","f":"七言律诗","c":["友贤端许写中怀，千丈孤标十倍才。","黄绢旧知儒业富，黑头宁受岁华催。","笔囊小却司盘诰，鼎实终期荐傅梅。","指日元侯矕龙衮，未容文学久低回。"]},{"t":"次韵寄陈主管","f":"七言律诗","c":["轺軿七十晓相追，记得张园叙拜时。","香衬蕙兰来北里，云随笙鹤燕仇池。","朋簪重盍宁人力，贫仕居卑听化儿。","祇冀幕莲分靫菂，诗坛棋社与闲嬉。"]},{"t":"次韵常倅俞君任二首 其二","f":"七言律诗","c":["与君颜面各临年，同滞江湖恐不然。","虎兕向来甘旷野，骅骝宁复待挥鞭。","政成合进凌霄步，客里犹抬斲句肩。","人品国华君可仰，岂应学我赋归田。"]},{"t":"次韵常倅俞君任二首 其一","f":"七言律诗","c":["匆匆同醉记前年，客路重逢亦偶然。","理窟扣君弥入域，生涯怜我欠加鞭。","了知富贵难投足，共约归来径息肩。","旧欲将雏卜邻去，未应须办十牛田。"]},{"t":"次韵常熟感旧","f":"七言律诗","c":["诗囊随处纪山川，古县繁雄更海边。","按节将春巡甲垒，循陔回首记丁年。","綵衣尚念亲三釜，芝检终当岁九迁。","移孝为忠贤圣事，期公迄反汶阳田。"]},{"t":"次韵章守移学","f":"七言律诗","c":["千柱崇成俨旧规，小劳移筑未为非。","诸儒受业三熏沐，贤守收功一指挥。","蒇事此时争拭目，决科它日看增辉。","问玄亦复侯芭事，可但经生识指归。"]},{"t":"次韵章宰 其二","f":"五言律诗","c":["游旧多厌绝，怪君终眷知。","帐留仍碧酒，纻献更清诗。","风义固难及，月评无乃私。","相从文字乐，悔作十年迟。"]},{"t":"次韵章宰 其一","f":"五言律诗","c":["穷山从薄宦，小郡著衰翁。","政术甘疏拙，辞坛敢长雄。","一饥才自救，五细未宜中。","又拟包羞去，京尘冒软红。"]},{"t":"次韵彭景贶","f":"五言律诗","c":["鸠杖随身去，乡园得自娱。","红鲜终日有，俗物向来无。","酒所挥椽笔，风前据槁梧。","逢人休举似，儿辈笑吾徒。"]},{"t":"次韵彭景贶","f":"七言律诗","c":["紫燕穿帘若有求，为人端作置书邮。","诗翁别后犹能酒，妄尉归来亦未侯。","江閤香温留语笑，花楼月好记从游。","即今满眼悲凉意，投老宁禁此段愁。"]},{"t":"次韵程帅二首 其一","f":"七言律诗","c":["平时渭北与江东，文会宾筵幸许同。","政使迟迟嗟去鲁，未应咄咄遽书空。","抄诗奚翅无瑕璧，会意俄乘在下风。","更喜朝来宾雁足，阳春封寄客涂中。"]},{"t":"次韵程帅二首 其二","f":"七言律诗","c":["从昔文章盖代翁，言间有物自无同。","娟妍徒玩花含露，洒落还惊月印空。","底许贱工惭擢矢，信知妙斲有成风。","古今一印元呈露，要在神融领会中。"]},{"t":"次韵程帅二首 其二","f":"七言律诗","c":["人间尘不到筹边，诗老乘閒思涌泉。","千佛香名仍世继，一灯素业自家传。","斗城一去嗟多病，宾幕重登便半仙。","要看诸郎各行马，染须膏面计留年。"]},{"t":"次韵程帅二首 其一","f":"七言律诗","c":["满怀披雾慰生平，到日音容隔暮城。","想见舟中留郭泰，可能酒处欠公荣。","韦家相业应门户，谢氏才华况弟兄。","愧我携儿在尘滓，寸田硗埆望茨京。"]},{"t":"次韵程帅游习池三首 其三","f":"七言律诗","c":["青编勋业笑谈追，千载生贤瑞圣时。","竹帛会书河似带，封疆不止汉为池。","玄谭日属王平子，妙语心轻谢客儿。","来岁赏花应帝所，赓歌宣劝倍欢嬉。"]},{"t":"次韵程帅游习池三首 其二","f":"七言律诗","c":["清明胜赏尚容追，不减觞浮曲水时。","坐觉晴云恋歌扇，看供吟笔泻天池。","春光有底遽如许，酒量勉添些子儿。","可但大堤民气乐，啼莺语燕共嬉嬉。"]},{"t":"次韵程帅游习池三首 其一","f":"七言律诗","c":["牙纛犹容后乘追，枕书不出此何时。","香飘玳席千花坞，影倒妆光百子池。","诗句肯藏扪虱手，仙曹容著牧羊儿。","回思行李冒尘土，更喜百忧偷一嬉。"]},{"t":"次韵答许推章宰二首 其二","f":"七言律诗","c":["北来青翼导霓旌，翩若凌云鹤驭轻。","烟柳困眠才寤晓，露花酣醉正熹晴。","献之能赋虽辞罚，楚客同醒恐不情。","豪兴尚堪追少隽，漏卮灌酒鲙长鲸。"]},{"t":"次韵答许推章宰二首 其一","f":"七言律诗","c":["矞云非雾霭飞浮，满听游人载路讴。","痛饮君能判濡首，新翻我亦办缠头。","羽觞潋滟风微度，翠盖蹁跹晚尚留。","且倩银钩写陈迹，未须诗律压刘侯。"]},{"t":"次韵答张丞","f":"七言律诗","c":["顾省辞华分槁乾，簿书堆里作粗官。","客怀止饮仍多病，海气乘秋早戒寒。","好语相濡真禁脔，不才持答欠琅玕。","从今恶况能排遣，日课君诗一再观。"]},{"t":"次韵答高宾王 其一","f":"七言律诗","c":["向来骑凤下天津，冠屦因循混世尘。","行处西湖作西子，静中佳茗是佳人。","秋风暗凝金茎露，香雾潜浮海树春。","唤萼绿华书玉叶，人间新笔有通神。"]},{"t":"次韵答高宾王 其二","f":"七言律诗","c":["陂量如君信有容，诺金到我岂宜蒙。","蛾眉自古偕三惑，虎旅何心待九攻。","雨室聊辞秉烛女，石肠莫笑叩舷翁。","吾徒妩媚青编在，檗茹冰栖定隽功。"]},{"t":"次韵答龚泽卿","f":"七言律诗","c":["君如绿耳抹流沙，躞蹀追风不待挝。","缀葺曾童楚山竹，燕游行插曲江花。","久烦凤诏搜奇逸，定复龙光叠宠嘉。","叱咤即今凌笔阵，坐令楚幕集归鸦。"]},{"t":"次韵答德瑞","f":"七言律诗","c":["诗客胸襟旧绝尘，惠然分我一缄春。","裁成蜀国添花锦，贵重丹砂伏火银。","暮雨朝云知有梦，琼枝璧月可无人。","要须共醉彭宣酒，莫诿忘情宋玉邻。"]},{"t":"次韵谢陈守伯固","f":"七言律诗","c":["投老登龙借齿牙，可能病骥待挥挝。","清篇久矣窥修月，谹论琅然听粲花。","小却御屏书姓字，行当宣室拜亨嘉。","恩章衮衮从天下，浓墨疏行砌乱鸦。"]},{"t":"次韵谢程帅复游习池见寄二首 其二","f":"七言律诗","c":["风流羊杜不劳追，况复轻裘缓带时。","醉倒莫孤桃李月，诏归恐便凤凰池。","政传西蜀中和颂，笔跨东京大小儿。","我亦抄诗支郡去，公馀吟玩取娱嬉。"]},{"t":"次韵谢程帅复游习池见寄二首 其一","f":"七言律诗","c":["名园壮观还前日，禊事追游可后时。","试问绣筵张绿野，何如诗客到昆池。","绮罗香外莺偷眼，花柳稀间鸟哢儿。","定许此民同此乐，春城无处不嬉嬉。"]},{"t":"次韵漕使张守二首 其二","f":"五言律诗","c":["授书天佐汉，鼓箧客师韩。","气宇包溟渤，辞锋凛莫干。","经纶股肱似，姓字齿牙寒。","不作规随起，谁令九鼎安。"]},{"t":"次韵漕使张守二首 其一","f":"五言律诗","c":["政绩新皇眷，功名旧壮怀。","人才双立玉，笔势各排淮。","鹏路天惟咫，鲰生骨未埋。","行看仲淹弼，接武冠尧阶。"]},{"t":"次韵犒士","f":"七言律诗","c":["万灶连连俨旧屯，朝来喜气袭人温。","固知除器须平日，政复投醪亦至恩。","帝綍函春周垒壁，使星回耀照和门。","文经武纬君王圣，汗简须公纪治原。"]},{"t":"次韵翟元卿 其二","f":"五言律诗","c":["我困枘投凿，君才瓴建高。","要之同臭味，政以借熏陶。","觞咏聊真乐，媸妍付尔曹。","能来缓诗颊，芋火荐松醪。"]},{"t":"次韵翟元卿 其一","f":"五言律诗","c":["君是儒冠秀，源流况父兄。","文堪一战霸，气欲五郎卿。","与世甘多遌，谋生迄未成。","其谁为推挽，小试合承明。"]},{"t":"次韵樊汊","f":"五言律诗","c":["荒政赖贤守，湛恩推上方。","龚黄真父母，秦越肯圻疆。","手自起僵仆，术先销暴强。","膏肓得司命，铭肺可能忘。"]},{"t":"次韵赠高宾王二首 其二","f":"七言律诗","c":["滞留无地豁闲愁，诗将坛高许客投。","过我肯论新旧雨，即君如望蓘穮秋。","几时雾縠搴蛟室，快意湍涛放鹢舟。","搯抉肾肠须小息，请携霜竹上危楼。"]},{"t":"次韵赠高宾王二首 其一","f":"七言律诗","c":["瓦注缘穷也自昏，扫除胶扰近清樽。","瘦田可谷宜投劾，小子今年亦抱孙。","惯病已拚疏药物，就闲聊免怆吟魂。","径当云卧山南北，芋火醅缸昼掩门。"]},{"t":"约二同年游虎丘","f":"七言律诗","c":["兼旬闭户耐寒威，起视晴空碧四围。","黄鸟啼边忽游子，白龙去后渐单衣。","年时尚记寻芳约，老境仍怜得醉希。","红影幽香虎丘路，杖藜携酒莫相违。"]},{"t":"约二赵棋集雨不果来","f":"五言律诗","c":["客子离群意，萧斋只睡宜。","得无新雨叹，漫有故人期。","日力须棋局，风凉入酒卮。","转头车妇去，相忆各儿痴。"]},{"t":"约吕徐二友游净慈二首 其二","f":"七言律诗","c":["一笑成行不待营，可无条约谂同盟。","盘餐取饱真君事，杯酒邀欢太俗生。","拨冗得闲殊自乐，吸光饮渌不胜清。","即今冷眼聚蚊梦，彼此劣优君试评。"]},{"t":"约吕徐二友游净慈二首 其一","f":"七言律诗","c":["芒鞋明日踏晴沙，肯学渠侬走狭斜。","天井巷前休倦足，暗门城外把煎茶。","暂同佛屋僧庖饭，徐访姚黄魏紫花。","要及钱唐尚留钥，共揄吟袂缓归家。"]},{"t":"约徐南卿出游","f":"七言律诗","c":["古寺周围锦树窠，清湖演漾曲尘波。","偷闲已计三餐反，败兴其如一雨何。","政复小孤鸥鹭约，未妨来校鲁鱼讹。","春光尚有三之一，徐办苏堤一再过。"]},{"t":"行都","f":"七言律诗","c":["露冷河倾斗柄低，望仙桥外独归时。","风梳御柳娟娟静，月度觚棱故故迟。","几处清歌留客醉，谁家长笛倚楼吹。","太平喜乐朝仍暮，帝力何曾尔辈知。"]},{"t":"行都夜归","f":"七言律诗","c":["灯火通衢苦未稀，望仙桥外独归时。","风梳御柳娟娟净，月傍觚棱故故迟。","隐地轮蹄忘夜旦，几家楼閤不金丝。","时平睿泽天无外，帝力何曾尔辈知。"]},{"t":"西林访铦师","f":"七言律诗","c":["天将宿雨净春空，却著湖山鼓吹中。","载酒言辞藉花伴，运斤来看斲泥工。","前身师定参寥子，拙宦吾今张长公。","俛首人间皆长物，未妨分飨北窗风。"]},{"t":"观山刑鹅夜归","f":"七言律诗","c":["巢鹊枝蜩已罢鸣，风声露气可胜清。","人谙浅濑安然度，月隔高林未肯明。","却乱宿云寻去路，渐因更鼓辨孤城。","谁知岁事关心切，翻忆冲泥傍险行。"]},{"t":"观诸公射于城北书壁二首 其二","f":"五言律诗","c":["尘我玉蟾蜍，弦君金仆姑。","分曹双壁立，中隽万人呼。","壮岁功名地，从渠山泽儒。","他年玉音问，册府起孙吴。"]},{"t":"观诸公射于城北书壁二首 其一","f":"五言律诗","c":["旧约已汤饼，新欢仍碧香。","小闲障日手，同憩卧云庄。","群彦矢复沓，老夫诗在囊。","蔬畦暝晚色，野兴为谁长。"]},{"t":"过八叠山","f":"七言律诗","c":["路入于平舒倦眼，襄阳佳处亦班班。","烧香岘好思三岘，八叠山高似万山。","喜此经行无雨阻，向来游览坐天悭。","山灵定笑贵野鹜，默遣归求邦域间。"]},{"t":"过八叠铺问宿","f":"五言律诗","c":["平野俄空阔，遥山且有无。","斜阳对扪虱，暝树忽啼乌。","老去犹羁旅，生平颇壮图。","田翁诧丰岁，不拟话为儒。"]},{"t":"过伏龙祠","f":"七言律诗","c":["蜀栈荆江志未酬，两京直拟笑谭收。","仅容孱后存酅祀，谁遣东吴解魏仇。","制敌岂应无法正，为谋不合有谯周。","伏龙祠上长烟霭，愤气堂堂恐未休。"]},{"t":"过樊村","f":"五言律诗","c":["几日囚笼鸟，今朝纵壑鱼。","空劳计迟速，凡百有乘除。","岸势惊禽过，江声午梦馀。","心融得新句，澄水滴铜蜍。"]},{"t":"别赵文卿明府","f":"七言律诗","c":["人品推君第一流，论文向我肯绸缪。","日从红粉追谭笑，家置青编纪唱酬。","转首各乘凫背去，几时同作凤城游。","临风莫道书难寄，旅雁飞还是便邮。"]},{"t":"劳农净居赠皎启二僧","f":"七言律诗","c":["劳农今喜复南辕，夹道扶携亦笑諠。","县尹庶几无疾病，山人迎送耐频烦。","芼葱汤饼聊堪饱，出瓮春醪半带浑。","惟有为民真实意，异时陈迹付公言。"]},{"t":"即事","f":"七言律诗","c":["泛蚁醪敷且命斟，中年节物自关心。","风前千柳竞春态，烟际一鸠啼晏阴。","急景绝怜添鬓雪，芳辰犹阻盍朋簪。","年时醉藉梨花地，回首鸥盟可得寻。"]},{"t":"即事","f":"七言律诗","c":["江漾晨光入县门，楼斜晚影到渔村。","海声不为无风静，山色居常带雾昏。","问俗即今防愒日，来时抚事错销魂。","浮生寄寓君恩重，未觉天涯异故园。"]},{"t":"即事","f":"五言律诗","c":["平昔功名念，如今冷似灰。","藏书堪乐死，望岁待归来。","小宅依城筑，虚檐枕水开。","溪翁诗社侣，有酒剩追陪。"]},{"t":"即事","f":"五言律诗","c":["侧径苔竹润，短篱鸡鹜喧。","小停障日手，聊憩卧云村。","绿影乌皮几，新醅老瓦盆。","平生农圃计，重与野人论。"]},{"t":"县西","f":"七言律诗","c":["一径斜穿荦确行，身闲尤觉马蹄轻。","坡头嘉树千幢立，烟际长江匹练横。","茶鼓适敲灵鹫院，夕阳欲压赭圻城。","一春簿领沈迷里，野鸟山花眼最明。"]},{"t":"县圃酴醾","f":"七言律诗","c":["北园红紫已蜚尘，始放幽亭烂熳春。","叠翠影低珠幰重，洗妆人倦玉容真。","蔷薇清露疑分派，茉莉评香且外臣。","领略浓芳须好语，即令袖手恐花嗔。"]},{"t":"寿皇圣帝挽章三首 其三","f":"五言律诗","c":["慈俭遵先志，刚明肖上乾。","题期千一遇，跻治五三前。","他日山藏壑，终天泽漏泉。","稽山穿望眼，松影五云连。"]},{"t":"寿皇圣帝挽章三首 其二","f":"五言律诗","c":["受授光尧禹，规摹陋汉唐。","皇图开寿域，国步坦康庄。","检玉方慈范，乘云忽帝乡。","华夷均孺慕，矫首涕滂浪。"]},{"t":"寿皇圣帝挽章三首 其一","f":"五言律诗","c":["孝俭超千古，初终秉一心。","时前未央酒，每惜露台金。","遗范天同久，湛恩海与深。","攀摧恸夷夏，悲泪作秋霖。"]},{"t":"张丞再有诗次韵","f":"七言律诗","c":["仰高排奡玩清圆，学力卑摧旧判年。","后进或夸金掷地，前修犹是斗横天。","晚规省语安衰病，暇复分题搅醉眠。","祇有君诗追古作，未忘缃素遣儿传。"]},{"t":"李粹伯挽章二首 其二","f":"五言律诗","c":["病酒漳滨久，传闻信复疑。","为郎真地下，哭友漫天涯。","雨绋何由挽，风松想助悲。","自今思有道，时展蔡邕碑。"]},{"t":"李粹伯挽章二首 其一","f":"五言律诗","c":["今代论时杰，如公未易量。","冰壶钟器质，绣段粲文章。","遂郁鸾台望，俄成马鬣藏。","忠贤如此尔，天意竟茫茫。"]},{"t":"杜母","f":"七言律诗","c":["杜母遗芳岂远求，田功谁比此邦优。","麦疄桑陇疑淮左，近水遥山似秀州。","楼识景疏知俗美，亭因思孟各风流。","我来眷眷淳厖处，比屋嬉嬉路载讴。"]},{"t":"杨侍郎召饭再用韵","f":"七言律诗","c":["升沉渠敢话齐年，妙句推褒辈行然。","高燕况叨琼作醴，凡骀底称玉为鞭。","歌终画扇犹遮面，舞困攲花半压肩。","此去隽游萦客梦，梦陪笙鹤下琼田。"]},{"t":"杨家会小坐","f":"七言律诗","c":["断蜺收尽有云屯，月映苍茫山敛昏。","白露素空犹暑意，碧林危叶已秋痕。","鸟乌定为何人乐，络纬惟能竟夕喧。","老阅流光易悽惋，惜无佳客共清樽。"]},{"t":"步西湖次韵徐南卿 其二","f":"五言律诗","c":["杨园骞绝岭，万象赴窥临。","坐久岚霏润，来时翠碧深。","莺花自佳处，鱼鼓亦丛林。","谁在飞埃外，芸芸付陆沈。"]},{"t":"步西湖次韵徐南卿 其三","f":"五言律诗","c":["山寺曾题竹，寻诗记所临。","缘云俯空旷，扪石探幽深。","倦鸟低平野，蔫花下碧林。","沙头催唤渡，空水远沈沈。"]},{"t":"步西湖次韵徐南卿 其一","f":"五言律诗","c":["载酒幽寻地，乘闲得再临。","丽黄啼晓霁，魏紫笑春深。","抚事挥犀管，他时梦鹤林。","心期更阒寂，物理付升沈。"]},{"t":"步西湖次韵徐南卿 其八","f":"五言律诗","c":["诗课逭离索，萧窗谁肯临。","语方逢众怒，自诧用功深。","未议辞穷鬼，才堪补笑林。","旧交多册府，肯信有湮沈。"]},{"t":"步西湖次韵徐南卿 其七","f":"五言律诗","c":["西湖千顷画，政用好诗临。","鉴揭雾解駮，屏纡云浅深。","钿车随宝马，红舫度青林。","归去开囊锦，君先炷水沈。"]},{"t":"步西湖次韵徐南卿 其四","f":"五言律诗","c":["水月春犹浅，携壶记此临。","云烟澹闲寂，鱼鸟媚清深。","堤路俄人海，侯家或肉林。","高楼下金弹，帘影眇深沈。"]},{"t":"步西湖次韵徐南卿 其五","f":"五言律诗","c":["徐子学诗苦，砚池宁暂临。","课功初赑屃，著语遽精深。","更积岁月力，傥陪英俊林。","人生才业地，渠辈分平沈。"]},{"t":"步西湖次韵徐南卿 其六","f":"五言律诗","c":["徐郎小隐处，爱我许迂临。","多遌话岁晚，言归忘夜深。","祛愁倚诗酒，结伴卜山林。","更喜檀栾旧，风烟挺绿沈。"]},{"t":"汪叔量白酒","f":"七言律诗","c":["妙诀何年受异人，酿成珍齐祇逡巡。","端忧肯念霜髯客，取醉时分玉色春。","篘处想如君德厚，饮来浑类我诗醇。","借书问字渠须计，走马鸣鞭莫厌频。"]},{"t":"言怀二首 其二","f":"七言律诗","c":["自是三生贺季真，亟应收拾水云身。","蜚凫吏隐聊同俗，饭犊生涯且耐贫。","林壑风烟当未慭，利名缰锁听横陈。","世间静者犹张邴，老境婆娑定笑人。"]},{"t":"言怀二首 其一","f":"七言律诗","c":["此身与世分相违，可是平生不见几。","知己方占白鸡梦，寸心已傍碧山飞。","周旋觞咏须三益，斟酌行藏欠一归。","甓社湖西隐君子，为翁应扫钓鱼矶。"]},{"t":"谷城道中","f":"七言律诗","c":["何许珠襟绣袂娘，额黄胸粉自新妆。","野芳贪折髻丫重，蝴蝶乱随裙幅香。","缓唱采菱空答响，小留挑菜翠盈筐。","汉风未许休乔木，行客相逢莫漫狂。"]},{"t":"近榆亭 其七","f":"五言律诗","c":["少日接为构，无何了桑榆。","邀食有馀地，何事须千奴。","此亭与此木，到眼聊为娱。","五诗信睡语，定博君卢胡。"]},{"t":"还王编修诗卷","f":"七言律诗","c":["奕奕长篇间短吟，子綦天籁伯牙琴。","几人不溺西昆体，老我亲聆正始音。","得宝浑惊探骊颔，换金当复售鸡林。","还诗正恐非子助，昼易忘饥夜易深。"]},{"t":"闲适二首 其二","f":"七言律诗","c":["丁年故纸枉埋头，老去时名底用求。","得句盖尝身被谤，屏书姑免眼为仇。","关门工作橐驼坐，阅世已冥鹏鴳游。","槁木山麋真适适，从来里舍议家丘。"]},{"t":"闲适二首 其一","f":"七言律诗","c":["人间火烈更风蜚，笑杀幽人咏桧枝。","贪赴敌场争腐鼠，宁知造物玩痴儿。","百年扰扰玄驹聚，万化悠悠野马驰。","老子床头但周易，尚容隐几耐支离。"]},{"t":"閒题","f":"七言律诗","c":["自笑冠裳裹沐猴，只今江海信虚舟。","断无贝阙珠宫梦，好在黄鸡紫蟹秋。","诗外尽为闲日月，人间分占素公侯。","政须鸥鹭供青眼，未厌山林映白头。"]},{"t":"饮客","f":"七言律诗","c":["暑气凭秋已自消，可能枯策伴良宵。","试开玉友招诗客，共吸金波对舞腰。","人近笙歌堪耐老，天非风月定无聊。","簿书正使无闲暇，卜夜时须慰寂寥。"]},{"t":"饮殖轩","f":"七言律诗","c":["病骨今朝觉倍轻，云天昨夜已全晴。","烂游花木欣荣处，剩喜风烟指顾生。","春草池塘频入梦，夜窗灯火会寻盟。","怅然又与禽鱼别，波影沉堤晚照明。"]},{"t":"京口呈张閤学 其二","f":"七言律诗","c":["色辞他日慰凄凉，别去吴山楚水长。","蚁国槐安消几梦，鹤归华表恐千霜。","安排久餍冷官饮，软语重登君子堂。","所惜将迎无暇日，妨人诗律悟濠梁。"]},{"t":"京口呈张閤学 其一","f":"七言律诗","c":["归怀未用话南园，卧治于今又北门。","但息儿啼宽上意，小稽霆击取中原。","虎头锐视非无种，狮子当觞且勿喧。","更恐谭公家世事，断无宣劝定惊魂。"]},{"t":"到任交权州事筵致语口号","f":"七言律诗","c":["假印侯封付继承，教条久已洽山城。","政成何异徵黄霸，日接宁惟拜水衡。","春酒入杯红浪涨，晚花荐座靓妆明。","良辰便合同沉醉，且置阳关叠后声。"]},{"t":"和张秀才","f":"七言律诗","c":["山川向晚点尘无，忽讶筛琼屑玉铺。","巧与梅花争便旋，试将姑射比肌肤。","破寒春酒何曾酽，荐箸穷鸠不料臞。","陵藉东君从作意，未妨芽甲暗昭苏。"]},{"t":"夜雨","f":"五言律诗","c":["窗声呼梦断，灯影尚微茫。","忽扫蚊专夜，从知雨献凉。","佳眠嗟莫续，残漏耿犹长。","却忆檠三尺，冯书怯曙光。"]},{"t":"夜宿商卿家","f":"七言律诗","c":["萑蒲无警南塘静，歉岁村讴鼓罢挝。","更喜良宵共谭麈，几烦亲手剪灯花。","酌无多酒仍馀味，懒不吟诗政自嘉。","蝶梦蘧蘧才一霎，邻鸡啼罢又啼鸦。"]},{"t":"官居二首 其二","f":"五言律诗","c":["官居不惜日，宰县动三年。","忍事肠欲烂，为防头救燃。","不应一饱计，长受众人怜。","俛仰堪供笑，人间海易田。"]},{"t":"官居二首 其一","f":"五言律诗","c":["磔磔初鸣晓，通通已报衙。","拙勤知待旦，欺绐未停挝。","漫役乡园梦，祇添老眼花。","屈信庸敢计，斗禄倚生涯。"]},{"t":"定海四首 其四","f":"五言律诗","c":["官廨盐烟外，居人杂贾胡。","听言须画字，讨海倚输租。","习俗何妨陋，鲜肥颇不无。","已甘三载住，畴昔计乘桴。"]},{"t":"定海四首 其三","f":"五言律诗","c":["穫稻来硗埆，开篘荐碧香。","地偏皆斥卤，汲井得甘芳。","漫仕今千室，前人陋一乡。","民安吾亦饱，相乐亦相忘。"]},{"t":"定海四首 其二","f":"五言律诗","c":["齿发今如此，东来料一寒。","爱民平日事，宰县昔人难。","稍得官租办，聊容坐席安。","渠侬趋负挽，疑未厌儿宽。"]},{"t":"定海四首 其一","f":"五言律诗","c":["县境拖脩直，人家住土涂。","三方鲸浪涌，一岛虎头孤。","风物犹佳处，弦歌付老夫。","平生虫篆意，或许间忧虞。"]},{"t":"定海县厅事落成致语口号","f":"七言律诗","c":["翚飞华屋酒如池，宾主风流况一时。","千杖敲春琼斝滑，九霞摇晚舞衫僛。","轻飔泛座漂香远，纤月窥人转影迟。","牛女多情应羡客，瓜华适已罥珠丝。"]},{"t":"念衰","f":"七言律诗","c":["心意彫残底自娱，每临清镜笑头颅。","诗从多病难为好，官过中年劣胜无。","急景驱秋著髭鬓，归鸿衔梦下江湖。","更应载酒高阳伴，误辍歌呼话故吾。"]},{"t":"房州到任交倅事筵致语口号","f":"七言律诗","c":["平时风义等肩差，况此周旋别乘衙。","湛渌徐倾卜夜酒，攲红同插殿春花。","成规灿备堪从事，殊渥便蕃定拜嘉。","烂醉长吟答佳致，不妨宾主各诗家。"]},{"t":"武昌","f":"七言律诗","c":["客子脩程未息肩，江山佳处小留连。","醉临庾亮楼前月，梦闯回翁洞里天。","形势盘萦蹲虎凤，轮蹄隐轸度丝弦。","登高欲赋还东望，楚些无因唤谪仙。"]},{"t":"苦雨再次前韵 其一","f":"七言律诗","c":["席蚓堂蛙岂赵城，崩空急雨未休倾。","青秧可复成坚皂，碧海渠能受浊清。","田舍望秋犹万一，官曹需禄更征营。","宝熏定有回天力，即看朝曦指顾生。"]},{"t":"苦雨再次前韵 其二","f":"七言律诗","c":["底用诗名到凤城，未妨醉帽笑攲倾。","日闻螟蠃讥狂率，目送鲲鹏簉紫清。","谭客有时三不对，生涯除酒一无营。","鸣鞭走送君能断，小印亲封定好生。"]},{"t":"虎丘","f":"七言律诗","c":["长日萧斋类蠹鱼，出门春事半销除。","快舒中散飞鸿眼，稳憩文公卧虎庐。","尘外风光诗笔底，竹梢禅榻茗瓯馀。","归涂定有行人问，底许空青润客裾。"]},{"t":"试柘枝溪上","f":"七言律诗","c":["蕙风花气雨馀天，报答融和玉作船。","壮岁自能鸲鹆舞，老狂犹有柘枝颠。","群鸿翩度昆昭锦，双凤翔从玉井莲。","起我少时豪侠兴，未甘诗客号臞仙。"]},{"t":"试院赠三同官","f":"七言律诗","c":["果饤茶瓯意未阑，独惭衰鬓映朱颜。","聚头长作三更语，屈指惟馀两日闲。","食叶蚕声行入听，探珠骊颔不应悭。","预怜朱墨秋宵永，咫尺灯窗断往还。"]},{"t":"述怀再次韵","f":"七言律诗","c":["高车驷马笑鸡栖，亦笑餔糟与汩泥。","鲁酒得间聊复饮，晋舆投老偶然题。","春冰自水收新悟，雨矢无乡悔旧迷。","尚有平生山水癖，未妨游戏向京西。"]},{"t":"金地寺","f":"五言律诗","c":["侧径崎岖去，飞萝次第扪。","山横欲无地，路转却逢村。","竹柏围荒寺，莓苔上缭垣。","残僧不知客，芋火老云根。"]},{"t":"雨后病起二首 其二","f":"五言律诗","c":["小卧竹间斋，幽怀得好开。","病从凉后减，雨及望时来。","两屩山千叠，诸雏饭一杯。","吾生计此耳，无梦到燕台。"]},{"t":"雨后病起二首 其一","f":"五言律诗","c":["旱岁仍无麦，淮民食正艰。","几时占雨信，今日破天悭。","尽息田家叹，聊开病客颜。","何由长岁稔，金火莫循环。"]},{"t":"饯赵伯卫赵有诗次其韵","f":"七言律诗","c":["雪后垂杨袅绿丝，邮亭折赠诉违离。","明朝月地嗟分影，胜日风流此一时。","白閤论诗成梦境，清湖载酒有心期。","樽前拟倩如椽笔，细与邦人写去思。"]},{"t":"复次韵寄程帅二首 其二","f":"七言律诗","c":["人家禊祓竞攀追，刺史春游正此时。","羯鼓声中花作锦，壶筹多处酒为池。","绝须丝竹娱安石，剩有篇章付雪儿。","闻道续貂容下客，老无佳句坐荒嬉。"]},{"t":"复次韵寄程帅二首 其一","f":"七言律诗","c":["节物匆匆可挽追，直须乐事趁芳时。","行春倏喜花围屋，借景何殊月在池。","对酒不无桃叶女，扣舷却笑木肠儿。","山家有约须重到，定放游人张水嬉。"]},{"t":"复程平叔","f":"七言律诗","c":["早岁雄文手自编，偶同闻喜听钧天。","漫为官去吾何取，肯寄诗来子定贤。","潘岳自怜头易白，士安况苦病相缠。","羡君身健须如漆，万里亨衢稳著鞭。"]},{"t":"客中","f":"五言律诗","c":["多夜淮濒梦，言归未有期。","愁禁客舍雨，寒过杏花时。","酒废无何饮，春如不自持。","若为丹九转，能黑镜中丝。"]},{"t":"客次小憩","f":"七言律诗","c":["竹屋深明许息肩，田家延客解欣然。","霜枝高挂赪虬卵，风砌初摇白玉钱。","得饱祇疑珠作粒，汲深仍诧乳为泉。","谭间更笑狂沮溺，政复知津未是贤。"]},{"t":"客路寄崔帅","f":"七言律诗","c":["笑语生春慰老怀，邹枚端复顾凡才。","酒边徐罢长鲸吸，梦里还惊去鹢催。","野渡水浑妨转柂，霜林寒浅未逢梅。","神驰缥缈凝香地，却惜无人为挽回。"]},{"t":"思归","f":"五言律诗","c":["薄宦随漂梗，流光任迅湍。","家山蝶梦隔，节物雁空寒。","抚事频回首，微吟小凭栏。","多情但乌鹊，时肯报平安。"]},{"t":"春日客中二首 其二","f":"七言律诗","c":["芳时已叹鬓毛斑，何况栖栖客路间。","杯酒故人千里隔，锦囊著语一春闲。","燕莺飞处频回首，桃李香前合厚颜。","昨夜东风贷庭竹，少容归梦到家山。"]},{"t":"春日客中二首 其一","f":"七言律诗","c":["平时谩说醉为乡，对景今如石作肠。","老去犹兴客中叹，春来刚制酒边狂。","露桃烟柳为谁好，蜂蜜燕泥徒自忙。","红紫打围歌笑地，暮年多感怕思量。"]},{"t":"春雨赠陈主管","f":"七言律诗","c":["初宵微月尚窥檐，雨脚斜斜晓入帘。","春谢欢悰风处减，愁将老色镜中添。","颇思甫里陪觞咏，不叹周南更滞淹。","倚赖宗盟慰牢落，得闲诗笔未妨拈。"]},{"t":"春晚郊外","f":"七言律诗","c":["轻云阁雨不成飞，稍喜行轩贷夹衣。","帝里园林春欲老，人家帘幕燕初归。","沧湾潮应沙痕瘦，碧陇烟生麦浪肥。","眼底湖山聊著句，那忧乐事与心违。"]},{"t":"皇孙寿诗二首 其二","f":"七言律诗","c":["曾簉蓬莱挹德风，日亲儒保罄寅恭。","学穷奥阃包贤圣，人仰英明肖祖宗。","綵服近天仍乐孺，帝觞拜赐更从容。","应刘寿语年年事，九万香笺未阙供。"]},{"t":"皇孙寿诗二首 其一","f":"七言律诗","c":["宝祚煌煌羡帝祺，天潢馀润到孙枝。","寿星良月占重见，振古熙朝此一时。","椽笔纪祥芳草颂，龙楼开笑正含饴。","萝图况与乾坤永，长款三宫奉玉卮。"]},{"t":"秋日","f":"五言律诗","c":["梦蚁浪多忧，隙驹如许遒。","凄凉一霜早，黄落万山秋。","得失古青简，漂零予白头。","不因多病过，始觉此生浮。"]},{"t":"贺二石登科","f":"七言律诗","c":["捷音西下亟蜚星，二隽辞锋旧莫京。","桂树前宵减清影，棣华同日擅香名。","谢家兰玉真门户，苏氏文章亦弟兄。","此去提衡霄汉上，鹏抟鲲运更论程。"]},{"t":"贺程帅因任四首且言久缺诗筒之意 其一","f":"七言律诗","c":["恩纶蜚下汉江滨，特许襄民借寇恂。","千里江山皆动色，列城条教再生春。","灌瓜夙稔安边策，茹草宁无待哺民。","方倚金城亲邵父，近君宁惜小逡巡。"]},{"t":"贺程帅因任四首且言久缺诗筒之意 其四","f":"七言律诗","c":["先生一笔将诗坛，庋匮珠玑底坐悭。","平日鸥盟当未慭，于今雁足每空还。","传抄可但闻平水，老瘦从知笑饭山。","缓带轻裘祇常日，千篇破竹定乘闲。"]},{"t":"贺程帅因任四首且言久缺诗筒之意 其三","f":"七言律诗","c":["肯优襄岘劣南徐，行止平时每裕馀。","荷紫端宜冠鸳鹭，飞黄犹似顾蟾蜍。","缅怀夜烛赓清唱，况许春郊载后车。","从此追陪得如愿，重分膏馥泽空虚。"]},{"t":"贺程帅因任四首且言久缺诗筒之意 其二","f":"词","c":["诗律宁惟似变风，姓名久矣御屏中。","逢辰千载合致主，入梦九华仍插空。","铁瓮倚听新号令，铜蹄终舞旧儿童。","烦?叶气成丰岁，却簉皋夔侍舜瞳。"]},{"t":"赵使君淮春楼落成二首 其二","f":"七言律诗","c":["步帐高牙置下方，华筵云影入风裳。","西山爽气珠帘外，北海芳樽锦瑟傍。","宾主前闻无胜事，簪钿明日剩馀香。","一天和气谁拘检，付与邦人作醉乡。"]},{"t":"赵使君淮春楼落成二首 其一","f":"七言律诗","c":["五凤规模到眼中，摘星奇观欲争雄。","客乘云气游三岛，人听歌声指半空。","便拟瑶杯酌银汉，何妨醉面受天风。","胡床不尽登临兴，未觉邦君后庾公。"]},{"t":"送七子赴省","f":"七言律诗","c":["旋转玑衡运化枢，嗣皇袭六待耆儒。","斗南誉望俱难匹，邺下才华旧不孤。","郡赋今推作者并，王庭可但诤臣趋。","竹林昔隐休回首，四辅三公此首涂。"]},{"t":"送人赴试","f":"五言律诗","c":["之子是荆璞，温纯仍琢磨。","诸公推大手，壮岁合贤科。","豹雾三年隐，龙门一跃过。","得诗应自慰，老子阅人多。"]},{"t":"送严上舍并寄诸公十首 其一 送严","f":"五言律诗","c":["啧啧雁声急，棱棱秋意深。","行都旧新雨，独客短长吟。","子肯怜衰病，时来慰滞淫。","惜无移日酒，留照蜡灯斟。"]},{"t":"送严上舍并寄诸公十首","f":"五言律诗","c":["严子老且健，翩然湖外行。","归来困一跌，悲啸念馀生。","幸弃扶衰杖，几成折足铛。","开笼出双鸟，身已御风轻。"]},{"t":"送严上舍并寄诸公十首 其二 寄俞君任府判","f":"五言律诗","c":["交际论才业，何郎种种长。","元推万人敌，况别四年彊。","文看青钱中，诗须古锦藏。","西归容盥读，老境借辉光。"]},{"t":"送严上舍并寄诸公十首 寄何解元","f":"五言律诗","c":["旧识追风足，低摧坂下车。","长驱待云路，小捷已乡书。","唾手须科第，差肩有诏除。","公馀富佳句，记我浑樵渔。"]},{"t":"送严上舍并寄诸公十首 其一 寄张次夔县丞","f":"五言律诗","c":["闻道张夫子，还家俗累轻。","两官终短袖，五字屹长城。","龙断悲人世，烟云写物情。","只今遥夜月，独许伴空明。"]},{"t":"送严上舍并寄诸公十首 其二 送严","f":"五言律诗","c":["自昔金陵幕，周旋未尽能。","凄凉论阀阅，突兀擅声称。","直己堪从事，公言不负丞。","嗣当蜚鹗牍，留眼看依乘。"]},{"t":"送严上舍并寄诸公十首 其二 寄赵景安府判","f":"五言律诗","c":["忆访俞夫子，频烦挽袖留。","酒边无俗物，尘外有高楼。","未醉催歌扇，言归听漏筹。","此欢谁与继，怊怅岁时遒。"]},{"t":"送严上舍并寄诸公十首 其一 寄俞君任府判","f":"五言律诗","c":["暇日诗成集，西来见未曾。","金徽想流水，玉井定层冰。","呵护山灵惜，流传纸价增。","石湖千载托，密密续前灯。"]},{"t":"送严上舍并寄诸公十首 其一 寄赵景安府判","f":"五言律诗","c":["已种河阳柳，将题晋客舆。","论交记曩昔，因使问何如。","拥烬应多暇，援毫不一书。","诗成当属我，拜赐衮褒馀。"]},{"t":"送严上舍并寄诸公十首 其二 寄张次夔县丞","f":"五言律诗","c":["赵子趋吴幕，予偕咏舞雩。","迄今推毂力，不堕拾尘诬。","鬓脚今全白，车轮欲半朱。","何阶答知己，冰檗耐穷涂。"]},{"t":"送张文昌帅豫章二首 其二","f":"七言律诗","c":["谈间宾客重宣州，到后儿童敬细侯。","薤本击彊休领揽，棠阴问俗见风流。","湖连市屋疑丰乐，江绕城闉似石头。","鸥鹭要盟公莫信，江湖祇许半年留。"]},{"t":"送张文昌帅豫章二首 其一","f":"七言律诗","c":["倚俟新年转化钧，昼方三接径抽身。","平时但有凝香梦，盛世那无勇退人。","滕閤宾筵时可醉，金华诗令看重新。","盍思远迩商霖望，不但淮乡有涸鳞。"]},{"t":"送李元英还常熟从周宰读书","f":"五言律诗","c":["久趼寻师足，还家讫受经。","可容轻日力，政使带朝星。","高步须堂奥，它年看典刑。","奉亲时得笑，馀事赐袍青。"]},{"t":"送学生归赴秋试因省别业三首 其三","f":"五言律诗","c":["食口几鹅雁，田收问菜麻。","宁堪再揽减，又抱两呕鸦。","投老怜漂泊，何时了贷赊。","终惭陶靖节，归不计生涯。"]},{"t":"送学生归赴秋试因省别业三首 其二","f":"五言律诗","c":["年事真无赖，官曹已惮烦。","儿堪付门户，吾粗有田园。","游旧因相问，襟怀为细论。","此心归隐计，日日受风幡。"]},{"t":"送学生归赴秋试因省别业三首 其一","f":"五言律诗","c":["凉意苏残梦，催儿起问涂。","功名数前辈，术业旧原夫。","漫触烟楼破，应先老骥驱。","蠲痾吾有待，端不倚岐卢。"]},{"t":"送诗陈惠伯","f":"七言律诗","c":["危楼深室桂为堂，题品端宜虎豹章。","历数诸公皆大手，尚须此老索枯肠。","驰神几夜层虚上，血指如今妙斲傍。","聊复送君供覆瓿，未须传到郑公乡。"]},{"t":"送高缙之归谋武林结课二首 其二","f":"五言律诗","c":["辐辏群英地，皇州异别州。","能文才倚马，作意付焚舟。","士价知名下，医门要担头。","明年春雁足，询我贺书邮。"]},{"t":"送高缙之归谋武林结课二首 其一","f":"五言律诗","c":["眼底论人物，如君亦壮哉。","作书犹乞米，造物不怜才。","跋履妨诗笔，祛除近酒杯。","飞尘栖剑室，归棹莫迟回。"]},{"t":"送臧汝舟楚州秋试","f":"七言律诗","c":["羡杀君家有两方，阿戎材干更昂藏。","久知笔力能扛鼎，此去贤书定探囊。","邻近玉渊尝借润，眼中珠树看争芳。","旧陪众俊工飞动，老气因君尚激昂。"]},{"t":"郝泽民主簿赠诗次韵二首 其二","f":"七言律诗","c":["薄宦年来尚转蓬，忍将荣悴问虚中。","共怜杜老谙为客，不讶元忠厌作公。","胜日笑谭方衮衮，残冬光景苦匆匆。","棋枰得隽诗反水，谁信吾徒旧讳穷。"]},{"t":"郝泽民主簿赠诗次韵二首 其一","f":"七言律诗","c":["夫君糠秕视钱神，诗逼黄初论借秦。","义槩咸推天下士，簿曹聊见宰官身。","茶香延客自不饱，书币踵门谁可人。","从古功名多晚节，相逢双鬓未妨新。"]}]};